def _normalized(paths: list[str]) -> list[str]:
    out: list[str] = []
    for path in paths:
        if os.path.isabs(path):
            out.append(os.path.normpath(os.path.abspath(path)))
        else:
            out.append(os.path.normpath(os.path.abspath(os.path.join(ROOT, path))))
    return out


def _path_tail(path: object) -> str:
    return os.path.basename(str(path).replace("\\", os.sep).replace("/", os.sep))


def _exif_user_comment(path: str) -> str:
    raw = piexif.load(path).get("Exif", {}).get(piexif.ExifIFD.UserComment)
    return piexif.helper.UserComment.load(raw) if raw else ""


def _api_image_base64(image, infotext: str = "") -> str:
    from PIL import PngImagePlugin

    buffer = io.BytesIO()
    metadata = None
    if infotext:
        metadata = PngImagePlugin.PngInfo()
        metadata.add_text("parameters", infotext)
    image.save(buffer, format="PNG", pnginfo=metadata)
    return base64.b64encode(buffer.getvalue()).decode("ascii")


def _rmtree_force(path: os.PathLike | str) -> None:
    target = Path(path)
    if not target.exists():
        return
    for item in sorted(target.rglob("*"), key=lambda value: len(value.parts), reverse=True):
        try:
            item.chmod(0o700 if item.is_dir() else 0o600)
        except OSError:
            pass
    try:
        target.chmod(0o700)
    except OSError:
        pass
    shutil.rmtree(target)


