class TestForgeNeoContract(unittest.TestCase):
    def test_qwen21_multi_image_edit_request_and_ui_defaults(self):
        from PIL import Image
        from forge_neo import ui
        from forge_neo.runtime import ForgeNeoRequest
        from forge_neo.runtime_backend import source_api_payload, source_runtime_child

        request = ForgeNeoRequest(
            mode="img2img",
            preset="qwen21",
            init_image=Image.new("RGB", (64, 64), "red"),
            image_stitch_enabled=True,
            image_stitch_references=[
                Image.new("RGB", (64, 64), "green"),
                Image.new("RGB", (64, 64), "blue"),
            ],
            image_stitch_max_dim=512,
        )
        payload = source_api_payload(request)["payload"]
        args = payload["alwayson_scripts"]["ImageStitch Integrated"]["args"]
        self.assertTrue(args[0])
        self.assertEqual(len(args[1]), 2)
        self.assertEqual(args[2], 512)
        colors = [Image.open(io.BytesIO(base64.b64decode(encoded))).convert("RGB").getpixel((0, 0)) for encoded in args[1]]
        self.assertEqual(colors, [(0, 128, 0), (0, 0, 255)])
        self.assertEqual(len(payload["init_images"]), 1)

        script = types.SimpleNamespace(alwayson=True, title=lambda: "ImageStitch Integrated")
        runner = types.SimpleNamespace(scripts=[script], selectable_scripts=[], alwayson_scripts=[script])
        source_runtime_child._assign_source_script_api_ranges(runner)
        self.assertEqual([control.value for control in script.controls], [False, [], 1024])
        with mock.patch.object(source_runtime_child, "_ensure_source_image_stitch_script", return_value={"loaded": True}) as ensure:
            adapter_scripts = source_runtime_child._ensure_source_adapter_scripts({"imagestitch integrated"}, types.SimpleNamespace(scripts=[]))
        ensure.assert_called_once_with()
        self.assertTrue(adapter_scripts["image_stitch"]["loaded"])

        self.assertEqual(ui._preset_img2img_denoising_strength("qwen21"), 1.0)
        self.assertEqual(ui._preset_img2img_denoising_strength("anima"), 0.6)
        content = Path(ROOT, "forge_neo", "ui.py").read_text(encoding="utf-8")
        self.assertIn("value=_preset_img2img_denoising_strength(default_preset)", content)
        self.assertIn("img_distilled_cfg_scale,\n                img_denoising_strength,\n                img_batch_size,", content)

