    def test_forge_neo_entry_local_proxy_bypass_contract(self):
        entry_path = Path(ROOT, "webui-forge-neo.py")
        previous_env = {key: os.environ.get(key) for key in ("NO_PROXY", "no_proxy")}
        module_name = "webui_forge_neo_proxy_contract"
        try:
            for key in ("NO_PROXY", "no_proxy"):
                os.environ.pop(key, None)
            os.environ["NO_PROXY"] = "example.com;localhost"
            spec = importlib.util.spec_from_file_location(module_name, entry_path)
            self.assertIsNotNone(spec)
            self.assertIsNotNone(spec.loader)
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)

            for key in ("NO_PROXY", "no_proxy"):
                values = os.environ[key].split(",")
                self.assertIn("127.0.0.1", values)
                self.assertIn("localhost", values)
                self.assertIn("::1", values)
                self.assertEqual(values.count("localhost"), 1)

            self.assertTrue(os.environ["NO_PROXY"].startswith("example.com,localhost"))
            self.assertIn("def _ensure_local_proxy_bypass(", entry_path.read_text(encoding="utf-8"))

            os.environ["no_proxy"] = "localhost,127.0.0.1,::1"
            module._ensure_local_proxy_bypass()
            self.assertEqual(os.environ["no_proxy"], "localhost,127.0.0.1,::1")
        finally:
            for key, value in previous_env.items():
                if value is None:
                    os.environ.pop(key, None)
                else:
                    os.environ[key] = value
            sys.modules.pop(module_name, None)

