    def test_forge_neo_shared_token_defaults_to_local_stub(self):
        import builtins
        import shared
        from forge_neo import bootstrap

        previous_token = getattr(shared, "token", None)
        previous_env = {
            key: os.environ.get(key)
            for key in (
                "FORGE_NEO_TEST_TOKEN_STUB",
                "FORGE_NEO_TOKEN_STUB",
                "FORGE_NEO_DISABLE_SIMPLEAI_BASE",
                "FORGE_NEO_USE_SIMPLEAI_BASE",
            )
        }
        real_import = builtins.__import__

        def guarded_import(name, globals=None, locals=None, fromlist=(), level=0):
            if name == "simpleai_base" or name.startswith("simpleai_base."):
                raise AssertionError("ensure_shared_token local mode must not import simpleai_base")
            return real_import(name, globals, locals, fromlist, level)

        try:
            for key in previous_env:
                os.environ.pop(key, None)
            shared.token = None
            builtins.__import__ = guarded_import
            bootstrap.ensure_shared_token()
            token = shared.token
            config_source = Path(ROOT, "modules", "config.py").read_text(encoding="utf-8")
            self.assertIsInstance(token, bootstrap._ForgeNeoTokenStub)
            self.assertEqual(token.get_default_workspace_did(), "forge_neo_local")
            self.assertEqual(token.get_guest_did(), "forge_neo_guest")
            self.assertEqual(token.get_admin_did(), "")
            self.assertEqual(token.get_node_mode(), "local")
            self.assertTrue(getattr(token, "skip_default_outputs_init", False))
            self.assertTrue(getattr(token, "read_only_user_config", False))
            self.assertIn('getattr(shared.token, "skip_default_outputs_init", False)', config_source)
            self.assertIn('forge_neo_read_only_user_config = bool(getattr(args_manager.args, "forge_neo_read_only_user_config", False))', config_source)
            self.assertIn('if not forge_neo_read_only_user_config and (not os.path.exists(config_path) or config_needs_write):', config_source)
            self.assertIn('if not forge_neo_read_only_user_config:', config_source)
            self.assertIn("def _default_user_base_dir() -> str:", Path(ROOT, "forge_neo", "bootstrap.py").read_text(encoding="utf-8"))
            self.assertNotEqual(os.path.normcase(os.path.abspath(getattr(token, "base_dir", ""))), os.path.normcase(os.path.join(ROOT, "users")))
            self.assertTrue(token.can_user_generate(token.get_guest_did()))
            self.assertTrue(token.can_user_download_models(token.get_guest_did()))
            session = token.get_guest_sstoken("ua-hash")
            self.assertEqual(token.check_sstoken_and_get_did(session, "ua-hash"), token.get_guest_did())
            token.set_local_vars("user_presets", "klein", session, "ua-hash")
            self.assertEqual(token.get_local_vars("user_presets", "", session, "ua-hash"), "klein")
            with tempfile.TemporaryDirectory(prefix="forge_neo_token_outputs_") as tmp:
                token.set_user_base_dir(tmp)
                outputs_path = token.get_path_in_user_dir(token.get_default_workspace_did(), "outputs")
                self.assertEqual(os.path.normcase(outputs_path), os.path.normcase(os.path.join(tmp, "ForgeNeo")))
                self.assertFalse(os.path.exists(outputs_path))
                self.assertNotIn("forge_neo_local", os.path.normcase(outputs_path))
        finally:
            builtins.__import__ = real_import
            shared.token = previous_token
            for key, value in previous_env.items():
                if value is None:
                    os.environ.pop(key, None)
                else:
                    os.environ[key] = value

        with open(os.path.join(ROOT, "forge_neo", "bootstrap.py"), "r", encoding="utf-8") as f:
            content = f.read()
        self.assertIn("FORGE_NEO_USE_SIMPLEAI_BASE", content)
        self.assertIn("FORGE_NEO_DISABLE_SIMPLEAI_BASE", content)
        self.assertIn("simpleai_base.init_local()", content)
        self.assertIn("def ensure_user_config_model_root_from_launch", content)

    def test_forge_neo_bootstrap_seeds_models_root_config_before_read_only_import(self):
        import args_manager
        from forge_neo import bootstrap

        previous_userhome = getattr(args_manager.args, "userhome_path", None)
        previous_models_root = getattr(args_manager.args, "models_root", None)
        try:
            with tempfile.TemporaryDirectory(prefix="forge_neo_models_root_config_") as tmp:
                user_home = Path(tmp) / "users"
                args_manager.args.userhome_path = str(user_home)
                args_manager.args.models_root = "../../SimpleModels"

                config_path = bootstrap.ensure_user_config_model_root_from_launch()

                self.assertTrue(os.path.samefile(config_path, user_home / "config.txt"))
                config = json.loads((user_home / "config.txt").read_text(encoding="utf-8"))
                self.assertEqual(config["path_models_root"], "../../SimpleModels")

                args_manager.args.models_root = "../../OtherModels"
                bootstrap.ensure_user_config_model_root_from_launch()
                config = json.loads((user_home / "config.txt").read_text(encoding="utf-8"))
                self.assertEqual(config["path_models_root"], "../../SimpleModels")
        finally:
            args_manager.args.userhome_path = previous_userhome
            args_manager.args.models_root = previous_models_root

    def test_sdapi_read_metadata_source_shape_contract(self):
        from forge_neo import api

        samplers = {row["name"]: row for row in api.samplers_payload()}
        self.assertEqual(samplers["DPM++ 2M"]["aliases"], ["k_dpmpp_2m"])
        self.assertEqual(samplers["DPM++ 2M"]["options"], {"scheduler": "karras"})
        self.assertEqual(samplers["Euler a"]["aliases"], ["k_euler_a", "k_euler_ancestral"])
        self.assertEqual(samplers["Euler a"]["options"], {"uses_ensd": True})
        self.assertEqual(
            samplers["DPM++ 3M SDE"]["options"],
            {"scheduler": "exponential", "discard_next_to_last_sigma": True, "brownian_noise": True},
        )

        schedulers = api.schedulers_payload()
        self.assertEqual(
            schedulers[0],
            {"name": "automatic", "label": "Automatic", "aliases": None, "default_rho": -1.0, "need_inner_model": False},
        )
        karras = next(row for row in schedulers if row["label"] == "Karras")
        self.assertEqual(karras, {"name": "karras", "label": "Karras", "aliases": None, "default_rho": 7.0, "need_inner_model": False})
        self.assertEqual(next(row for row in schedulers if row["label"] == "SGM Uniform")["aliases"], ["SGMUniform"])
        self.assertFalse(next(row for row in schedulers if row["label"] == "Flux2")["need_inner_model"])

        latent_modes = [row["name"] for row in api.latent_upscale_modes_payload()]
        self.assertEqual(
            latent_modes,
            [
                "Latent",
                "Latent (antialiased)",
                "Latent (bicubic)",
                "Latent (bicubic antialiased)",
                "Latent (nearest)",
                "Latent (nearest-exact)",
            ],
        )

    def test_sdapi_progress_source_shape_contract(self):
        from forge_neo.api import progress_payload, sdapi_progress_payload
        from forge_neo.worker import worker

        worker.reset()
        try:
            payload = sdapi_progress_payload(skip_current_image=True)
            self.assertEqual(set(payload), {"progress", "eta_relative", "state", "current_image", "textinfo"})
            self.assertIn("current_image", payload)
            self.assertIsNone(payload["current_image"])
            self.assertIsNone(payload["textinfo"])
            self.assertIn("job_timestamp", payload["state"])
            self.assertIsInstance(payload["state"]["job_timestamp"], str)
            self.assertTrue(payload["state"]["job_timestamp"])
            self.assertNotIn("status", payload["state"])
            self.assertNotIn("current_task", payload)
            self.assertNotIn("live_preview_refresh_period", payload)

            live_payload = sdapi_progress_payload(skip_current_image=False, id_live_preview=0)
            self.assertEqual(set(live_payload), {"progress", "eta_relative", "state", "current_image", "textinfo"})
            self.assertIn("current_image", live_payload)
            self.assertIsNone(live_payload["current_image"])
            self.assertNotIn("id_live_preview", live_payload)

            neo_payload = progress_payload(skip_current_image=True)
            self.assertIn("current_task", neo_payload)
            self.assertIn("live_preview_refresh_period", neo_payload)
        finally:
            worker.unload_runtime_state()

