    def test_forge_neo_language_toggle_contract(self):
        import args_manager
        from forge_neo.restart import ensure_server_state
        from forge_neo.ui import _language_changed, _runtime_marker_html

        server_state = ensure_server_state()
        old_language = getattr(args_manager.args, "language", "cn")
        old_command = server_state.server_command
        old_interrupted = server_state.interrupted
        try:
            server_state.server_command = None
            server_state.interrupted = False
            next_state, marker = _language_changed("en", {"__lang": "cn"})
            self.assertEqual(next_state["__lang"], "en")
            self.assertEqual(next_state["app"], "forge_neo")
            self.assertEqual(args_manager.args.language, "en")
            self.assertEqual(server_state.server_command, "restart")
            self.assertIn('data-lang="en"', marker["value"])
            self.assertIn('data-lang="cn"', _runtime_marker_html("zh_CN"))
        finally:
            args_manager.args.language = old_language
            server_state.server_command = old_command
            server_state.interrupted = old_interrupted

