    def test_backend_reference_map_and_adapter_gate_contract(self):
        import args_manager
        from PIL import Image
        from forge_neo.runtime_backend import adapter
        from forge_neo import runtime

        capabilities = adapter.backend_capabilities()
        reference_roots = " ".join(row["root"] for row in capabilities["reference"]["roots"])
        self.assertEqual(capabilities["reference"]["roots"], [])
        self.assertEqual(capabilities["reference"]["entrypoints"], [])
        self.assertNotIn("sd-webui-forge-classic", reference_roots)
        self.assertNotIn("sd-webui-forge-neo-v3", reference_roots)
        self.assertEqual(capabilities["adapter"], "source_backend_runtime")
        self.assertEqual(capabilities["source_api_bridge"]["adapter"], "source_api")
        self.assertEqual(capabilities["source_api_bridge"]["route"], "modules/api/api.py -> modules/processing.py -> process_images")
        self.assertEqual(capabilities["source_api_bridge"]["auto_env"], "FORGE_NEO_BACKEND_ADAPTER=auto")
        self.assertNotIn("*", capabilities["source_api_bridge"]["auto_presets"])
        self.assertIn("*", capabilities["source_backend_runtime"]["auto_presets"])
        self.assertFalse(capabilities["target"]["native_forge_ready"])
        self.assertTrue(capabilities["target"]["simpai_async_worker_ready"])

        preview = adapter.build_simpai_async_preview(
            runtime.ForgeNeoRequest(
                prompt="adapter smoke",
                checkpoint="z_image_turbo_bf16.safetensors",
                width=832,
                height=1216,
                steps=1,
                seed=198,
            )
        )
        self.assertTrue(preview["ok"], preview)
        task_preview = preview["preview"]["task_object_preview"]
        self.assertEqual(task_preview["task_class"], "Z-image")
        self.assertEqual(task_preview["task_method"], "z_image_turbo_aio_cn")
        self.assertEqual(task_preview["base_model_name"], "z_image_turbo_bf16.safetensors")

        old_disable_backend = adapter.args_manager.args.disable_backend
        old_adapter = adapter.run_backend_generation
        try:
            adapter.args_manager.args.disable_backend = False

            def fake_backend(request, progress_callback=None, control_callback=None):
                return runtime.ForgeNeoResult(
                    images=[Image.new("RGB", (8, 8), (1, 2, 3))],
                    infotext="adapter result",
                    seed=198,
                    status="finished",
                )

            adapter.run_backend_generation = fake_backend
            result = runtime.generate(runtime.ForgeNeoRequest(prompt="adapter delegated", steps=1, seed=198))
            self.assertEqual(result.status, "finished")
            self.assertEqual(result.infotext, "adapter result")
            self.assertEqual(len(result.images), 1)
        finally:
            adapter.run_backend_generation = old_adapter
            adapter.args_manager.args.disable_backend = old_disable_backend

