    def test_source_backend_lora_registry_refresh_contract(self):
        from forge_neo.runtime_backend import source_runtime_child

        calls: list[tuple[str, list[str] | None]] = []
        events: list[dict[str, object]] = []
        fake_networks = types.ModuleType("networks")
        fake_networks.available_networks = {}
        fake_networks.available_network_aliases = {}
        fake_networks.forbidden_network_aliases = {"none", "Addams"}

        class Entry:
            name = "111可爱的画风sky02Light"
            alias = "skyv1"
            filename = r"I:\dev2\New_SimpAI\SimpleModels\loras\111可爱的画风sky02Light.safetensors"

        def update_available_networks_by_names(names):
            calls.append(("by_name", list(names)))

        def list_available_networks():
            calls.append(("full", None))
            entry = Entry()
            fake_networks.available_networks[entry.name] = entry
            fake_networks.available_network_aliases[entry.name] = entry
            fake_networks.available_network_aliases[entry.alias] = entry

        fake_networks.update_available_networks_by_names = update_available_networks_by_names
        fake_networks.list_available_networks = list_available_networks
        old_networks = sys.modules.get("networks")
        old_emit = source_runtime_child._emit_event
        try:
            sys.modules["networks"] = fake_networks
            source_runtime_child._emit_event = lambda event: events.append(event)
            result = source_runtime_child._refresh_source_loras_for_payload({"prompt": "cute <lora:skyv1:1>"})
        finally:
            source_runtime_child._emit_event = old_emit
            if old_networks is None:
                sys.modules.pop("networks", None)
            else:
                sys.modules["networks"] = old_networks

        self.assertEqual(result["requested"], ["skyv1"])
        self.assertEqual(result["missing"], [])
        self.assertTrue(result["refreshed_by_name"])
        self.assertTrue(result["refreshed_full_list"])
        self.assertEqual(calls, [("by_name", ["skyv1"]), ("full", None)])
        self.assertEqual(result["resolved"][0]["name"], "111可爱的画风sky02Light")
        self.assertEqual(result["resolved"][0]["alias"], "skyv1")
        self.assertEqual(result["resolved"][0]["basename"], "111可爱的画风sky02Light.safetensors")
        self.assertEqual(events[-1]["message_cn"], "源后端 LoRA 注册表已检查")

    def test_source_backend_registers_lora_extra_network_contract(self):
        from forge_neo.runtime_backend import source_runtime_child

        calls: list[str] = []
        fake_modules = types.ModuleType("modules")
        fake_extra_networks = types.ModuleType("modules.extra_networks")
        fake_extra_networks.extra_network_registry = {}

        def register_extra_network(extra_network):
            calls.append(str(extra_network.name))
            fake_extra_networks.extra_network_registry[extra_network.name] = extra_network

        fake_extra_networks.register_extra_network = register_extra_network
        fake_extra_networks_lora = types.ModuleType("extra_networks_lora")

        class FakeExtraNetworkLora:
            name = "lora"

        fake_extra_networks_lora.ExtraNetworkLora = FakeExtraNetworkLora
        fake_networks = types.ModuleType("networks")
        old_modules = sys.modules.get("modules")
        old_modules_extra_networks = sys.modules.get("modules.extra_networks")
        old_extra_networks_lora = sys.modules.get("extra_networks_lora")
        old_networks = sys.modules.get("networks")
        try:
            fake_modules.extra_networks = fake_extra_networks
            sys.modules["modules"] = fake_modules
            sys.modules["modules.extra_networks"] = fake_extra_networks
            sys.modules["extra_networks_lora"] = fake_extra_networks_lora
            sys.modules["networks"] = fake_networks
            result = source_runtime_child._ensure_source_lora_extra_network_registered()
            second_result = source_runtime_child._ensure_source_lora_extra_network_registered()
        finally:
            for name, old_value in (
                ("modules", old_modules),
                ("modules.extra_networks", old_modules_extra_networks),
                ("extra_networks_lora", old_extra_networks_lora),
                ("networks", old_networks),
            ):
                if old_value is None:
                    sys.modules.pop(name, None)
                else:
                    sys.modules[name] = old_value

        self.assertTrue(result["changed"])
        self.assertTrue(result["lora_registered"])
        self.assertEqual(result["registered"], ["lora"])
        self.assertEqual(calls, ["lora"])
        self.assertIs(fake_networks.extra_network_lora, fake_extra_networks.extra_network_registry["lora"])
        self.assertFalse(second_result["changed"])
        self.assertTrue(second_result["lora_registered"])

