    def test_source_api_auto_route_contract(self):
        from forge_neo.runtime_backend import adapter
        from forge_neo.runtime import ForgeNeoRequest, ForgeNeoResult

        old_disable_backend = adapter.args_manager.args.disable_backend
        old_env = os.environ.get("FORGE_NEO_BACKEND_ADAPTER")
        old_auto_source_presets = os.environ.get("FORGE_NEO_AUTO_SOURCE_API_PRESETS")
        old_auto_source_backend_presets = os.environ.get("FORGE_NEO_AUTO_SOURCE_BACKEND_PRESETS")
        old_native = adapter.run_native_processing
        old_source = adapter.run_source_api_processing
        old_source_backend = adapter.run_source_backend_processing
        try:
            adapter.args_manager.args.disable_backend = False
            os.environ["FORGE_NEO_AUTO_SOURCE_API_PRESETS"] = "anima"
            adapter.run_native_processing = lambda request, progress_callback=None, control_callback=None: ForgeNeoResult(
                status="finished",
                infotext=f"native:{getattr(request, 'preset', '')}",
            )
            adapter.run_source_api_processing = lambda request, progress_callback=None, control_callback=None: ForgeNeoResult(
                status="finished",
                infotext=f"source:{getattr(request, 'preset', '')}",
            )
            adapter.run_source_backend_processing = lambda request, progress_callback=None, control_callback=None: ForgeNeoResult(
                status="finished",
                infotext=f"backend:{getattr(request, 'preset', '')}",
            )

            os.environ.pop("FORGE_NEO_BACKEND_ADAPTER", None)
            self.assertEqual(adapter.run_backend_generation(ForgeNeoRequest(preset="xl", checkpoint="xl-model.safetensors", steps=1)).infotext, "backend:xl")
            self.assertEqual(adapter.run_backend_generation(ForgeNeoRequest(preset="anima", checkpoint="anima-base-v1.0.safetensors", steps=1)).infotext, "backend:anima")

            os.environ["FORGE_NEO_BACKEND_ADAPTER"] = "auto"
            self.assertEqual(adapter.run_backend_generation(ForgeNeoRequest(checkpoint="custom-anima-model.safetensors", steps=1)).infotext, "backend:klein")

            os.environ["FORGE_NEO_AUTO_SOURCE_BACKEND_PRESETS"] = ""
            self.assertEqual(adapter.run_backend_generation(ForgeNeoRequest(preset="anima", checkpoint="anima-base-v1.0.safetensors", steps=1)).infotext, "source:anima")

            os.environ["FORGE_NEO_BACKEND_ADAPTER"] = "native"
            self.assertEqual(adapter.run_backend_generation(ForgeNeoRequest(preset="anima", checkpoint="anima-base-v1.0.safetensors", steps=1)).infotext, "native:anima")

            os.environ["FORGE_NEO_AUTO_SOURCE_API_PRESETS"] = ""
            os.environ["FORGE_NEO_BACKEND_ADAPTER"] = "auto"
            self.assertEqual(adapter.run_backend_generation(ForgeNeoRequest(preset="anima", checkpoint="anima-base-v1.0.safetensors", steps=1)).infotext, "native:anima")
        finally:
            adapter.run_native_processing = old_native
            adapter.run_source_api_processing = old_source
            adapter.run_source_backend_processing = old_source_backend
            adapter.args_manager.args.disable_backend = old_disable_backend
            if old_env is None:
                os.environ.pop("FORGE_NEO_BACKEND_ADAPTER", None)
            else:
                os.environ["FORGE_NEO_BACKEND_ADAPTER"] = old_env
            if old_auto_source_presets is None:
                os.environ.pop("FORGE_NEO_AUTO_SOURCE_API_PRESETS", None)
            else:
                os.environ["FORGE_NEO_AUTO_SOURCE_API_PRESETS"] = old_auto_source_presets
            if old_auto_source_backend_presets is None:
                os.environ.pop("FORGE_NEO_AUTO_SOURCE_BACKEND_PRESETS", None)
            else:
                os.environ["FORGE_NEO_AUTO_SOURCE_BACKEND_PRESETS"] = old_auto_source_backend_presets

        source = Path(ROOT, "forge_neo", "runtime_backend", "adapter.py").read_text(encoding="utf-8")
        self.assertIn('os.environ.get("FORGE_NEO_BACKEND_ADAPTER", "auto")', source)
        self.assertIn("def auto_source_api_preferred(", source)
        self.assertIn("def auto_source_backend_preferred(", source)
        self.assertIn("return run_source_backend_processing(request, progress_callback=progress_callback, control_callback=control_callback)", source)
        self.assertIn("return run_source_api_processing(request, progress_callback=progress_callback, control_callback=control_callback)", source)

        stage_report_path = Path(ROOT, "reports", "forge-neo-stage478-source-api-auto-route.json")
        self.assertTrue(stage_report_path.is_file())
        stage_report = json.loads(stage_report_path.read_text(encoding="utf-8"))
        self.assertEqual(stage_report["stage"], 478)
        self.assertEqual(stage_report["adapter_stage"], "source_api_auto_route")
        self.assertIn("test_source_api_auto_route_contract", stage_report["contracts"])

    def test_source_backend_direct_folder_contract(self):
        from forge_neo import source_backend_manifest

        backend_root = Path(ROOT) / "forge_neo" / "webui"
        legacy_mirror_root = Path(ROOT) / "forge_neo" / "source_backend_mirror"
        manifest_path = backend_root / "manifest.json"
        self.assertTrue(manifest_path.is_file())
        self.assertFalse(legacy_mirror_root.exists())
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        source_root = Path(manifest["source_root"])
        target_root = Path(manifest["target_root"])
        self.assertEqual(manifest["stage"], source_backend_manifest.SOURCE_BACKEND_STAGE)
        self.assertEqual(source_root, backend_root)
        self.assertEqual(target_root, backend_root)
        self.assertNotIn("sd-webui-forge-neo-v3", manifest["source_root"])
        self.assertNotIn("sd-webui-forge-neo-v3", manifest["target_root"])
        self.assertTrue((source_root / "backend").is_dir())
        self.assertTrue(manifest["source_commit"])
        self.assertGreaterEqual(manifest["file_count"], 313)
        self.assertEqual(source_backend_manifest.SOURCE_BACKEND_DIR, backend_root)
        self.assertIn("backend", source_backend_manifest.SOURCE_BACKEND_DIRS)
        self.assertIn("launch.py", source_backend_manifest.SOURCE_BACKEND_ROOT_FILES)
        self.assertIn("modules/processing.py", source_backend_manifest.SOURCE_MODULE_FILES)
        self.assertIn("backend/loader.py", source_backend_manifest.SOURCE_BACKEND_LOCAL_PATCH_FILES)
        self.assertNotIn("backend/loader.py", source_backend_manifest.SOURCE_BACKEND_HASH_CHECKS)
        self.assertIn("modules/processing.py", source_backend_manifest.SOURCE_BACKEND_LOCAL_PATCH_FILES)
        self.assertNotIn("modules/processing.py", source_backend_manifest.SOURCE_BACKEND_HASH_CHECKS)
        self.assertIn("modules_forge/patch_basic.py", source_backend_manifest.SOURCE_BACKEND_LOCAL_PATCH_FILES)
        self.assertIn("modules/sd_samplers_kdiffusion.py", source_backend_manifest.SOURCE_MODULE_FILES)
        self.assertTrue((backend_root / "launch.py").is_file())
        self.assertTrue((backend_root / "backend" / "loader.py").is_file())
        self.assertTrue((backend_root / "backend" / "sampling" / "sampling_function.py").is_file())
        self.assertTrue((backend_root / "modules" / "processing.py").is_file())

        def digest(path: Path) -> str:
            value = hashlib.sha256()
            with path.open("rb") as handle:
                for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                    value.update(chunk)
            return value.hexdigest()

        for relative in source_backend_manifest.SOURCE_BACKEND_HASH_CHECKS:
            source_path = source_root / relative
            target_path = source_backend_manifest.source_backend_target_path(backend_root, relative)
            self.assertTrue(source_path.is_file(), relative)
            self.assertTrue(target_path.is_file(), relative)
            self.assertEqual(digest(target_path), digest(source_path), relative)

        script = Path(ROOT, "tools", "forge_neo_sync_source_backend.py").read_text(encoding="utf-8")
        self.assertIn("SOURCE_BACKEND_DIRS", script)
        self.assertIn("SOURCE_BACKEND_ROOT_FILES", script)
        self.assertIn("SOURCE_MODULE_FILES", script)
        self.assertIn("SOURCE_BACKEND_LOCAL_PATCH_FILES", script)
        self.assertIn("source_backend_target_relative", script)
        self.assertIn("shutil.copy2(source, target)", script)
        self.assertIn("manifest.json", script)

        stage_report_path = Path(ROOT, "reports", "forge-neo-stage481-source-backend-direct-folder.json")
        self.assertTrue(stage_report_path.is_file())
        stage_report = json.loads(stage_report_path.read_text(encoding="utf-8"))
        self.assertEqual(stage_report["stage"], 481)
        self.assertEqual(stage_report["backend_stage"], "source_backend_direct_folder")
        self.assertIn("test_source_backend_direct_folder_contract", stage_report["contracts"])

    def test_source_backend_huggingface_tokenizer_startup_contract(self):
        module_path = Path(ROOT, "forge_neo", "webui", "backend", "huggingface", "__init__.py")
        content = module_path.read_text(encoding="utf-8")
        self.assertIn("def decompress_tokenizer_if_available(", content)
        self.assertIn("if not os.path.isfile(source):", content)
        self.assertIn("os.makedirs(os.path.dirname(target), exist_ok=True)", content)

        spec = importlib.util.spec_from_file_location("forge_neo_huggingface_tokenizer_contract", module_path)
        self.assertIsNotNone(spec)
        self.assertIsNotNone(spec.loader)
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)

        with tempfile.TemporaryDirectory() as tempdir:
            root = Path(tempdir)
            raw_tokenizer = root / "tokenizer.json"
            raw_bytes = b'{"contract":"anima-tokenizer"}'
            raw_tokenizer.write_bytes(raw_bytes)
            compressed = root / "z.tokenizer.json.xz"
            module.compress(str(raw_tokenizer), str(compressed))
            expected_hash = hashlib.sha256(raw_bytes).hexdigest()

            module.sha256.z = expected_hash
            module.sha256.f2 = expected_hash
            module.Token.wan_compress = str(root / "missing" / "wan.tokenizer.json.xz")
            module.Token.wan_t2v = str(root / "Wan-AI" / "Wan2.1-T2V-14B" / "tokenizer" / "tokenizer.json")
            module.Token.wan_i2v = str(root / "Wan-AI" / "Wan2.1-I2V-14B" / "tokenizer" / "tokenizer.json")
            module.Token.neta_compress = str(root / "missing" / "neta.tokenizer.json.xz")
            module.Token.neta_lumina = str(root / "neta-art" / "Neta-Lumina" / "tokenizer" / "tokenizer.json")
            module.Token.z_compress = str(compressed)
            module.Token.z_image = str(root / "Tongyi-MAI" / "Z-Image-Turbo" / "tokenizer" / "tokenizer.json")
            module.Token.f2_4b = str(root / "black-forest-labs" / "FLUX.2-klein-4B" / "tokenizer" / "tokenizer.json")
            module.Token.f2_9b = str(root / "black-forest-labs" / "FLUX.2-klein-9B" / "tokenizer" / "tokenizer.json")
            module.Token.anima = str(root / "circlestone-labs" / "Anima" / "tokenizer" / "tokenizer.json")
            module.Token.ernie_compress = str(root / "missing" / "ernie.tokenizer.json.xz")
            module.Token.ernie = str(root / "baidu" / "ERNIE-Image" / "tokenizer" / "tokenizer.json")

            module.process()

            self.assertFalse(Path(module.Token.wan_t2v).exists())
            self.assertFalse(Path(module.Token.wan_i2v).exists())
            self.assertFalse(Path(module.Token.ernie).exists())
            self.assertEqual(Path(module.Token.anima).read_bytes(), raw_bytes)
            self.assertEqual(Path(module.Token.z_image).read_bytes(), raw_bytes)
            self.assertEqual(Path(module.Token.f2_4b).read_bytes(), raw_bytes)
            self.assertEqual(Path(module.Token.f2_9b).read_bytes(), raw_bytes)

    def test_source_backend_comfy_kitchen_rope_split_half_contract(self):
        import torch
        import comfy_kitchen as ck

        patch_path = Path(ROOT, "forge_neo", "webui", "modules_forge", "patch_basic.py")
        content = patch_path.read_text(encoding="utf-8")
        forge_launch_source = Path(ROOT, "forge_neo", "webui", "modules", "launch_utils.py").read_text(encoding="utf-8")
        source_runtime = Path(ROOT, "forge_neo", "runtime_backend", "source_runtime.py").read_text(encoding="utf-8")
        self.assertIn("def patch_comfy_kitchen_rope_split_half(", content)
        self.assertIn("ck.apply_rope_split_half = apply_rope_split_half", content)
        self.assertIn("patch_comfy_kitchen_rope_split_half()", content)
        self.assertIn("comfy-kitchen==0.2.38", Path(ROOT, "requirements.txt").read_text(encoding="utf-8"))
        self.assertIn("('comfy-kitchen', '0.2.38', None)", Path(ROOT, "launch.py").read_text(encoding="utf-8"))
        self.assertIn("comfy-kitchen==0.2.38", Path(ROOT, "comfy", "requirements.txt").read_text(encoding="utf-8"))
        self.assertIn('("comfy-kitchen", "0.2.38", None)', forge_launch_source)
        self.assertIn('("comfy-kitchen", "0.2.38"),', source_runtime)
        self.assertIn("_ensure_source_backend_bootstrap_packages(python_executable)", source_runtime)

        old_sys_path = list(sys.path)
        old_modules = sys.modules.get("modules")
        old_modules_errors = sys.modules.get("modules.errors")
        previous = getattr(ck, "apply_rope_split_half", None)
        had_previous = hasattr(ck, "apply_rope_split_half")
        try:
            if had_previous:
                delattr(ck, "apply_rope_split_half")
            modules_stub = types.ModuleType("modules")
            modules_stub.__path__ = [str(Path(ROOT, "forge_neo", "webui", "modules"))]
            errors_stub = types.ModuleType("modules.errors")
            errors_stub.display = lambda *args, **kwargs: None
            sys.modules["modules"] = modules_stub
            sys.modules["modules.errors"] = errors_stub
            sys.path.insert(0, str(Path(ROOT, "forge_neo", "webui")))
            from modules_forge import patch_basic

            patch_basic.patch_comfy_kitchen_rope_split_half()
            self.assertTrue(hasattr(ck, "apply_rope_split_half"))

            q = torch.tensor([[[[1.0, 2.0, 3.0, 4.0]]]])
            k = torch.tensor([[[[5.0, 6.0, 7.0, 8.0]]]])
            freqs = torch.tensor(
                [
                    [
                        [[0.0, -1.0], [1.0, 0.0]],
                        [[1.0, 0.0], [0.0, 1.0]],
                    ]
                ]
            ).unsqueeze(0).unsqueeze(2)
            q_out, k_out = ck.apply_rope_split_half(q, k, freqs)

            self.assertTrue(torch.equal(q_out, torch.tensor([[[[-3.0, 2.0, 1.0, 4.0]]]])))
            self.assertTrue(torch.equal(k_out, torch.tensor([[[[-7.0, 6.0, 5.0, 8.0]]]])))
        finally:
            sys.path[:] = old_sys_path
            if old_modules is None:
                sys.modules.pop("modules", None)
            else:
                sys.modules["modules"] = old_modules
            if old_modules_errors is None:
                sys.modules.pop("modules.errors", None)
            else:
                sys.modules["modules.errors"] = old_modules_errors
            if had_previous:
                ck.apply_rope_split_half = previous
            elif hasattr(ck, "apply_rope_split_half"):
                delattr(ck, "apply_rope_split_half")

