    def test_source_backend_generation_batches_match_source_batch_loop_contract(self):
        from PIL import Image

        from forge_neo import runtime
        from forge_neo.runtime import ForgeNeoRequest, ForgeNeoResult
        from forge_neo.runtime_backend import source_runtime

        old_run = source_runtime._SOURCE_BACKEND_SESSION.run
        old_save_images = runtime._save_images
        old_randrange = source_runtime.random.randrange
        calls: list[dict[str, object]] = []
        saves: list[dict[str, object]] = []
        order: list[str] = []

        def fake_run(
            *,
            request,
            mode,
            payload,
            data_root,
            model_ref,
            timeout,
            started,
            progress_callback=None,
            control_callback=None,
        ):
            payload_args = dict(payload["payload"])
            call_number = len(calls) + 1
            order.append(f"run-{call_number}")
            seed = int(payload_args["seed"])
            batch_size = int(payload_args["batch_size"])
            calls.append(
                {
                    "mode": mode,
                    "n_iter": payload_args["n_iter"],
                    "batch_size": batch_size,
                    "seed": seed,
                    "force_task_id": payload_args["force_task_id"],
                    "request_batch_count": request.batch_count,
                    "request_seed": request.seed,
                }
            )
            images = [Image.new("RGB", (4, 4), (call_number, image_index, 0)) for image_index in range(batch_size)]
            infotexts = [
                f"seq prompt\nSteps: 1, Sampler: Euler, Seed: {seed + image_index}, Size: 4x4"
                for image_index in range(batch_size)
            ]
            source_info = {
                "prompt": "seq prompt",
                "all_prompts": ["seq prompt" for _index in range(batch_size)],
                "negative_prompt": "",
                "all_negative_prompts": ["" for _index in range(batch_size)],
                "seed": seed,
                "all_seeds": [seed + image_index for image_index in range(batch_size)],
                "subseed": -1,
                "all_subseeds": [-1 for _index in range(batch_size)],
                "index_of_first_image": 0,
                "infotexts": infotexts,
                "version": "fake-source",
            }
            if progress_callback is not None:
                progress_callback(
                    {
                        "event": "progress",
                        "progress": 0.5,
                        "message": "fake child progress",
                        "message_en": "fake child progress",
                        "message_cn": "fake child progress",
                        "sampling_step": 1,
                        "sampling_steps": 2,
                    }
                )
            return ForgeNeoResult(
                images=images,
                infotext=infotexts[0],
                seed=seed,
                status="finished",
                debug_info={"source_backend": {"source_info": json.dumps(source_info)}},
            )

        def fake_save_images(images, infotext, seed):
            save_number = len(saves) + 1
            order.append(f"save-{save_number}")
            saves.append({"count": len(images), "infotext": infotext, "seed": seed})
            return [f"saved-{save_number}-{index}.png" for index in range(len(images))]

        try:
            source_runtime._SOURCE_BACKEND_SESSION.run = fake_run
            runtime._save_images = fake_save_images
            source_runtime.random.randrange = lambda *args: 700
            progress_events: list[dict[str, object]] = []
            result = source_runtime.run_source_backend_processing(
                ForgeNeoRequest(
                    mode="txt2img",
                    prompt="seq prompt",
                    seed=-1,
                    batch_count=3,
                    batch_size=2,
                    steps=1,
                    width=64,
                    height=64,
                ),
                progress_callback=progress_events.append,
            )
        finally:
            source_runtime._SOURCE_BACKEND_SESSION.run = old_run
            runtime._save_images = old_save_images
            source_runtime.random.randrange = old_randrange

        self.assertEqual(result.status, "finished")
        self.assertEqual(result.seed, 700)
        self.assertEqual(len(result.images), 6)
        self.assertEqual([call["mode"] for call in calls], ["txt2img", "txt2img", "txt2img"])
        self.assertEqual([call["n_iter"] for call in calls], [1, 1, 1])
        self.assertEqual([call["request_batch_count"] for call in calls], [1, 1, 1])
        self.assertEqual([call["batch_size"] for call in calls], [2, 2, 2])
        self.assertEqual([call["seed"] for call in calls], [700, 702, 704])
        self.assertEqual([call["request_seed"] for call in calls], [700, 702, 704])
        self.assertTrue(str(calls[0]["force_task_id"]).endswith("-batch-1"))
        self.assertEqual([save["seed"] for save in saves], [700, 701, 702, 703, 704, 705])
        self.assertEqual([save["count"] for save in saves], [1, 1, 1, 1, 1, 1])
        self.assertEqual(
            order,
            ["run-1", "save-1", "save-2", "run-2", "save-3", "save-4", "run-3", "save-5", "save-6"],
        )
        self.assertEqual(result.output_paths, [f"saved-{index}-0.png" for index in range(1, 7)])
        source_debug = result.debug_info["source_backend"]
        self.assertTrue(source_debug["sequential_batches"])
        self.assertEqual(source_debug["batch_count"], 3)
        self.assertEqual(source_debug["batch_size"], 2)
        source_info = source_debug["source_info"]
        self.assertEqual(source_info["n_iter"], 3)
        self.assertEqual(source_info["batch_size"], 2)
        self.assertEqual(source_info["all_seeds"], [700, 701, 702, 703, 704, 705])
        self.assertEqual(len(source_info["infotexts"]), 6)
        self.assertEqual(progress_events[0]["message_cn"], "源后端生成已排队 3 个批次")
        self.assertEqual(progress_events[-1]["event"], "finish")
        self.assertEqual(progress_events[-1]["message_cn"], "源后端生成完成")

