        def report_path(*parts: str) -> Path:
            path = Path(ROOT, "reports", *parts)
            if path.is_file():
                return path
            return Path(ROOT, "reports", "归档", *parts)

        stage_report_path = report_path("forge-neo-stage484-source-backend-streaming-progress.json")
        self.assertTrue(stage_report_path.is_file())
        stage_report = json.loads(stage_report_path.read_text(encoding="utf-8"))
        self.assertEqual(stage_report["stage"], 484)
        self.assertEqual(stage_report["adapter"], "source_backend")
        self.assertEqual(stage_report["anima_defaults"]["sampler"], "ER SDE")
        self.assertEqual(stage_report["anima_defaults"]["scheduler"], "Simple")
        self.assertTrue(stage_report["auto_route"]["source_backend_anima"])
        self.assertFalse(stage_report["auto_route"]["source_api_anima"])
        self.assertTrue(stage_report["streaming_progress"]["child_polls_immediately"])
        self.assertTrue(stage_report["auto_route"]["source_backend_any_txt2img"])
        self.assertTrue(stage_report["auto_route"]["source_backend_img2img"])
        self.assertEqual(stage_report["smoke"]["batch_count_2"]["image_count"], 2)
        self.assertGreaterEqual(stage_report["smoke"]["steps_4_preview"]["preview_event_count"], 1)
        self.assertGreaterEqual(stage_report["smoke"]["steps_4_preview"]["step_event_count"], 1)
        self.assertIn("test_source_backend_streaming_progress_and_anima_defaults_contract", stage_report["contracts"])

        browser_smoke_path = report_path("forge-neo-browser-smoke", "browser-generate-smoke.json")
        self.assertTrue(browser_smoke_path.is_file())
        browser_smoke = json.loads(browser_smoke_path.read_text(encoding="utf-8"))
        self.assertTrue(browser_smoke["finished"])
        self.assertTrue(browser_smoke["capturedRunning"])
        self.assertTrue(browser_smoke["capturedPreview"])
        browser_events = browser_smoke["events"]
        progress_lines = [" ".join(event.get("progressText", [])) for event in browser_events]
        self.assertTrue(any("源后端" in line for line in progress_lines))
        self.assertTrue(any("源后端采样" in line and "/32" in line for line in progress_lines))
        sampling_steps = []
        for line in progress_lines:
            for token in line.replace("·", " ").split():
                if token.endswith("/32") and token[:-3].isdigit():
                    sampling_steps.append(int(token[:-3]))
        self.assertGreaterEqual(max(sampling_steps), 30)
        self.assertTrue(any(event.get("livePreviewImageCount", 0) > 0 for event in browser_events))
        self.assertTrue(any(event.get("livePreviewCount", 0) > 0 for event in browser_events))
        self.assertTrue(any(event.get("finalImageCount", 0) > 0 for event in browser_events))
        final_events = [event for event in browser_events if event.get("label") == "final"]
        self.assertEqual(len(final_events), 1)
        final_event = final_events[0]
        self.assertTrue(final_event["generate"]["visible"])
        self.assertFalse(final_event["generate"]["disabled"])
        self.assertFalse(final_event["stop"]["visible"])
        self.assertFalse(final_event["skip"]["visible"])
        self.assertEqual(final_event["progressCount"], 0)
        self.assertEqual(final_event["livePreviewCount"], 0)
        self.assertEqual(final_event["livePreviewImageCount"], 0)
        self.assertEqual(final_event["runningBoxes"], 0)
        self.assertGreater(final_event["finalImageCount"], 0)
        self.assertIn("1024x1024", final_event["finalImageSizes"])
        self.assertTrue((browser_smoke_path.parent / "03-live-preview.png").is_file())
        self.assertTrue((browser_smoke_path.parent / "04-final.png").is_file())

