    def test_source_backend_passive_progress_keeps_interval_preview_contract(self):
        from PIL import Image

        from forge_neo.runtime_backend import source_runtime_child

        class FakeState:
            def __init__(self):
                self.sampling_step = 1
                self.sampling_steps = 2
                self.preview_step = 1
                self.current_image_sampling_step = 0
                self.current_image = None
                self.id_live_preview = 0
                self.job_no = 0
                self.job_count = 1
                self.eta_relative = 0
                self.textinfo = ""
                self.preview_calls = 0

            def set_current_image(self):
                self.preview_calls += 1
                self.current_image_sampling_step = self.preview_step
                self.current_image = Image.new("RGB", (8, 8), "red")
                self.id_live_preview += 1

        class FakeOpts:
            live_previews_image_format = "jpeg"
            live_previews_enable = True
            show_progress_every_n_steps = 1

        old_poll = source_runtime_child._SOURCE_BACKEND_PROGRESS_POLL_SECONDS
        old_emit = source_runtime_child._emit_event
        old_preview_env = os.environ.get("FORGE_NEO_SOURCE_BACKEND_PREVIEW")
        old_modules = sys.modules.get("modules")
        old_modules_shared = sys.modules.get("modules.shared")
        events: list[dict[str, object]] = []
        stop_holder = {"event": threading.Event()}

        def install_state(state: FakeState) -> None:
            fake_shared = types.SimpleNamespace(state=state, opts=FakeOpts())
            fake_modules = types.ModuleType("modules")
            fake_modules.shared = fake_shared
            sys.modules["modules"] = fake_modules
            sys.modules["modules.shared"] = fake_shared

        def emit(event: dict[str, object]) -> None:
            events.append(event)
            stop_holder["event"].set()

        try:
            source_runtime_child._SOURCE_BACKEND_PROGRESS_POLL_SECONDS = 0.01
            source_runtime_child._emit_event = emit

            state = FakeState()
            install_state(state)
            os.environ["FORGE_NEO_SOURCE_BACKEND_PREVIEW"] = "1"
            source_runtime_child._progress_worker_passive(
                stop_holder["event"],
                requested_steps=2,
                requested_batches=1,
                task_id="unit-preview",
            )
            self.assertEqual(state.preview_calls, 1)
            self.assertEqual(events[-1]["id_live_preview"], 1)
            self.assertTrue(str(events[-1]["current_image"]).startswith("/9j/"))

            events.clear()
            state = FakeState()
            install_state(state)
            stop_holder["event"] = threading.Event()
            os.environ["FORGE_NEO_SOURCE_BACKEND_PREVIEW"] = "0"
            source_runtime_child._progress_worker_passive(
                stop_holder["event"],
                requested_steps=2,
                requested_batches=1,
                task_id="unit-preview-disabled",
            )
            self.assertEqual(state.preview_calls, 0)
            self.assertNotIn("current_image", events[-1])
        finally:
            source_runtime_child._SOURCE_BACKEND_PROGRESS_POLL_SECONDS = old_poll
            source_runtime_child._emit_event = old_emit
            if old_preview_env is None:
                os.environ.pop("FORGE_NEO_SOURCE_BACKEND_PREVIEW", None)
            else:
                os.environ["FORGE_NEO_SOURCE_BACKEND_PREVIEW"] = old_preview_env
            if old_modules is None:
                sys.modules.pop("modules", None)
            else:
                sys.modules["modules"] = old_modules
            if old_modules_shared is None:
                sys.modules.pop("modules.shared", None)
            else:
                sys.modules["modules.shared"] = old_modules_shared

    def test_source_backend_command_line_event_hidden_from_ui_contract(self):
        import queue

        from forge_neo.runtime_backend import source_runtime

        startup_event = {
            "event": "progress",
            "progress": 0.025,
            "message_en": "Source backend command line prepared",
            "message_cn": "源后端启动参数已准备",
            "commandline_args": '"--data-dir" "L:\\example" "--lowvram" "--disable-sage" "--ckpt-dirs" "A" "--ckpt-dirs" "B" "--lora-dirs" "L" "--disable-extra-extensions"',
            "python_executable": "python.exe",
        }
        startup_line = source_runtime._source_event_console_line(startup_event)
        self.assertIn("source backend command line prepared", startup_line)
        self.assertIn('python=python.exe', startup_line)
        self.assertIn('args=--lowvram --disable-sage --disable-extra-extensions', startup_line)
        self.assertIn('model_dirs=ckpt=2 lora=1', startup_line)
        self.assertNotIn('L:\\example', startup_line)
        old_full_args = os.environ.get("FORGE_NEO_SOURCE_BACKEND_LOG_FULL_ARGS")
        try:
            os.environ["FORGE_NEO_SOURCE_BACKEND_LOG_FULL_ARGS"] = "1"
            full_startup_line = source_runtime._source_event_console_line(startup_event)
        finally:
            if old_full_args is None:
                os.environ.pop("FORGE_NEO_SOURCE_BACKEND_LOG_FULL_ARGS", None)
            else:
                os.environ["FORGE_NEO_SOURCE_BACKEND_LOG_FULL_ARGS"] = old_full_args
        self.assertIn('args="--data-dir" "L:\\example"', full_startup_line)
        forwarded: list[dict[str, object]] = []
        source_runtime._forward_source_event(startup_event, forwarded.append)
        self.assertEqual(forwarded, [])

        startup_queue = queue.Queue()
        startup_queue.put(source_runtime.SOURCE_EVENT_PREFIX + json.dumps(startup_event))
        printed: list[str] = []
        previous_print = source_runtime._print_source_backend_log
        try:
            source_runtime._print_source_backend_log = printed.append
            fake_process = types.SimpleNamespace(poll=lambda: None)
            source_runtime._SourceBackendSession()._drain_startup_output(fake_process, startup_queue, timeout=0.1)
        finally:
            source_runtime._print_source_backend_log = previous_print
        self.assertTrue(any('args=--lowvram --disable-sage --disable-extra-extensions' in line for line in printed))
        self.assertFalse(any('L:\\example' in line for line in printed))

        sampling_event = {
            "event": "progress",
            "progress": 0.25,
            "message_en": "Source backend preparing sampler",
            "message_cn": "源后端准备采样",
            "sampling_step": 0,
            "sampling_steps": 32,
        }
        self.assertIn("Source backend preparing sampler", source_runtime._source_event_console_line(sampling_event))
        source_runtime._forward_source_event(sampling_event, forwarded.append)
        self.assertEqual(forwarded[-1]["message_en"], "Source backend preparing sampler")

    def test_source_backend_console_event_same_text_dedupe_contract(self):
        from forge_neo.runtime_backend import source_runtime

        session = source_runtime._SourceBackendSession()
        first_event = {
            "event": "progress",
            "progress": 0.315,
            "message_en": "Source backend sampling 1/8",
            "message_cn": "源后端采样 1/8",
            "sampling_step": 1,
            "sampling_steps": 8,
            "eta_relative": 25.0,
            "job_id": "forge-neo-ab4f0968",
        }
        preview_event = dict(first_event)
        preview_event["id_live_preview"] = 11
        preview_event["current_image"] = "data:image/png;base64,AAAA"
        second_event = dict(first_event)
        second_event.update(
            {
                "progress": 0.41,
                "message_en": "Source backend sampling 2/8",
                "message_cn": "源后端采样 2/8",
                "sampling_step": 2,
                "eta_relative": 18.0,
            }
        )

        printed: list[str] = []
        progress_lines: list[str] = []
        completion_lines: list[str] = []
        previous_print = source_runtime._print_source_backend_log
        previous_progress = source_runtime._print_source_backend_progress_line

        def fake_progress_line(message: str, *, completion_line: str = "") -> None:
            progress_lines.append(message)
            completion_lines.append(completion_line)

        try:
            source_runtime._print_source_backend_log = printed.append
            source_runtime._print_source_backend_progress_line = fake_progress_line
            session._print_source_event_console(first_event)
            session._print_source_event_console(preview_event)
            session._print_source_event_console(second_event)
        finally:
            source_runtime._print_source_backend_log = previous_print
            source_runtime._print_source_backend_progress_line = previous_progress

        self.assertEqual(printed, [])
        self.assertEqual(
            progress_lines,
            [
                source_runtime._source_sampling_progress_console_line(first_event, elapsed_seconds=0.0),
                source_runtime._source_sampling_progress_console_line(second_event, elapsed_seconds=0.0),
            ],
        )
        self.assertEqual(progress_lines[0], " 12%|█▎        | 1/8 [00:03<00:25,  3.57s/it]")
        self.assertEqual(progress_lines[1], " 25%|██▌       | 2/8 [00:06<00:18,  3.00s/it]")
        self.assertNotIn("Source backend sampling job", "".join(progress_lines))
        self.assertEqual(completion_lines[0], "100%|██████████| 8/8 [00:28<00:00,  3.57s/it]")
        self.assertEqual(completion_lines[1], "100%|██████████| 8/8 [00:24<00:00,  3.00s/it]")

        forwarded: list[dict[str, object]] = []
        source_runtime._forward_source_event(preview_event, forwarded.append)
        self.assertEqual(forwarded[-1]["id_live_preview"], 11)
        self.assertIn("current_image", forwarded[-1])

        kdiffusion_source = Path(ROOT, "forge_neo", "webui", "modules", "sd_samplers_kdiffusion.py").read_text(encoding="utf-8")
        self.assertEqual(kdiffusion_source.count("disable=shared.cmd_opts.disable_console_progressbars"), 2)
        self.assertNotIn("self.sampler_extra_args, disable=False, callback=self.callback_state", kdiffusion_source)

    def test_source_native_processed_infotext_priority_contract(self):
        from PIL import Image

        from forge_neo.runtime_backend import adapter
        from forge_neo.runtime import ForgeNeoRequest

        class ProcessedWithJs:
            images = [Image.new("RGB", (8, 8), "red")]
            extra_images = []
            infotexts = ["native visible prompt\nSteps: 4, Sampler: Euler, CFG scale: 3.0"]
            info = "fallback readable info"
            seed = 123

            def js(self):
                return '{"prompt": "json prompt", "seed": 123}'

        result = adapter._processed_to_result(
            ProcessedWithJs(),
            ForgeNeoRequest(prompt="request prompt", seed=123),
            elapsed_seconds=0.25,
        )

        self.assertEqual(result.status, "finished")
        self.assertEqual(result.infotext, "native visible prompt\nSteps: 4, Sampler: Euler, CFG scale: 3.0")
        self.assertNotIn('"json prompt"', result.infotext)

        source = Path(ROOT, "forge_neo", "runtime_backend", "adapter.py").read_text(encoding="utf-8")
        block = source[source.index("def _processed_to_result"):source.index("def run_native_processing")]
        self.assertLess(block.index("infotexts ="), block.index("if hasattr(processed, \"js\")"))
        self.assertIn("if not info:\n            info = js_info", block)

    def test_source_save_samples_output_paths_contract(self):
        from PIL import Image

        from forge_neo.runtime_backend import adapter
        from forge_neo.modules import processing, shared
        from forge_neo.runtime import ForgeNeoRequest

        old_values = {
            "samples_save": shared.opts.samples_save,
            "samples_format": shared.opts.samples_format,
            "save_txt": shared.opts.save_txt,
            "save_incomplete_images": shared.opts.save_incomplete_images,
        }
        try:
            shared.opts.samples_save = True
            shared.opts.samples_format = "png"
            shared.opts.save_txt = True
            shared.opts.save_incomplete_images = True
            with tempfile.TemporaryDirectory() as tmp:
                txt = processing.StableDiffusionProcessingTxt2Img(
                    prompt="save sample prompt",
                    negative_prompt="",
                    seed=430,
                    sampler_name="Euler",
                    scheduler="Normal",
                    batch_size=1,
                    n_iter=1,
                    steps=1,
                    width=16,
                    height=16,
                )
                txt.outpath_samples = tmp
                txt.setup_conds = lambda: None
                txt.get_conds = lambda: (None, None)
                txt.sample = lambda **_kwargs: [Image.new("RGB", (16, 16), "green")]
                processed = processing.process_images_inner(txt)
                self.assertEqual(len(processed.images), 1)
                saved_as = str(getattr(processed.images[0], "already_saved_as", "") or "")
                self.assertTrue(saved_as)
                self.assertTrue(Path(saved_as).is_file())
                self.assertEqual(Path(saved_as).suffix.lower(), ".png")
                self.assertTrue(Path(saved_as).with_suffix(".txt").is_file())
                result = adapter._processed_to_result(
                    processed,
                    ForgeNeoRequest(prompt="save sample prompt", seed=430),
                    elapsed_seconds=0.1,
                )
                self.assertIn(saved_as, result.output_paths)
        finally:
            for key, value in old_values.items():
                setattr(shared.opts, key, value)

        images_source = Path(ROOT, "forge_neo", "modules", "images.py").read_text(encoding="utf-8")
        processing_source = Path(ROOT, "forge_neo", "modules", "processing.py").read_text(encoding="utf-8")
