    def test_source_processing_generation_result_saved_when_backend_returns_images_only_contract(self):
        from PIL import Image

        import args_manager
        from forge_neo import runtime, ui
        from forge_neo.bootstrap import ensure_config
        from forge_neo.runtime import ForgeNeoRequest, ForgeNeoResult
        from forge_neo.runtime_backend import adapter

        config = ensure_config(test_stub=True)
        old_userhome = getattr(config, "path_userhome", "")
        old_run_backend_generation = adapter.run_backend_generation
        old_build_request = ui._build_request
        old_worker_run = ui.worker.run
        old_disable_backend = getattr(args_manager.args, "disable_backend", None)
        old_disable_image_log = getattr(args_manager.args, "disable_image_log", None)
        try:
            with tempfile.TemporaryDirectory() as tmp:
                config.path_userhome = tmp
                args_manager.args.disable_backend = False
                args_manager.args.disable_image_log = False

                def fake_run_backend_generation(request, *, progress_callback=None, control_callback=None):
                    return ForgeNeoResult(
                        images=[Image.new("RGB", (12, 10), "green")],
                        infotext="saved backend prompt\nSteps: 4, Sampler: Euler, CFG scale: 1.5, Seed: 77, Size: 12x10",
                        seed=77,
                        status="finished",
                        output_paths=[],
                    )

                adapter.run_backend_generation = fake_run_backend_generation
                result = runtime.generate(ForgeNeoRequest(prompt="saved backend prompt", seed=77))
                self.assertEqual(result.status, "finished")
                self.assertEqual(len(result.output_paths), 1)
                self.assertEqual(Path(result.output_paths[0]).parent, Path(tmp) / "ForgeNeo")
                self.assertTrue(Path(result.output_paths[0]).is_file())
                self.assertEqual(Image.open(result.output_paths[0]).convert("RGB").getpixel((0, 0)), (0, 128, 0))

                ui._build_request = lambda *args: ForgeNeoRequest(prompt="saved backend prompt", seed=77)
                ui.worker.run = lambda request, state: result
                clicked = ui._generate_clicked({"__lang": "cn"})
                self.assertTrue(clicked[3]["visible"])
                self.assertIn("forge-neo-output-status", clicked[3]["value"])
                self.assertIn("已保存", clicked[3]["value"])
                self.assertIn(Path(result.output_paths[0]).name, clicked[3]["value"])
        finally:
            adapter.run_backend_generation = old_run_backend_generation
            ui._build_request = old_build_request
            ui.worker.run = old_worker_run
            config.path_userhome = old_userhome
            args_manager.args.disable_backend = old_disable_backend
            args_manager.args.disable_image_log = old_disable_image_log

