    def test_source_processing_grid_extended_filename_contract(self):
        from PIL import Image

        from forge_neo.modules import processing, shared

        keys = (
            "return_grid",
            "grid_save",
            "grid_only_if_multiple",
            "grid_format",
            "grid_extended_filename",
            "samples_save",
            "save_txt",
            "enable_pnginfo",
        )
        old_values = {key: getattr(shared.opts, key) for key in keys}

        def generate_grid(tmp: str, *, extended: bool, seed: int, prompt: str) -> Path:
            shared.opts.return_grid = False
            shared.opts.grid_save = True
            shared.opts.grid_only_if_multiple = True
            shared.opts.grid_format = "png"
            shared.opts.grid_extended_filename = extended
            shared.opts.samples_save = False
            shared.opts.save_txt = False
            shared.opts.enable_pnginfo = False
            txt = processing.StableDiffusionProcessingTxt2Img(
                prompt=prompt,
                negative_prompt="",
                seed=seed,
                sampler_name="Euler",
                scheduler="Normal",
                batch_size=2,
                n_iter=1,
                steps=1,
                width=16,
                height=16,
            )
            txt.outpath_grids = tmp
            txt.setup_conds = lambda: None
            txt.get_conds = lambda: (None, None)
            txt.sample = lambda **_kwargs: [
                Image.new("RGB", (16, 16), "red"),
                Image.new("RGB", (16, 16), "blue"),
            ]
            processing.process_images_inner(txt)
            files = sorted(Path(tmp).glob("*.png"))
            self.assertEqual(len(files), 1)
            return files[0]

        try:
            with tempfile.TemporaryDirectory() as tmp:
                short_path = generate_grid(tmp, extended=False, seed=450, prompt="grid short prompt")
                self.assertTrue(short_path.name.startswith("grid"))
                self.assertNotIn("450", short_path.name)
                self.assertNotIn("grid_short_prompt", short_path.name)
            with tempfile.TemporaryDirectory() as tmp:
                extended_path = generate_grid(tmp, extended=True, seed=451, prompt="grid extended prompt")
                self.assertTrue(extended_path.name.startswith("grid"))
                self.assertIn("451", extended_path.name)
                self.assertIn("grid extended prompt", extended_path.name)
        finally:
            for key, value in old_values.items():
                setattr(shared.opts, key, value)

        processing_source = Path(ROOT, "forge_neo", "modules", "processing.py").read_text(encoding="utf-8")
        images_source = Path(ROOT, "forge_neo", "modules", "images.py").read_text(encoding="utf-8")
        shared_source = Path(ROOT, "forge_neo", "modules", "shared.py").read_text(encoding="utf-8")
        classic_source = Path(ROOT, "..", "sd-webui-forge-classic", "modules", "processing.py").read_text(encoding="utf-8")
        self.assertIn("short_filename=not opts.grid_extended_filename", classic_source)
        self.assertIn('short_filename=not bool(getattr(shared_module.opts, "grid_extended_filename", False))', processing_source)
        self.assertIn("def _image_filename_base(", images_source)
        self.assertIn("if bool(short_filename) or seed is None:", images_source)
        self.assertIn('pattern = "[seed]" if bool(getattr(opts, "save_to_dirs", False)) else "[seed]-[prompt_spaces]"', images_source)
        self.assertIn("basecount = _next_sequence_number(directory, basename_text)", images_source)
        self.assertIn("grid_extended_filename: bool = False", shared_source)

