    def test_source_images_existing_info_callbacks_contract(self):
        from PIL import Image

        from forge_neo.modules import images, script_callbacks, shared

        keys = (
            "enable_pnginfo",
            "save_txt",
            "save_images_add_number",
            "samples_filename_pattern",
        )
        old_values = {key: getattr(shared.opts, key) for key in keys}
        old_before = list(script_callbacks.callbacks_before_image_saved)
        old_after = list(script_callbacks.callbacks_image_saved)
        calls = []

        def before_save(params):
            calls.append(("before", Path(params.filename).name, dict(params.pnginfo)))
            params.filename = str(Path(params.filename).with_name("callback-name.png"))
            params.pnginfo["before"] = "callback metadata"
            params.pnginfo["parameters"] = "callback infotext"
            params.image = Image.new("RGB", (8, 8), "purple")

        def after_save(params):
            calls.append(("after", Path(params.filename).name, dict(params.pnginfo), params.image.getpixel((0, 0))))

        try:
            shared.opts.enable_pnginfo = True
            shared.opts.save_txt = True
            shared.opts.save_images_add_number = True
            shared.opts.samples_filename_pattern = ""
            script_callbacks.callbacks_before_image_saved[:] = [before_save]
            script_callbacks.callbacks_image_saved[:] = [after_save]
            with tempfile.TemporaryDirectory() as tmp:
                image_path, txt_path = images.save_image(
                    Image.new("RGB", (8, 8), "red"),
                    tmp,
                    "",
                    seed=453,
                    prompt="callback prompt",
                    extension="png",
                    info="original infotext",
                    existing_info={"custom": "kept metadata"},
                )
                self.assertEqual(Path(image_path).name, "callback-name.png")
                self.assertTrue(Path(image_path).is_file())
                self.assertTrue(Path(txt_path).is_file())
                self.assertEqual(Path(txt_path).read_text(encoding="utf-8").strip(), "callback infotext")
                saved = Image.open(image_path)
                self.assertEqual(saved.getpixel((0, 0)), (128, 0, 128))
                self.assertEqual(saved.info["parameters"], "callback infotext")
                self.assertEqual(saved.info["custom"], "kept metadata")
                self.assertEqual(saved.info["before"], "callback metadata")
                self.assertEqual(calls[0][0], "before")
                self.assertIn("original infotext", calls[0][2]["parameters"])
                self.assertEqual(calls[1][0], "after")
                self.assertEqual(calls[1][1], "callback-name.png")
                self.assertEqual(calls[1][2]["custom"], "kept metadata")
        finally:
            for key, value in old_values.items():
                setattr(shared.opts, key, value)
            script_callbacks.callbacks_before_image_saved[:] = old_before
            script_callbacks.callbacks_image_saved[:] = old_after

        images_source = Path(ROOT, "forge_neo", "modules", "images.py").read_text(encoding="utf-8")
        callbacks_source = Path(ROOT, "forge_neo", "modules", "script_callbacks.py").read_text(encoding="utf-8")
        classic_images = Path(ROOT, "..", "sd-webui-forge-classic", "modules", "images.py").read_text(encoding="utf-8")
        classic_callbacks = Path(ROOT, "..", "sd-webui-forge-classic", "modules", "script_callbacks.py").read_text(encoding="utf-8")
        self.assertIn("pnginfo = existing_info or {}", classic_images)
        self.assertIn("script_callbacks.before_image_saved_callback(params)", classic_images)
        self.assertIn("script_callbacks.image_saved_callback(params)", classic_images)
        self.assertIn("class ImageSaveParams:", classic_callbacks)
        self.assertIn("pnginfo = dict(existing_info or {})", images_source)
        self.assertIn("params = script_callbacks.ImageSaveParams(image, p, str(target), pnginfo)", images_source)
        self.assertIn("script_callbacks.before_image_saved_callback(params)", images_source)
        self.assertIn("image = params.image", images_source)
        self.assertIn("target = Path(params.filename)", images_source)
        self.assertIn("script_callbacks.image_saved_callback(params)", images_source)
        self.assertIn("class ImageSaveParams", callbacks_source)
        self.assertIn("def before_image_saved_callback(params: ImageSaveParams) -> None:", callbacks_source)
        self.assertIn("def image_saved_callback(params: ImageSaveParams) -> None:", callbacks_source)

