    def test_source_images_atomic_replace_action_contract(self):
        from PIL import Image

        from forge_neo.modules import images, shared

        keys = (
            "save_images_replace_action",
            "save_images_add_number",
            "samples_filename_pattern",
            "enable_pnginfo",
            "save_txt",
        )
        old_values = {key: getattr(shared.opts, key) for key in keys}
        try:
            shared.opts.save_images_add_number = False
            shared.opts.samples_filename_pattern = ""
            shared.opts.enable_pnginfo = False
            shared.opts.save_txt = False
            with tempfile.TemporaryDirectory() as tmp:
                existing = Path(tmp) / "fixed.png"
                Image.new("RGB", (8, 8), "red").save(existing)

                shared.opts.save_images_replace_action = "Replace"
                replace_path, _ = images.save_image(
                    Image.new("RGB", (8, 8), "blue"),
                    tmp,
                    "",
                    extension="png",
                    forced_filename="fixed",
                )
                self.assertEqual(Path(replace_path), existing)
                self.assertEqual(Image.open(existing).getpixel((0, 0)), (0, 0, 255))
                self.assertEqual(list(Path(tmp).glob("*.tmp")), [])

                shared.opts.save_images_replace_action = "Override"
                suffix_path, _ = images.save_image(
                    Image.new("RGB", (8, 8), "green"),
                    tmp,
                    "",
                    extension="png",
                    forced_filename="fixed",
                )
                self.assertEqual(Path(suffix_path).name, "fixed-1.png")
                self.assertEqual(Image.open(existing).getpixel((0, 0)), (0, 0, 255))
                self.assertEqual(Image.open(suffix_path).getpixel((0, 0)), (0, 128, 0))
                self.assertEqual(list(Path(tmp).glob("*.tmp")), [])
        finally:
            for key, value in old_values.items():
                setattr(shared.opts, key, value)

        images_source = Path(ROOT, "forge_neo", "modules", "images.py").read_text(encoding="utf-8")
        shared_source = Path(ROOT, "forge_neo", "modules", "shared.py").read_text(encoding="utf-8")
        classic_source = Path(ROOT, "..", "sd-webui-forge-classic", "modules", "images.py").read_text(encoding="utf-8")
        self.assertIn('temp_file_path = f"{filename_without_extension}.tmp"', classic_source)
        self.assertIn('if shared.opts.save_images_replace_action != "Replace":', classic_source)
        self.assertIn("os.replace(temp_file_path, filename)", classic_source)
        self.assertIn("def _atomically_save_image(", images_source)
        self.assertIn('temp_file_path = target.with_suffix(".tmp")', images_source)
        self.assertIn('if str(getattr(opts, "save_images_replace_action", "Override") or "Override") != "Replace":', images_source)
        self.assertIn("os.replace(temp_file_path, final_target)", images_source)
        self.assertIn('allow_existing = forced_filename is not None and str(getattr(opts, "save_images_replace_action", "Override") or "Override") == "Replace"', images_source)
        self.assertIn('save_images_replace_action: str = "Override"', shared_source)

