    def test_source_processing_tail_cleanup_video_path_contract(self):
        from PIL import Image

        from forge_neo.modules import devices, extra_networks, processing

        calls: list[tuple[object, ...]] = []

        class TailExtraNetwork(extra_networks.ExtraNetwork):
            def activate(self, p, params_list):
                calls.append(("activate", self.name))

            def deactivate(self, p):
                calls.append(("deactivate", self.name, tuple(sorted(p.extra_network_data.keys()))))

        old_torch_gc = devices.torch_gc
        try:
            extra_networks.initialize()
            extra_networks.register_extra_network(TailExtraNetwork("lora"))

            def fake_torch_gc():
                calls.append(("torch_gc",))
                return None

            devices.torch_gc = fake_torch_gc
            txt = processing.StableDiffusionProcessingTxt2Img(
                prompt="tail <lora:tail_lora:0.5> cleanup prompt",
                negative_prompt="",
                seed=433,
                sampler_name="Euler",
                scheduler="Normal",
                batch_size=1,
                n_iter=1,
                steps=1,
                width=16,
                height=16,
            )
            txt.setup_conds = lambda: None
            txt.get_conds = lambda: (None, None)
            txt.sample = lambda **_kwargs: [Image.new("RGB", (16, 16), "green")]
            processed = processing.process_images_inner(txt)
            self.assertIsNone(processed.video_path)
            self.assertEqual(calls, [("torch_gc",), ("activate", "lora"), ("torch_gc",), ("deactivate", "lora", ("lora",)), ("torch_gc",)])
        finally:
            devices.torch_gc = old_torch_gc
            extra_networks.initialize()

        source = Path(ROOT, "forge_neo", "modules", "processing.py").read_text(encoding="utf-8")
        self.assertIn("video_path = None", source)
        tail_block = source[
            source.index("    if not p.disable_extra_networks and p.extra_network_data:")
            : source.index("    return processed")
        ]
        self.assertIn("extra_networks.deactivate(p, p.extra_network_data)", tail_block)
        self.assertLess(tail_block.index("extra_networks.deactivate(p, p.extra_network_data)"), tail_block.index("devices.torch_gc()"))
        self.assertLess(tail_block.index("devices.torch_gc()"), tail_block.index("processed = Processed("))
        self.assertLess(tail_block.index("processed.video_path = video_path"), tail_block.index("p.scripts.postprocess(p, processed)"))

