    def test_source_processing_script_process_hook_contract(self):
        from PIL import Image

        from forge_neo.modules import processing, scripts

        calls: list[tuple[object, ...]] = []

        class AlwaysOn:
            def process(self, p):
                calls.append(("process", p.prompt, tuple(p.all_seeds)))

            def before_process_batch(self, p, batch_number, prompts, seeds, subseeds):
                calls.append(("before_batch", batch_number, prompts[0], seeds[0], subseeds[0]))

        runner = scripts.ScriptRunner()
        runner.alwayson_scripts.append(AlwaysOn())
        txt = processing.StableDiffusionProcessingTxt2Img(
            prompt="script process prompt",
            negative_prompt="",
            seed=437,
            subseed=438,
            sampler_name="Euler",
            scheduler="Normal",
            batch_size=1,
            n_iter=1,
            steps=1,
            width=16,
            height=16,
        )
        txt.scripts = runner
        txt.init = lambda all_prompts, all_seeds, all_subseeds: calls.append(("init", tuple(all_prompts), tuple(all_seeds), tuple(all_subseeds)))
        txt.setup_conds = lambda: None
        txt.get_conds = lambda: (None, None)
        txt.sample = lambda **_kwargs: [Image.new("RGB", (16, 16), "green")]
        processed = processing.process_images_inner(txt)
        self.assertEqual(len(processed.images), 1)
        self.assertEqual(calls[:3], [
            ("process", "script process prompt", (437,)),
            ("init", ("script process prompt",), (437,), (438,)),
            ("before_batch", 0, "script process prompt", 437, 438),
        ])

        source = Path(ROOT, "forge_neo", "modules", "processing.py").read_text(encoding="utf-8")
        block = source[source.index("p.all_subseeds =") : source.index("    with _source_inference_context(p):")]
        self.assertIn("if p.scripts is not None:\n        p.scripts.process(p)", block)

