        class MainExtraNetwork(extra_networks.ExtraNetwork):
            def activate(self, p, params_list):
                calls.append(("activate", self.name, [list(params.items) for params in params_list], list(p.prompts)))

            def deactivate(self, p):
                calls.append(("deactivate", self.name))

        class HookScripts:
            def process(self, p):
                calls.append(("process", p.prompt))

            def before_process_batch(self, p, batch_number, prompts, seeds, subseeds):
                calls.append(("before_batch", batch_number, list(prompts), list(seeds)))

            def after_extra_networks_activate(self, p, **kwargs):
                calls.append(("after", kwargs["batch_number"], list(kwargs["prompts"]), list(kwargs["seeds"]), sorted(kwargs["extra_network_data"].keys())))

            def process_batch(self, p, batch_number, prompts, seeds, subseeds):
                calls.append(("process_batch", batch_number, list(prompts), list(seeds), sorted(p.extra_network_data.keys())))

        old_registry = dict(extra_networks.extra_network_registry)
        old_aliases = dict(extra_networks.extra_network_aliases)
        try:
            extra_networks.initialize()
            extra_networks.register_extra_network(MainExtraNetwork("lora"))
            txt = processing.StableDiffusionProcessingTxt2Img(
                prompt="extra <lora:main:0.7> prompt",
                negative_prompt="",
                seed=438,
                sampler_name="Euler",
                scheduler="Normal",
                batch_size=1,
                n_iter=1,
                steps=1,
                width=16,
                height=16,
            )
            runner = scripts.ScriptRunner()
            runner.alwayson_scripts.append(HookScripts())
            txt.scripts = runner
            txt.setup_conds = lambda: None
            txt.get_conds = lambda: (None, None)
            txt.sample = lambda **_kwargs: [Image.new("RGB", (16, 16), "green")]
            processed = processing.process_images_inner(txt)
            self.assertEqual(len(processed.images), 1)
            self.assertEqual([params.items for params in txt.extra_network_data["lora"]], [["main", "0.7"]])
            self.assertEqual(calls[:5], [
                ("process", "extra <lora:main:0.7> prompt"),
                ("before_batch", 0, ["extra <lora:main:0.7> prompt"], [438]),
                ("activate", "lora", [["main", "0.7"]], ["extra  prompt"]),
                ("after", 0, ["extra  prompt"], [438], ["lora"]),
                ("process_batch", 0, ["extra  prompt"], [438], ["lora"]),
            ])
            self.assertIn(("deactivate", "lora"), calls)
        finally:
            extra_networks.extra_network_registry.clear()
            extra_networks.extra_network_registry.update(old_registry)
            extra_networks.extra_network_aliases.clear()
            extra_networks.extra_network_aliases.update(old_aliases)

        source = Path(ROOT, "forge_neo", "modules", "processing.py").read_text(encoding="utf-8")
        self.assertIn("def parse_extra_network_prompts(self):", source)
        scripts_source = Path(ROOT, "forge_neo", "modules", "scripts.py").read_text(encoding="utf-8")
        self.assertIn("def after_extra_networks_activate(self, p, **kwargs) -> None:", scripts_source)
        block = source[source.index("p.scripts.before_process_batch") : source.index("        with _source_inference_context(p):")]
        self.assertIn("p.parse_extra_network_prompts()", block)
        self.assertIn("extra_networks.activate(p, p.extra_network_data)", block)
        self.assertLess(block.index("p.scripts.before_process_batch"), block.index("p.parse_extra_network_prompts()"))
        self.assertLess(block.index("extra_networks.activate(p, p.extra_network_data)"), block.index("p.scripts.process_batch"))

