    def test_source_processing_before_batch_empty_prompt_guard_contract(self):
        from forge_neo.modules import processing, scripts

        calls: list[tuple[object, ...]] = []

        class ClearBatchScript:
            def before_process_batch(self, p, batch_number, prompts, seeds, subseeds):
                calls.append(("before_process_batch", batch_number, list(prompts), list(seeds), list(subseeds), p.rng is not None))
                p.prompts = []

            def process_batch(self, p, **kwargs):
                calls.append(("process_batch", kwargs.get("batch_number")))

        runner = scripts.ScriptRunner()
        runner.alwayson_scripts.append(ClearBatchScript())
        txt = processing.StableDiffusionProcessingTxt2Img(
            prompt="clear this batch",
            negative_prompt="",
            seed=444,
            sampler_name="Euler",
            scheduler="Normal",
            batch_size=1,
            n_iter=1,
            steps=1,
            width=16,
            height=16,
        )
        txt.scripts = runner
        txt.init = lambda all_prompts, all_seeds, all_subseeds: calls.append(("init", list(all_prompts), list(all_seeds)))
        txt.parse_extra_network_prompts = lambda: calls.append(("parse_extra_network_prompts",))
        txt.setup_conds = lambda: calls.append(("setup_conds",))
        txt.get_conds = lambda: (None, None)
        txt.sample = lambda **_kwargs: calls.append(("sample",)) or []
        processed = processing.process_images_inner(txt)

        self.assertEqual(processed.images, [])
        self.assertIn(("before_process_batch", 0, ["clear this batch"], [444], [txt.all_subseeds[0]], True), calls)
        self.assertNotIn(("parse_extra_network_prompts",), calls)
        self.assertNotIn(("process_batch", 0), calls)
        self.assertNotIn(("setup_conds",), calls)
        self.assertNotIn(("sample",), calls)

        source = Path(ROOT, "forge_neo", "modules", "processing.py").read_text(encoding="utf-8")
        loop_block = source[source.index("        from forge_neo.modules import rng"):source.index("        if not p.disable_extra_networks:")]
        self.assertLess(loop_block.index("p.rng = rng.ImageRNG("), loop_block.index("p.scripts.before_process_batch"))
        self.assertLess(loop_block.index("p.scripts.before_process_batch"), loop_block.index("if not p.prompts:"))
        self.assertLess(loop_block.index("if not p.prompts:"), loop_block.index("p.parse_extra_network_prompts()"))

    def test_source_processing_zero_terminal_snr_contract(self):
        import torch
        from PIL import Image

        from forge_neo.modules import processing, scripts, shared

        calls: list[tuple[object, ...]] = []
        old_schedule = shared.opts.sd_noise_schedule
        old_sd_model = shared.sd_model

        class FakePredictor:
            def __init__(self):
                self.sigmas = torch.tensor([10.0, 1.0, 0.1], dtype=torch.float32)
                self.original = self.sigmas

            def set_sigmas(self, value):
                self.sigmas = value
                calls.append(("set_sigmas", tuple(round(float(item), 6) for item in value.tolist())))

        class FakeModelInner:
            def __init__(self):
                self.predictor = FakePredictor()

        class FakeUNet:
            def __init__(self):
                self.model = FakeModelInner()

        class FakeVAE:
            latent_channels = 4

        class FakeForgeObjects:
            def __init__(self, unet):
                self.unet = unet
                self.vae = FakeVAE()

            def shallow_copy(self):
                return self

        class FakeCheckpointInfo:
            model_name = "stage445-model"
            name_for_extra = "stage445-model"
            name = "stage445-model.safetensors"

        class FakeModelConfig:
            ztsnr = False

        class FakeModel:
            def __init__(self):
                self.unet = FakeUNet()
                self.sd_checkpoint_info = FakeCheckpointInfo()
                self.sd_model_hash = "stage445-hash"
                self.additional_modules = []
                self.unet_storage_dtype = None
                self.model_config = FakeModelConfig()
                self.forge_objects = FakeForgeObjects(self.unet)
                self.forge_objects_original = FakeForgeObjects(self.unet)
                self.forge_objects_after_applying_lora = FakeForgeObjects(self.unet)
                self.extra_generation_params = {}
                self.comments = []

        class PostSampleScript:
            def post_sample(self, p, args):
                sigmas = p.sd_model.forge_objects.unet.model.predictor.sigmas
                calls.append(("post_sample_sigmas", tuple(round(float(item), 6) for item in sigmas.tolist())))

        try:
            shared.opts.sd_noise_schedule = "Zero Terminal SNR"
            shared.sd_model = FakeModel()
            runner = scripts.ScriptRunner()
            runner.alwayson_scripts.append(PostSampleScript())
            txt = processing.StableDiffusionProcessingTxt2Img(
                prompt="zero terminal snr",
                negative_prompt="",
                seed=445,
                sampler_name="Euler",
                scheduler="Normal",
                batch_size=1,
                n_iter=1,
                steps=1,
                width=16,
                height=16,
            )
            txt.sd_model = shared.sd_model
            txt.scripts = runner
            txt.init = lambda all_prompts, all_seeds, all_subseeds: None
            txt.setup_conds = lambda: None
            txt.get_conds = lambda: (None, None)

            def fake_sample(**_kwargs):
                sigmas = txt.sd_model.forge_objects.unet.model.predictor.sigmas
                calls.append(("sample_sigmas", tuple(round(float(item), 6) for item in sigmas.tolist())))
                return [Image.new("RGB", (16, 16), "green")]

            txt.sample = fake_sample
            processed = processing.process_images_inner(txt)
        finally:
            shared.opts.sd_noise_schedule = old_schedule
            shared.sd_model = old_sd_model

        expected_rescaled = tuple(round(float(item), 6) for item in processing.rescale_zero_terminal_snr_sigmas(torch.tensor([10.0, 1.0, 0.1], dtype=torch.float32)).tolist())
        original = (10.0, 1.0, 0.1)
        self.assertEqual(len(processed.images), 1)
        self.assertEqual(processed.extra_generation_params["Noise Schedule"], "Zero Terminal SNR")
        self.assertIn(("sample_sigmas", expected_rescaled), calls)
        self.assertIn(("post_sample_sigmas", original), calls)
        self.assertLess(calls.index(("sample_sigmas", expected_rescaled)), calls.index(("post_sample_sigmas", original)))
        self.assertEqual(calls[0], ("set_sigmas", expected_rescaled))
        self.assertIn(("set_sigmas", original), calls)

        source = Path(ROOT, "forge_neo", "modules", "processing.py").read_text(encoding="utf-8")
        shared_source = Path(ROOT, "forge_neo", "modules", "shared.py").read_text(encoding="utf-8")
        settings_source = Path(ROOT, "forge_neo", "settings.py").read_text(encoding="utf-8")
        self.assertIn("def rescale_zero_terminal_snr_sigmas", source)
        self.assertIn("def _apply_zero_terminal_snr_sigmas", source)
        self.assertIn("def _restore_zero_terminal_snr_sigmas", source)
        sample_start = source.index("sigmas_backup = _apply_zero_terminal_snr_sigmas(p)")
        sample_block = source[sample_start:source.index("            if p.scripts is not None:", sample_start)]
        self.assertLess(sample_block.index("sigmas_backup = _apply_zero_terminal_snr_sigmas(p)"), sample_block.index("sampled = p.sample("))
        self.assertLess(sample_block.index("_record_latents_after_sampling(p, sampled)"), sample_block.index("_restore_zero_terminal_snr_sigmas(sigmas_backup)"))
        self.assertIn('sd_noise_schedule: str = "Default"', shared_source)
        self.assertIn('ForgeNeoSettingInfo("sd_noise_schedule", "Default", "stable_diffusion", "Noise Schedule", "噪声计划")', settings_source)

