    def test_source_processing_face_restoration_contract(self):
        import numpy as np
        from PIL import Image

        from forge_neo.modules import face_restoration, processing, shared

        calls: list[tuple[object, ...]] = []
        old_face_restorers = list(shared.face_restorers)
        keys = (
            "samples_save",
            "samples_format",
            "save_incomplete_images",
            "save_before_face_restoration",
            "save_images_before_face_restoration",
            "face_restoration",
            "face_restoration_model",
        )
        old_values = {key: getattr(shared.opts, key) for key in keys}

        class FakeCodeFormer(face_restoration.FaceRestoration):
            def name(self):
                return "CodeFormer"

            def restore(self, np_image):
                calls.append(("restore", tuple(np_image.shape), tuple(int(value) for value in np_image[0, 0].tolist())))
                restored = np_image.copy()
                restored[..., 0] = 255
                restored[..., 1] = 0
                restored[..., 2] = 0
                return restored

        try:
            shared.face_restorers[:] = [FakeCodeFormer()]
            shared.opts.samples_save = True
            shared.opts.samples_format = "png"
            shared.opts.save_incomplete_images = True
            shared.opts.save_before_face_restoration = True
            shared.opts.save_images_before_face_restoration = False
            shared.opts.face_restoration = True
            shared.opts.face_restoration_model = "CodeFormer"
            with tempfile.TemporaryDirectory() as tmp:
                txt = processing.StableDiffusionProcessingTxt2Img(
                    prompt="face restoration prompt",
                    negative_prompt="",
                    seed=447,
                    sampler_name="Euler",
                    scheduler="Normal",
                    batch_size=1,
                    n_iter=1,
                    steps=1,
                    width=16,
                    height=16,
                )
                txt.outpath_samples = tmp
                txt.restore_faces = None
                txt.setup_conds = lambda: None
                txt.get_conds = lambda: (None, None)
                txt.sample = lambda **_kwargs: [Image.new("RGB", (16, 16), (0, 128, 0))]
                processed = processing.process_images_inner(txt)
                before_paths = sorted(Path(tmp).glob("*-before-face-restoration.png"))
                self.assertEqual(len(before_paths), 1)
                self.assertEqual(Image.open(before_paths[0]).getpixel((0, 0)), (0, 128, 0))
        finally:
            shared.face_restorers[:] = old_face_restorers
            for key, value in old_values.items():
                setattr(shared.opts, key, value)

        self.assertTrue(txt.restore_faces)
        self.assertEqual(processed.face_restoration_model, "CodeFormer")
        self.assertEqual(processed.images[0].getpixel((0, 0)), (255, 0, 0))
        self.assertIn(("restore", (16, 16, 3), (0, 128, 0)), calls)

        processing_source = Path(ROOT, "forge_neo", "modules", "processing.py").read_text(encoding="utf-8")
        face_source = Path(ROOT, "forge_neo", "modules", "face_restoration.py").read_text(encoding="utf-8")
        shared_source = Path(ROOT, "forge_neo", "modules", "shared.py").read_text(encoding="utf-8")
        adapter_source = Path(ROOT, "forge_neo", "runtime_backend", "adapter.py").read_text(encoding="utf-8")
        self.assertIn("def _save_before_face_restoration_enabled", processing_source)
        self.assertIn("if p.restore_faces:", processing_source)
        self.assertIn("_save_before_face_restoration_enabled()", processing_source)
        self.assertIn('suffix="-before-face-restoration"', processing_source)
        self.assertIn("restored = face_restoration.restore_faces", processing_source)
        self.assertIn('self.face_restoration_model = _opts_value("face_restoration_model", "CodeFormer") if p.restore_faces else None', processing_source)
        face_block = processing_source[
            processing_source.index("            if p.restore_faces:")
            : processing_source.index("            if p.scripts is not None:", processing_source.index("            if p.restore_faces:"))
        ]
        self.assertLess(face_block.index("images_module.save_image("), face_block.index("restored = face_restoration.restore_faces"))
        self.assertIn("class FaceRestoration", face_source)
        self.assertIn("def restore_faces(np_image):", face_source)
        self.assertIn("face_restorers: list[Any] = []", shared_source)
        self.assertIn('face_restoration_model: str = "CodeFormer"', shared_source)
        self.assertIn('"face_restoration": "forge_neo.modules.face_restoration"', adapter_source)

