    def test_source_decode_latent_batch_decoded_samples_contract(self):
        import torch

        from forge_neo.modules import devices, processing, shared

        class FakeModel:
            def decode_first_stage(self, value):
                return torch.ones((value.shape[0], 3, value.shape[2], value.shape[3])) * -0.25

        decoded = processing.decode_latent_batch(FakeModel(), torch.zeros((1, 4, 2, 2)), target_device=torch.device("cpu"))

        self.assertIsInstance(decoded, processing.DecodedSamples)
        self.assertTrue(getattr(decoded, "already_decoded", False))
        self.assertEqual(len(decoded), 1)
        self.assertEqual(tuple(decoded[0].shape), (3, 2, 2))
        stacked = processing._as_bchw_tensor(decoded)
        self.assertEqual(tuple(stacked.shape), (1, 3, 2, 2))
        source_tensor = processing._decoded_samples_to_source_tensor(
            processing.DecodedSamples(
                [
                    torch.full((3, 2, 2), -1.0),
                    torch.full((3, 2, 2), 1.0),
                ]
            )
        )
        self.assertEqual(tuple(source_tensor.shape), (2, 3, 2, 2))
        self.assertEqual(float(source_tensor[0].mean()), 0.0)
        self.assertEqual(float(source_tensor[1].mean()), 1.0)
        pil_images = processing._source_image_tensor_to_pil_images(source_tensor, object())
        self.assertEqual([image.getpixel((0, 0)) for image in pil_images], [(0, 0, 0), (255, 255, 255)])
        nan_tensor = torch.tensor([float("nan"), float("inf"), float("-inf"), 0.25])
        devices.test_for_nans(nan_tensor)
        self.assertTrue(torch.isfinite(nan_tensor).all())
        self.assertEqual(nan_tensor.tolist(), [0.0, 1.0, 0.0, 0.25])
        self.assertIsNone(devices.torch_gc())

        decode_calls = []
        old_decode_latent_batch = processing.decode_latent_batch
        old_values = {
            "samples_save": shared.opts.samples_save,
            "return_grid": shared.opts.return_grid,
            "grid_save": shared.opts.grid_save,
        }
        try:
            shared.opts.samples_save = False
            shared.opts.return_grid = False
            shared.opts.grid_save = False

            def fake_decode_latent_batch(model, batch, target_device=None, check_for_nans=False):
                decode_calls.append((model, tuple(getattr(batch, "shape", ())), target_device, check_for_nans))
                return processing.DecodedSamples([torch.zeros((3, 2, 2), dtype=torch.float32)])

            processing.decode_latent_batch = fake_decode_latent_batch
            txt = processing.StableDiffusionProcessingTxt2Img(
                prompt="decode cpu prompt",
                negative_prompt="",
                seed=467,
                sampler_name="Euler",
                scheduler="Normal",
                batch_size=1,
                n_iter=1,
                steps=1,
                width=16,
                height=16,
            )
            txt.setup_conds = lambda: None
            txt.get_conds = lambda: (None, None)
            txt.sample = lambda **_kwargs: torch.zeros((1, 4, 2, 2), dtype=torch.float32)
            processed = processing.process_images_inner(txt)
        finally:
            processing.decode_latent_batch = old_decode_latent_batch
            for key, value in old_values.items():
                setattr(shared.opts, key, value)
        self.assertEqual(len(processed.images), 1)
        self.assertEqual(len(decode_calls), 1)
        self.assertEqual(decode_calls[0][1], (1, 4, 2, 2))
        self.assertIs(decode_calls[0][2], devices.cpu)
        self.assertTrue(decode_calls[0][3])

        source = Path(ROOT, "forge_neo", "modules", "processing.py").read_text(encoding="utf-8")
        devices_source = Path(ROOT, "forge_neo", "modules", "devices.py").read_text(encoding="utf-8")
        decode_block = source[source.index("class DecodedSamples"):source.index("def _squeeze_singleton_decoded_frame")]
        self.assertIn("class DecodedSamples(list):", decode_block)
        self.assertIn("already_decoded = True", decode_block)
        self.assertIn("samples_pytorch = _squeeze_singleton_decoded_frame(decode_first_stage(model, batch))", decode_block)
        self.assertIn("for x in samples_pytorch:\n        samples.append(x)", decode_block)
        tensor_block = source[source.index("def _decoded_samples_to_source_tensor"):source.index("def _source_image_tensor_to_pil_images")]
        self.assertIn("tensor = torch.clamp((tensor + 1.0) / 2.0, min=0.0, max=1.0)", tensor_block)
        self.assertIn("tensor = tensor.reshape(-1, *tuple(tensor.shape[-3:]))", tensor_block)
        source_decode_call_block = source[source.index("if getattr(sampled, \"already_decoded\", False):"):source.index("        decoded_tensor = _decoded_samples_to_source_tensor(decoded)")]
        self.assertIn("from forge_neo.modules import devices", source_decode_call_block)
        self.assertIn("decode_latent_batch(p.sd_model, sampled, target_device=devices.cpu, check_for_nans=True)", source_decode_call_block)
        self.assertNotIn("decode_latent_batch(p.sd_model, sampled, target_device=None, check_for_nans=True)", source_decode_call_block)
        main_block = source[source.index("decoded_tensor = _decoded_samples_to_source_tensor(decoded)"):source.index("        if len(images) > len(p.prompts):")]
        self.assertLess(main_block.index("devices.test_for_nans(decoded_tensor)"), main_block.index("p.scripts.postprocess_batch(p, batch_images, batch_number=n)"))
        self.assertLess(main_block.index("devices.torch_gc()"), main_block.index("p.scripts.postprocess_batch(p, batch_images, batch_number=n)"))
        self.assertLess(main_block.index("devices.torch_gc()"), main_block.index("shared_module.state.nextjob()"))
        self.assertLess(main_block.index("shared_module.state.nextjob()"), main_block.index("p.scripts.postprocess_batch(p, batch_images, batch_number=n)"))
        self.assertLess(main_block.index("p.scripts.postprocess_batch(p, batch_images, batch_number=n)"), main_block.index("p.prompts = p.all_prompts[start:end]"))
        self.assertLess(main_block.index("p.negative_prompts = p.all_negative_prompts[start:end]"), main_block.index("scripts.PostprocessBatchListArgs("))
        self.assertIn("p.scripts.postprocess_batch(p, batch_images, batch_number=n)", main_block)
        self.assertIn("p.prompts = p.all_prompts[start:end]", main_block)
        self.assertIn("p.negative_prompts = p.all_negative_prompts[start:end]", main_block)
        self.assertIn("scripts.PostprocessBatchListArgs(list(batch_images) if decoded_tensor is not None else batch_images)", main_block)
        self.assertIn("images = _source_image_tensor_to_pil_images(batch_args.images, p)", main_block)
        self.assertIn("class NansException(Exception):", devices_source)
        self.assertIn("def test_for_nans(x: torch.Tensor, *args, **kwargs):", devices_source)
        self.assertIn("x.nan_to_num_(nan=0.0, posinf=1.0, neginf=0.0)", devices_source)
        self.assertIn("def torch_gc():", devices_source)
        self.assertIn('p.extra_generation_params["VAE Decoder"] = vae_decode_method', source)
        image_loop = source[source.index("for index, image in enumerate(images):"):source.index("            target_size = (p.width, p.height)")]
        self.assertIn("p.batch_index = index", image_loop)

        stage_report_path = Path(ROOT, "reports", "forge-neo-stage467-decode-target-cpu.json")
        self.assertTrue(stage_report_path.is_file())
        stage_report = json.loads(stage_report_path.read_text(encoding="utf-8"))
        self.assertEqual(stage_report["stage"], 467)
