        runner = scripts.ScriptRunner()
        calls = []

        class AlwaysOn:
            def before_process(self, p):
                calls.append(("before_process", p.prompt))

            def before_process_batch(self, p, batch_number, prompts, seeds, subseeds):
                calls.append(("before_batch", batch_number, prompts[0], seeds[0], subseeds[0]))

            def process_batch(self, p, batch_number, prompts, seeds, subseeds):
                calls.append(("process_batch", batch_number, len(prompts)))

            def process_before_every_sampling(self, p, x, noise, c, uc):
                calls.append(("process_before_sampling", tuple(getattr(x, "shape", ()) or ()), tuple(getattr(noise, "shape", ()) or ())))

            def post_sample(self, p, args):
                calls.append(("post_sample", p.iteration, len(args.samples) if hasattr(args.samples, "__len__") else 1))

            def on_mask_blend(self, p, args):
                calls.append(("mask_blend", args.is_final_blend, args.blended_latent))

            def postprocess_batch(self, p, images, batch_number):
                calls.append(("postprocess_batch", batch_number, len(images)))

            def postprocess_batch_list(self, p, args, batch_number):
                calls.append(("postprocess_batch_list", batch_number, len(args.images)))

            def postprocess_image(self, p, args):
                calls.append(("postprocess_image", args.index, args.image.size))

            def postprocess(self, p, processed):
                calls.append(("postprocess", len(processed.images)))

        runner.alwayson_scripts.append(AlwaysOn())
        runner.on_mask_blend(object(), scripts.MaskBlendArgs("current", "nmask", "init", "mask", "blend"))
        self.assertIn(("mask_blend", True, "blend"), calls)
