        def fake_sampler(p, **kwargs):
            conditioning = kwargs["conditioning"]
            unconditional = kwargs["unconditional_conditioning"]
            unet = p.sd_model.forge_objects.unet
            cfg_denoiser = kwargs["cfg_denoiser"]
            sampler_extra_args = kwargs["sampler_extra_args"]
            image_cond = sampler_extra_args.get("image_cond")
            calls.append((
                "sample_image_conditioning",
                kwargs["mode"],
                tuple(getattr(image_cond, "shape", ()) or ()),
            ))
            cond_composition, current_cond, current_uncond = cfg_denoiser._reconstruct(sampler_extra_args["cond"], sampler_extra_args["uncond"])
            x_value = kwargs.get("x")
            if hasattr(x_value, "new_ones"):
                sigma = x_value.new_ones((x_value.shape[0],))
                denoised = cfg_denoiser(
                    x_value,
                    sigma,
                    sampler_extra_args["uncond"],
                    sampler_extra_args["cond"],
                    sampler_extra_args["cond_scale"],
                    sampler_extra_args["s_min_uncond"],
                    sampler_extra_args["image_cond"],
                )
                denoised_shape = tuple(getattr(denoised, "shape", ()) or ())
            else:
                denoised_shape = ()
            calls.append((
                "sampling_function_entry",
                kwargs["mode"],
                denoised_shape,
                len(p.sd_model.forge_objects.unet.model.apply_calls),
            ))
            sampling_sigmas = p.sd_model.forge_objects.unet.model_options["transformer_options"]["sampling_sigmas"]
            calls.append((
                "sigma_state",
                kwargs["mode"],
                len(kwargs["sigmas"]),
                len(sampling_sigmas),
                sampling_sigmas is kwargs["sigmas"],
            ))
            calls.append((
                "cfg_state",
                kwargs["mode"],
                cfg_denoiser.steps,
                cfg_denoiser.total_steps,
                tuple(sorted(sampler_extra_args.keys())),
                len(cond_composition),
                len(current_cond),
                None if current_uncond is None else len(current_uncond),
            ))
            calls.append((
                "sampling_state",
                kwargs["mode"],
                bool(getattr(unet, "sampling_prepared", False)),
                tuple(getattr(unet, "last_sampling_shape", ()) or ()),
            ))
            calls.append((
                "sample_common",
                kwargs["mode"],
                kwargs["steps"],
                kwargs.get("t_enc"),
                kwargs["total_steps"],
                kwargs.get("requested_steps"),
                tuple(sorted((kwargs.get("sampler_options") or {}).keys())),
            ))
            init_latent = getattr(p, "init_latent", None)
            calls.append((
                "sample_init_latent",
                kwargs["mode"],
                kwargs.get("x") is init_latent,
                tuple(getattr(init_latent, "shape", ()) or ()),
            ))
            calls.append((
                "sample_cfg_init_latent",
                kwargs["mode"],
                getattr(cfg_denoiser, "init_latent", None) is init_latent,
                tuple(getattr(getattr(cfg_denoiser, "init_latent", None), "shape", ()) or ()),
            ))
            calls.append((
                "sample",
                kwargs["mode"],
                kwargs["sampler"],
                kwargs["scheduler"],
                p.iteration,
                tuple(kwargs["seeds"]),
                tuple(kwargs["prompts"]),
                p.sd_model_name,
                tuple(p.sd_model.additional_modules),
                p.sd_model.unet_storage_dtype,
                tuple(getattr(kwargs.get("x"), "shape", ())),
                getattr(conditioning, "kind", None),
                tuple(getattr(conditioning, "prompts", []) or []),
                getattr(conditioning, "width", None),
                getattr(conditioning, "height", None),
                "none" if unconditional is None else "learned",
                tuple(
                    getattr(
                        unconditional[0][0].cond if unconditional is not None and unconditional and unconditional[0] else None,
                        "prompts",
                        [],
                    )
                    or []
                ),
            ))
            return [
                Image.new("RGB", (p.width, p.height), "red"),
                Image.new("RGB", (p.width, p.height), "blue"),
            ]

