        class FakeCoreVae:
            latent_channels = (8,)
            upscale_ratio = (1, 4)

            def __init__(self):
                self.decode_calls = []

            def decode(self, value):
                shape = tuple(getattr(value, "shape", ()) or ())
                self.decode_calls.append(shape)
                if len(shape) == 5:
                    return torch.ones((value.shape[0], 1, 3, value.shape[3], value.shape[4])) * 0.5
                return torch.ones((value.shape[0], value.shape[2], value.shape[3], 3)) * 0.5

            def encode(self, value):
                return value

        class FakeCoreClip:
            cond_stage_model = object()

            def __init__(self):
                self.clip_skip = None
                self.tokenized = []
                self.encoded = []

            def clip_layer(self, value):
                self.clip_skip = value

            def tokenize(self, text):
                self.tokenized.append(text)
                return {"text": text}

            def encode_from_tokens(self, tokens, return_pooled=False, return_dict=False):
                self.encoded.append((tokens, return_pooled, return_dict))
                value = torch.full((1, 2, 3), float(len(self.encoded)))
                pooled = torch.full((1,), float(len(self.encoded)))
                if return_dict:
                    return {
                        "cond": value,
                        "pooled_output": pooled,
                        "t5xxl_ids": torch.tensor([11, 12], dtype=torch.int),
                        "t5xxl_weights": torch.tensor([1.0, 0.5]),
                    }
                return (value, pooled) if return_pooled else value

