    def test_source_modified_noise_hook_contract(self):
        from PIL import Image

        import torch
        from forge_neo.modules import processing, scripts, sd_models, sd_samplers, shared

        random_noise = processing.create_random_tensors(
            (4, 2, 2),
            [101, 102],
            subseeds=[201, 202],
            subseed_strength=0.35,
            seed_resize_from_h=0,
            seed_resize_from_w=0,
        )
        self.assertEqual(tuple(random_noise.shape), (2, 4, 2, 2))

        records: list[tuple[object, ...]] = []

        class NoiseSetter:
            values = {
                "modified txt": 0.25,
                "modified img": 0.5,
                "modified hires": 0.75,
            }

            def process_before_every_sampling(self, p, x, noise, c, uc):
                value = self.values.get(str(getattr(p, "prompt", "")))
                if value is not None and hasattr(noise, "new_full"):
                    p.modified_noise = noise.new_full(tuple(noise.shape), value)

        runner = scripts.ScriptRunner()
        runner.alwayson_scripts.append(NoiseSetter())

        class DirectSampler:
            def __init__(self, name):
                self.config = type("DirectConfig", (), {"name": name})()

            def sample(self, p, x, conditioning, unconditional_conditioning, steps=None, image_conditioning=None):
                records.append(("txt2img", p.prompt, round(float(x.detach().cpu().mean()), 3), p.modified_noise is None))
                if getattr(p, "enable_hr", False):
                    return x.new_zeros((x.shape[0], 4, max(1, p.height // 8), max(1, p.width // 8)))
                return [Image.new("RGB", (p.width, p.height), "red")]

            def sample_img2img(self, p, x, noise, conditioning, unconditional_conditioning, steps=None, image_conditioning=None):
                records.append(("img2img", p.prompt, round(float(noise.detach().cpu().mean()), 3), p.modified_noise is None))
                if getattr(p, "is_hr_pass", False):
                    return torch.ones((1, 3, max(1, int(getattr(p, "hr_upscale_to_y", p.height)) // 8), max(1, int(getattr(p, "hr_upscale_to_x", p.width)) // 8)))
                return [Image.new("RGB", (p.width, p.height), "blue")]

        old_create_sampler = sd_samplers.create_sampler
        old_forge_model_reload = sd_models.forge_model_reload
        old_data_model = sd_models.model_data.sd_model
        old_shared_model = shared.sd_model
        fake_model = sd_models.LightweightForgeModel(
            sd_models.CheckpointInfo("modified-noise-model.safetensors"),
            [],
            None,
        )

        def fake_forge_model_reload():
            sd_models.model_data.set_sd_model(fake_model)
            return fake_model, False

        try:
            sd_samplers.create_sampler = lambda name, _model: DirectSampler(name)
            sd_models.forge_model_reload = fake_forge_model_reload

            txt = processing.StableDiffusionProcessingTxt2Img(
                prompt="modified txt",
                seed=100,
                sampler_name="Euler",
                scheduler="Normal",
                batch_size=1,
                n_iter=1,
                steps=2,
                width=16,
                height=16,
            )
            txt.scripts = runner
            processing.process_images(txt)
            self.assertIsNone(txt.modified_noise)

            img = processing.StableDiffusionProcessingImg2Img(
                prompt="modified img",
                init_images=[Image.new("RGB", (8, 8), "white")],
                seed=101,
                sampler_name="Euler",
                scheduler="Normal",
                batch_size=1,
                n_iter=1,
                steps=2,
                width=16,
                height=16,
            )
            img.scripts = runner
            processing.process_images(img)
            self.assertIsNone(img.modified_noise)

            hires = processing.StableDiffusionProcessingTxt2Img(
                prompt="modified hires",
                seed=102,
                sampler_name="Euler",
                scheduler="Normal",
                batch_size=1,
                n_iter=1,
                steps=2,
                width=64,
                height=64,
                enable_hr=True,
                hr_scale=2.0,
                hr_upscaler="Latent",
                hr_second_pass_steps=3,
            )
            hires.scripts = runner
            hires_processed = processing.process_images(hires)
            self.assertIsNone(hires.modified_noise)
            self.assertTrue(hires.hr_pass_completed)
            self.assertEqual(hires_processed.images[0].size, (128, 128))
        finally:
            sd_samplers.create_sampler = old_create_sampler
            sd_models.forge_model_reload = old_forge_model_reload
            sd_models.model_data.sd_model = old_data_model
            shared.sd_model = old_shared_model

        self.assertIn(("txt2img", "modified txt", 0.25, True), records)
        self.assertIn(("img2img", "modified img", 0.5, True), records)
        self.assertIn(("txt2img", "modified hires", 0.75, True), records)
        self.assertIn(("img2img", "modified hires", 0.75, True), records)

    def test_source_img2img_extra_noise_native_hook_contract(self):
        import torch

        from forge_neo.modules import sd_samplers, sd_samplers_kdiffusion, shared

        class FakePredictor:
            def __init__(self):
                self.sigmas = torch.tensor([0.0, 0.5, 1.0], dtype=torch.float32)

            def sigma_min(self):
                return 0.0

            def sigma_max(self):
                return 1.0

            def timestep(self, sigma):
                return sigma

            def sigma(self, timestep):
                return timestep

            def noise_scaling(self, sigma, noise, latent_image, max_denoise=False):
                return latent_image + noise * 2.0

        fake_unet = type(
            "FakeUnet",
            (),
            {
                "model": type("FakeUnetModel", (), {"predictor": FakePredictor()})(),
                "model_options": {"transformer_options": {}},
            },
        )()
        fake_model = type(
            "FakeModel",
            (),
            {
                "forge_objects": type("FakeForgeObjects", (), {"unet": fake_unet})(),
                "is_webui_legacy_model": lambda self: False,
            },
        )()
        records: list[tuple[object, ...]] = []

        class FakeP:
            scheduler = "Normal"
            hr_scheduler = None
            is_hr_pass = False
            sampler_noise_scheduler_override = None
            steps = 4
            denoising_strength = 0.5
            cfg_scale = 1.0
            eta = None
            s_churn = 0.0
            s_tmin = 0.0
            s_tmax = float("inf")
            s_noise = 1.0
            extra_generation_params: dict[str, object] = {}
            sd_model = fake_model
            seeds = [444]
            prompts = ["extra noise img2img"]
            rng = types.SimpleNamespace(next=lambda: torch.zeros((1, 4, 2, 2), dtype=torch.float32))

            def native_sampler(self, p, **kwargs):
                cfg_denoiser = kwargs["cfg_denoiser"]
                cfg_init_latent = getattr(cfg_denoiser, "init_latent", None)
                sampling_sigmas = p.sd_model.forge_objects.unet.model_options["transformer_options"]["sampling_sigmas"]
                records.append((
                    "hook",
                    round(float(kwargs["x"].detach().cpu().mean()), 3),
                    tuple(getattr(cfg_init_latent, "shape", ()) or ()),
                    round(float(cfg_init_latent.detach().cpu().mean()), 3),
                    len(kwargs["sigmas"]),
                    len(sampling_sigmas),
                    sampling_sigmas is kwargs["sigmas"],
                    kwargs["steps"],
                    kwargs["requested_steps"],
                    kwargs["t_enc"],
                ))
                return kwargs["x"]

        p = FakeP()
        x = torch.zeros((1, 4, 2, 2), dtype=torch.float32)
        p.init_latent = x
        noise = torch.ones_like(x)
        old_shared_model = shared.sd_model
        old_extra_noise = shared.opts.img2img_extra_noise
        old_extra_noise_callback = sd_samplers_kdiffusion.extra_noise_callback

        def fake_extra_noise_callback(params):
            records.append((
                "callback",
                round(float(params.noise.detach().cpu().mean()), 3),
                round(float(params.x.detach().cpu().mean()), 3),
                round(float(params.xi.detach().cpu().mean()), 3),
            ))
            params.noise = params.noise * 3.0

        try:
            shared.sd_model = fake_model
            sampler = sd_samplers.create_sampler("Euler", fake_model)
            shared.opts.set("img2img_extra_noise", 0.25)
            sd_samplers_kdiffusion.extra_noise_callback = fake_extra_noise_callback
            result = sampler.sample_img2img(p, x, noise, conditioning="cond", unconditional_conditioning="uncond")
        finally:
            shared.sd_model = old_shared_model
            shared.opts.set("img2img_extra_noise", old_extra_noise)
            sd_samplers_kdiffusion.extra_noise_callback = old_extra_noise_callback

        self.assertEqual(round(float(result.detach().cpu().mean()), 3), 2.75)
        self.assertEqual(p.extra_generation_params["Extra noise"], 0.25)
        self.assertIn(("callback", 1.0, 0.0, 2.0), records)
        self.assertIn(("hook", 2.75, (1, 4, 2, 2), 0.0, 4, 5, False, 3, 4, 2), records)

    def test_source_txt2img_noise_scaling_native_hook_contract(self):
        import torch

        from forge_neo.modules import sd_samplers, shared

        class FakePredictor:
            def __init__(self):
                self.sigmas = torch.tensor([0.0, 0.5, 1.0], dtype=torch.float32)

            def sigma_min(self):
                return 0.0

            def sigma_max(self):
                return 1.0

            def timestep(self, sigma):
                return sigma

            def sigma(self, timestep):
                return timestep

            def noise_scaling(self, sigma, noise, latent_image, max_denoise=False):
                records.append((
                    "noise_scaling",
                    round(float(sigma), 3),
                    round(float(noise.detach().cpu().mean()), 3),
                    round(float(latent_image.detach().cpu().mean()), 3),
                    bool(max_denoise),
                ))
                return noise * (4.0 if max_denoise else 2.0) + latent_image

        fake_unet = type(
            "FakeUnet",
            (),
            {
                "model": type("FakeUnetModel", (), {"predictor": FakePredictor()})(),
                "model_options": {"transformer_options": {}},
            },
        )()
        fake_model = type(
            "FakeModel",
            (),
            {
                "forge_objects": type("FakeForgeObjects", (), {"unet": fake_unet})(),
                "is_webui_legacy_model": lambda self: False,
            },
        )()
        records: list[tuple[object, ...]] = []

        class FakeP:
            scheduler = "Normal"
            hr_scheduler = None
            is_hr_pass = False
            sampler_noise_scheduler_override = None
            steps = 3
            cfg_scale = 1.0
            eta = None
            s_churn = 0.0
            s_tmin = 0.0
            s_tmax = float("inf")
            s_noise = 1.0
            extra_generation_params: dict[str, object] = {}
            sd_model = fake_model
            seeds = [555]
            prompts = ["noise scaled txt2img"]
            rng = types.SimpleNamespace(next=lambda: torch.zeros((1, 4, 2, 2), dtype=torch.float32))

            def native_sampler(self, p, **kwargs):
                sampling_sigmas = p.sd_model.forge_objects.unet.model_options["transformer_options"]["sampling_sigmas"]
                records.append((
                    "hook",
                    round(float(kwargs["x"].detach().cpu().mean()), 3),
                    len(kwargs["sigmas"]),
                    len(sampling_sigmas),
                    sampling_sigmas is kwargs["sigmas"],
                    kwargs["steps"],
                    kwargs["total_steps"],
                ))
                return kwargs["x"]

        p = FakeP()
        x = torch.ones((1, 4, 2, 2), dtype=torch.float32)
        old_shared_model = shared.sd_model
        old_sgm_noise_multiplier = shared.opts.sgm_noise_multiplier
        try:
            shared.sd_model = fake_model
            sampler = sd_samplers.create_sampler("Euler", fake_model)
            shared.opts.set("sgm_noise_multiplier", True)
            result = sampler.sample(p, x, conditioning="cond", unconditional_conditioning="uncond")
        finally:
            shared.sd_model = old_shared_model
            shared.opts.set("sgm_noise_multiplier", old_sgm_noise_multiplier)

        self.assertEqual(round(float(result.detach().cpu().mean()), 3), 4.0)
        self.assertTrue(p.extra_generation_params["SGM noise multiplier"])
        self.assertIn(("noise_scaling", 1.0, 1.0, 0.0, True), records)
        self.assertIn(("hook", 4.0, 4, 4, True, 3, 3), records)

    def test_source_kdiffusion_native_hook_sampler_kwargs_contract(self):
        import torch

        from forge_neo.modules import sd_samplers, shared

        records: list[tuple[object, ...]] = []

        class FakePredictor:
            def __init__(self):
                self.sigmas = torch.tensor([0.0, 0.25, 0.5, 0.75, 1.0], dtype=torch.float32)

            def sigma_min(self):
                return 0.0

            def sigma_max(self):
                return 1.0

            def timestep(self, sigma):
                return sigma

            def sigma(self, timestep):
                return timestep

            def noise_scaling(self, sigma, noise, latent_image, max_denoise=False):
                records.append(("noise_scaling", round(float(sigma), 3), round(float(noise.detach().cpu().mean()), 3), bool(max_denoise)))
                return noise + latent_image

        fake_unet = type(
            "FakeUnet",
            (),
            {
                "model": type("FakeUnetModel", (), {"predictor": FakePredictor()})(),
                "model_options": {"transformer_options": {}},
            },
        )()
        fake_model = type(
            "FakeModel",
            (),
            {
                "forge_objects": type("FakeForgeObjects", (), {"unet": fake_unet})(),
                "is_webui_legacy_model": lambda self: False,
            },
        )()

        class FakeP:
            scheduler = "Normal"
            hr_scheduler = None
            is_hr_pass = False
            sampler_noise_scheduler_override = None
            steps = 4
            denoising_strength = 0.5
            cfg_scale = 1.5
            eta = 0.25
            s_churn = 0.0
            s_tmin = 0.0
            s_tmax = float("inf")
            s_noise = 0.75
            r = 0.4
            extra_generation_params: dict[str, object] = {}
            sd_model = fake_model
            seeds = [901, 902]
            prompts = ["sde kwargs"]
            rng = types.SimpleNamespace(next=lambda: torch.zeros((1, 4, 2, 2), dtype=torch.float32))

            def native_sampler(self, p, **kwargs):
                sampler_kwargs = dict(kwargs["sampler_kwargs"])
                records.append((
                    "hook",
                    kwargs["mode"],
                    kwargs["sampler"],
                    len(kwargs["sigmas"]),
                    kwargs["steps"],
                    kwargs["total_steps"],
                    kwargs["requested_steps"],
                    kwargs["t_enc"],
                    round(float(kwargs["x"].detach().cpu().mean()), 3),
                    sampler_kwargs.get("eta"),
                    sampler_kwargs.get("s_noise"),
                    sampler_kwargs.get("r"),
                    sampler_kwargs.get("noise_sampler"),
                    "sigmas" in sampler_kwargs,
                ))
                return kwargs["x"]

        noise_sampler_calls = []

        def fake_create_noise_sampler(x, sigmas, p):
            value = f"brownian-{len(noise_sampler_calls)}"
            noise_sampler_calls.append((value, tuple(getattr(sigmas, "shape", ()) or ()), round(float(x.detach().cpu().mean()), 3)))
            return value

        p = FakeP()
        x = torch.ones((1, 4, 2, 2), dtype=torch.float32)
        old_shared_model = shared.sd_model
        try:
            shared.sd_model = fake_model
            sampler = sd_samplers.create_sampler("DPM++ SDE", fake_model)
            sampler.create_noise_sampler = fake_create_noise_sampler
            sampler.model_wrap_cfg.padded_cond_uncond = True
            sampler.model_wrap_cfg.padded_cond_uncond_v0 = True
            txt_result = sampler.sample(p, x, conditioning="cond", unconditional_conditioning="uncond", image_conditioning="image-cond")
            img_result = sampler.sample_img2img(
                p,
                torch.zeros((1, 4, 2, 2), dtype=torch.float32),
                torch.ones((1, 4, 2, 2), dtype=torch.float32),
                conditioning="img-cond",
                unconditional_conditioning="img-uncond",
                image_conditioning="img-image-cond",
            )
        finally:
            shared.sd_model = old_shared_model

        self.assertEqual(tuple(txt_result.shape), (1, 4, 2, 2))
        self.assertEqual(tuple(img_result.shape), (1, 4, 2, 2))
        self.assertEqual(p.extra_generation_params["Eta"], 0.25)
        self.assertTrue(p.extra_generation_params["Pad conds"])
        self.assertTrue(p.extra_generation_params["Pad conds v0"])
        self.assertEqual(noise_sampler_calls[0][0], "brownian-0")
        self.assertEqual(noise_sampler_calls[1][0], "brownian-1")
        self.assertIn(("hook", "txt2img", "DPM++ SDE", 5, 4, 8, None, None, 1.0, 0.25, 0.75, 0.4, "brownian-0", False), records)
        img_hook = next(row for row in records if row[1] == "img2img")
        self.assertEqual(img_hook[2:8], ("DPM++ SDE", 4, 3, 3, 4, 2))
        self.assertGreater(img_hook[8], 0.0)
        self.assertEqual(img_hook[9:], (0.25, 0.75, 0.4, "brownian-1", False))

        source = Path(ROOT, "forge_neo", "modules", "sd_samplers_kdiffusion.py").read_text(encoding="utf-8")
        self.assertNotIn("def _source_sampler_kwargs", source)
        cfg_block = source[source.index("class CFGDenoiserKDiffusion"):source.index("class KDiffusionSampler")]
        self.assertIn("self.model_wrap = k_external.ForgeScheduleLinker(shared.sd_model.forge_objects.unet.model.predictor)", cfg_block)
