    def test_source_timestep_compvis_sampler_native_hook_contract(self):
        import torch

        from forge_neo.modules import sd_sampler_executor, sd_samplers, sd_samplers_common, sd_samplers_timesteps, shared

        class FakePredictor:
            sigmas = torch.linspace(0.01, 1.0, 1000, dtype=torch.float32)

        fake_unet = type(
            "FakeUnet",
            (),
            {
                "model": type("FakeUnetModel", (), {"predictor": FakePredictor()})(),
                "model_options": {"transformer_options": {}},
            },
        )()
        fake_model = type(
            "FakeCompVisModel",
            (),
            {
                "forge_objects": type("FakeForgeObjects", (), {"unet": fake_unet})(),
                "alphas_cumprod": torch.linspace(0.999, 0.001, 1000),
                "is_webui_legacy_model": lambda self: False,
            },
        )()
        records: list[tuple[object, ...]] = []

        class FakeTxtP:
            scheduler = "DDIM"
            steps = 4
            cfg_scale = 1.25
            eta = 0.33
            extra_generation_params: dict[str, object] = {}
            sd_model = fake_model
            seeds = [777]
            prompts = ["ddim txt2img hook"]
            rng = types.SimpleNamespace(next=lambda: torch.zeros((1, 4, 2, 2), dtype=torch.float32))

            def native_sampler(self, p, **kwargs):
                records.append((
                    "txt_hook",
                    kwargs["mode"],
                    kwargs["sampler"],
                    tuple(int(item) for item in kwargs["timesteps"].detach().cpu().tolist()),
                    kwargs["sigmas"],
                    kwargs["steps"],
                    kwargs["total_steps"],
                    round(float(kwargs["x"].detach().cpu().mean()), 3),
                    kwargs["sampler_kwargs"],
                    bool(getattr(kwargs["cfg_denoiser"], "classic_ddim_eps_estimation", False)),
                    kwargs["sampler_extra_args"]["cond"],
                    kwargs["sampler_extra_args"]["uncond"],
                    kwargs["sampler_extra_args"]["cond_scale"],
                    kwargs["sampler_extra_args"]["image_cond"],
                ))
                return kwargs["x"] + 7.0

        class FakeImgP:
            scheduler = "PLMS"
            steps = 4
            denoising_strength = 0.5
            cfg_scale = 1.5
            eta = None
            extra_generation_params: dict[str, object] = {}
            sd_model = fake_model
            seeds = [888]
            prompts = ["plms img2img hook"]
            rng = types.SimpleNamespace(next=lambda: torch.zeros((1, 4, 2, 2), dtype=torch.float32))

            def native_sampler(self, p, **kwargs):
                init_latent = getattr(kwargs["cfg_denoiser"], "init_latent", None)
                records.append((
                    "img_hook",
                    kwargs["mode"],
                    kwargs["sampler"],
                    tuple(int(item) for item in kwargs["timesteps"].detach().cpu().tolist()),
                    kwargs["steps"],
                    kwargs["total_steps"],
                    kwargs["requested_steps"],
                    kwargs["t_enc"],
                    round(float(kwargs["x"].detach().cpu().mean()), 3),
                    round(float(init_latent.detach().cpu().mean()), 3),
                    kwargs["sampler_kwargs"],
                ))
                return kwargs["x"] + 3.0

        old_shared_model = shared.sd_model
        old_extra_noise = shared.opts.img2img_extra_noise
        old_extra_noise_callback = sd_samplers_timesteps.extra_noise_callback

        def fake_extra_noise_callback(params):
            records.append((
                "img_extra_noise",
                round(float(params.noise.detach().cpu().mean()), 3),
                round(float(params.x.detach().cpu().mean()), 3),
                round(float(params.xi.detach().cpu().mean()), 3),
            ))
            params.noise = params.noise * 2.0

        try:
            shared.sd_model = fake_model
            ddim_sampler = sd_samplers.create_sampler("DDIM", fake_model)
            txt_p = FakeTxtP()
            txt_x = torch.ones((1, 4, 2, 2), dtype=torch.float32)
            txt_result = ddim_sampler.sample(
                txt_p,
                txt_x,
                conditioning="cond",
                unconditional_conditioning="uncond",
                image_conditioning="image-cond",
            )
            shared.opts.set("img2img_extra_noise", 0.25)
            sd_samplers_timesteps.extra_noise_callback = fake_extra_noise_callback
            plms_sampler = sd_samplers.create_sampler("PLMS", fake_model)
            img_p = FakeImgP()
            init_latent = torch.zeros((1, 4, 2, 2), dtype=torch.float32)
            noise = torch.ones_like(init_latent)
            img_result = plms_sampler.sample_img2img(
                img_p,
                init_latent,
                noise,
                conditioning="img-cond",
                unconditional_conditioning="img-uncond",
            )
        finally:
            shared.sd_model = old_shared_model
            shared.opts.set("img2img_extra_noise", old_extra_noise)
            sd_samplers_timesteps.extra_noise_callback = old_extra_noise_callback

        self.assertEqual(round(float(txt_result.detach().cpu().mean()), 3), 8.0)
        self.assertEqual(txt_p.extra_generation_params["Eta DDIM"], 0.33)
        self.assertIn((
            "txt_hook",
            "txt2img",
            "DDIM",
            (1, 251, 501, 751),
            None,
            4,
            4,
            1.0,
            {"eta": 0.33},
            True,
            "cond",
            "uncond",
            1.25,
            "image-cond",
        ), records)
        self.assertGreater(round(float(img_result.detach().cpu().mean()), 3), 3.0)
        self.assertEqual(img_p.extra_generation_params["Extra noise"], 0.25)
        self.assertTrue(any(row[0] == "img_extra_noise" for row in records))
        img_hook = next(row for row in records if row[0] == "img_hook")
        self.assertEqual(img_hook[1:8], ("img2img", "PLMS", (1, 251), 3, 3, 4, 2))
        self.assertGreater(img_hook[8], 0.0)
        self.assertEqual(img_hook[9], 0.0)
        self.assertEqual(img_hook[10], {})

        no_hook_p = type("NoHookP", (), {"sd_model": fake_model})()
        old_ready = sd_sampler_executor.NATIVE_REAL_MODEL_READY
        old_executor = sd_samplers.SAMPLER_EXECUTOR
        try:
            sd_sampler_executor.NATIVE_REAL_MODEL_READY = False
            sd_samplers.set_sampler_executor(sd_sampler_executor.default_executor)
            self.assertIsNone(sd_samplers_common.native_sampler_hook(no_hook_p))
            sd_sampler_executor.NATIVE_REAL_MODEL_READY = True
            self.assertIs(sd_samplers_common.native_sampler_hook(no_hook_p), sd_sampler_executor.default_executor)
        finally:
            sd_sampler_executor.NATIVE_REAL_MODEL_READY = old_ready
            sd_samplers.set_sampler_executor(old_executor)

