    def test_source_timestep_img2img_uses_shared_model_alphas_contract(self):
        import torch

        from forge_neo.modules import sd_samplers, sd_samplers_timesteps, shared

        class FakePredictor:
            sigmas = torch.ones(1000, dtype=torch.float32) * ((1.0 / 0.81 - 1.0) ** 0.5)

        class FakeUnet:
            model = type("FakeUnetModel", (), {"predictor": FakePredictor(), "computation_dtype": torch.float32})()
            model_options = {"transformer_options": {}}
