        source = Path(ROOT, "forge_neo", "modules", "sd_samplers_timesteps.py").read_text(encoding="utf-8")
        img_block = source[source.index("    def sample_img2img"):source.index("    def sample(self, p, x")]
        self.assertIn("alphas_cumprod = shared.sd_model.alphas_cumprod", img_block)
        self.assertNotIn("            alphas_cumprod = self.model_wrap.inner_model.alphas_cumprod\n", img_block)

