    def test_source_cfg_denoiser_pad_cond_inplace_contract(self):
        import torch

        from forge_neo.modules import sd_samplers_cfg_denoiser

        crossattn = torch.ones((1, 2, 3), dtype=torch.float32)
        other = torch.zeros((1, 1), dtype=torch.float32)
        cond = {"crossattn": crossattn, "other": other}
        empty = torch.zeros((1, 1, 3), dtype=torch.float32)

        padded = sd_samplers_cfg_denoiser.pad_cond(cond, 2, empty)

        self.assertIs(padded, cond)
