        self.assertEqual(tuple(padded["crossattn"].shape), (1, 4, 3))
        self.assertEqual(float(padded["crossattn"][:, :2, :].sum()), 6.0)
        self.assertEqual(float(padded["crossattn"][:, 2:, :].sum()), 0.0)

