    def test_source_refiner_non_fast_reload_contract(self):
        from forge_neo.runtime_backend.sampling import condition, sampling_function
        from forge_neo.modules import sd_models, sd_samplers_common, shared

        records: list[tuple[object, ...]] = []
        base_info = types.SimpleNamespace(short_title="base-title", filename="base.safetensors")
        refiner_info = types.SimpleNamespace(short_title="refiner-title", filename="refiner.safetensors")
        base_unet = types.SimpleNamespace(name="base-unet")
        refiner_unet = types.SimpleNamespace(name="refiner-unet")

        def fake_get_checkpoint_match(name):
            return {
                "base-title": base_info,
                "refiner-title": refiner_info,
            }.get(str(name or ""))

        def fake_refresh_model_loading_parameters():
            records.append(("refresh", shared.opts.sd_model_checkpoint))
            return {"checkpoint": shared.opts.sd_model_checkpoint}

        def fake_forge_model_reload():
            records.append(("reload", shared.opts.sd_model_checkpoint))
            shared.sd_model = types.SimpleNamespace(sd_checkpoint_info=refiner_info, forge_objects=types.SimpleNamespace(unet=refiner_unet))
            return shared.sd_model, True

        def fake_sampling_cleanup(unet):
            records.append(("cleanup", getattr(unet, "name", None)))

        def fake_sampling_prepare(unet, *, x=None, **_kwargs):
            records.append(("prepare", getattr(unet, "name", None), x == "latent-x"))
            return unet

        class FakeProcessing:
            refiner_switch_at = 0.5
            refiner_checkpoint_info = refiner_info
            enable_hr = False
            disable_extra_networks = True
            extra_generation_params: dict[str, object]
            extra_network_data: dict[str, object]

            def __init__(self):
                self.extra_generation_params = {}
                self.extra_network_data = {"lora": []}

            def setup_conds(self):
                records.append(("setup_conds",))

        class FakeDenoiser:
            total_steps = 10
            step = 6

            def __init__(self):
                self.p = FakeProcessing()
                self.model_wrap = object()

            def update_inner_model(self):
                records.append(("update_inner_model", not hasattr(self, "model_wrap")))
                self.model_wrap = "reloaded-wrap"

        old_shared_model = shared.sd_model
        old_checkpoint = shared.opts.sd_model_checkpoint
        old_refiner_fast_sd = shared.opts.refiner_fast_sd
        old_refiner_use_steps = shared.opts.refiner_use_steps
