    def test_source_extra_networks_refiner_activation_contract(self):
        from forge_neo.modules import extra_networks, sd_samplers_common, shared

        calls: list[tuple[object, ...]] = []

        class FakeExtraNetwork(extra_networks.ExtraNetwork):
            def activate(self, p, params_list):
                calls.append(("activate", self.name, [list(params.items) for params in params_list]))

            def deactivate(self, p):
                calls.append(("deactivate", self.name))

        class FakeScripts:
            def after_extra_networks_activate(self, p, **kwargs):
                calls.append(("after", kwargs["batch_number"], kwargs["prompts"], kwargs["seeds"], sorted(kwargs["extra_network_data"].keys())))

        old_replacement = shared.opts.refiner_lora_replacement
        try:
            extra_networks.initialize()
            extra_networks.register_extra_network(FakeExtraNetwork("lora"))
            shared.opts.set("refiner_lora_replacement", "old_lora=new_lora")
            self.assertEqual(sd_samplers_common._parse_replacements(), [("old_lora", "new_lora")])

            original = [types.SimpleNamespace(items=["old_lora", "0.7", "te=0.5"])]
            replaced = sd_samplers_common.apply_lora_for_refiner(original)
            self.assertIsInstance(replaced[0], extra_networks.ExtraNetworkParams)
            self.assertEqual(replaced[0].items, ["new_lora", "0.7", "te=0.5"])
            self.assertEqual(original[0].items, ["new_lora", "0.7", "te=0.5"])
            self.assertEqual(replaced[0].positional, ["new_lora", "0.7"])
            self.assertEqual(replaced[0].named, {"te": "0.5"})

            shared.opts.set("refiner_lora_replacement", "bad replacement line")
            with self.assertRaises(ValueError):
                sd_samplers_common.apply_lora_for_refiner([types.SimpleNamespace(items=["old_lora", "0.7"])])

            p = types.SimpleNamespace(scripts=FakeScripts(), iteration=2, prompts=["prompt"], seeds=[101], subseeds=[202])
            extra_networks.activate(p, {"lora": replaced})
            self.assertEqual(calls, [("activate", "lora", [["new_lora", "0.7", "te=0.5"]]), ("after", 2, ["prompt"], [101], ["lora"])])

            cleaned_prompt, parsed = extra_networks.parse_prompt("a <lora:test:0.5> image")
            self.assertEqual(cleaned_prompt, "a  image")
            self.assertEqual(parsed["lora"][0].items, ["test", "0.5"])

            extra_networks.deactivate(p, {"lora": replaced})
            self.assertEqual(calls[-1], ("deactivate", "lora"))
        finally:
            shared.opts.set("refiner_lora_replacement", old_replacement)
            extra_networks.initialize()

        source = Path(ROOT, "forge_neo", "modules", "extra_networks.py").read_text(encoding="utf-8")
        self.assertIn("class ExtraNetworkParams", source)
        self.assertIn("def activate(p, extra_network_data)", source)
        self.assertIn("def parse_prompt(prompt)", source)
        self.assertIn("after_extra_networks_activate", source)
        samplers_common_source = Path(ROOT, "forge_neo", "modules", "sd_samplers_common.py").read_text(encoding="utf-8")
        parse_block = samplers_common_source[
            samplers_common_source.index("def _parse_replacements()") : samplers_common_source.index("def apply_lora_for_refiner")
        ]
        self.assertIn('for entry in opts.refiner_lora_replacement.split("\\n")', parse_block)
        self.assertNotIn("shared.opts.refiner_lora_replacement", parse_block)
        self.assertIn('before, after = entry.split("=", 1)', parse_block)
        self.assertNotIn("try:", parse_block)
        self.assertNotIn("if not entry.strip()", parse_block)
        self.assertIn("items: list[str | float] = lora.items", samplers_common_source)
        self.assertNotIn("items = lora.items", samplers_common_source)
        self.assertIn("assert isinstance(items[0], str)", samplers_common_source)
        self.assertIn("lora_replacements = _parse_replacements()", samplers_common_source)
        self.assertIn("result.append(extra_networks.ExtraNetworkParams(items))", samplers_common_source)
        self.assertNotIn("clone = type(lora)(items)", samplers_common_source)

    def test_source_brownian_noise_sampler_current_iter_seeds_contract(self):
        import torch

        from forge_neo.modules import sd_samplers_common
        from forge_neo.modules_forge.packages.k_diffusion import sampling as k_sampling

        calls: list[dict[str, object]] = []

        class FakeBrownianTreeNoiseSampler:
            def __init__(self, x, sigma_min, sigma_max, seed=None):
                calls.append(
                    {
                        "shape": tuple(x.shape),
                        "sigma_min": round(float(sigma_min.detach().cpu()), 3),
                        "sigma_max": round(float(sigma_max.detach().cpu()), 3),
                        "seed": list(seed or []),
                    }
                )

        old_brownian = k_sampling.BrownianTreeNoiseSampler
        try:
            k_sampling.BrownianTreeNoiseSampler = FakeBrownianTreeNoiseSampler
            sampler = sd_samplers_common.Sampler("sample_dpmpp_sde")
            p = types.SimpleNamespace(all_seeds=[10, 11, 12, 13, 14, 15], iteration=1, batch_size=2)
            result = sampler.create_noise_sampler(
                torch.zeros((1, 4, 2, 2)),
                torch.tensor([1.0, 0.5, 0.0], dtype=torch.float32),
                p,
            )
            with self.assertRaises(RuntimeError):
                sampler.create_noise_sampler(
                    torch.zeros((1, 4, 2, 2)),
                    torch.tensor([0.0, 0.0], dtype=torch.float32),
                    p,
                )
        finally:
            k_sampling.BrownianTreeNoiseSampler = old_brownian

        self.assertIsInstance(result, FakeBrownianTreeNoiseSampler)
        self.assertEqual(calls, [{"shape": (1, 4, 2, 2), "sigma_min": 0.5, "sigma_max": 1.0, "seed": [12, 13]}])

        source = Path(ROOT, "forge_neo", "modules", "sd_samplers_common.py").read_text(encoding="utf-8")
        create_noise_block = source[source.find("def create_noise_sampler"):source.find("def sample(")]
        self.assertNotIn("def _source_current_iter_seeds", source)
        self.assertIn("# manually create noise sampler to enable deterministic results across different batch sizes", create_noise_block)
        self.assertIn("sigma_min, sigma_max = sigmas[sigmas > 0].min(), sigmas.max()", create_noise_block)
        self.assertIn("current_iter_seeds = p.all_seeds[p.iteration * p.batch_size : (p.iteration + 1) * p.batch_size]", create_noise_block)
        self.assertIn("return k_sampling.BrownianTreeNoiseSampler(x, sigma_min, sigma_max, seed=current_iter_seeds)", create_noise_block)
        self.assertNotIn("getattr(p,", create_noise_block)
        self.assertNotIn("except Exception", create_noise_block)
        self.assertNotIn("return None", create_noise_block)

    def test_source_flux_realistic_executor_alias_contract(self):
        import torch

        from forge_neo import models
        from forge_neo.modules import sd_sampler_executor, sd_samplers

        normal_methods = models.sampling_methods({"forbidden_knowledge": False, "hide_samplers": []})
        self.assertIn("DPM++ 2s a RF", normal_methods)
        self.assertNotIn("Flux Realistic", normal_methods)
        forbidden_methods = models.sampling_methods({"forbidden_knowledge": True, "hide_samplers": []})
        self.assertIn("Flux Realistic", forbidden_methods)
        self.assertNotIn("DPM++ 2s a RF", forbidden_methods)
        hidden_methods = models.sampling_methods({"forbidden_knowledge": True, "hide_samplers": ["Flux Realistic"]})
        self.assertNotIn("Flux Realistic", hidden_methods)
        self.assertIn("Flux Realistic", models.sampling_methods({"forbidden_knowledge": True, "hide_samplers": ["Flux Realistic"]}, include_hidden=True))
        self.assertEqual(sd_samplers.find_sampler_config("Flux Realistic").name, "DPM++ 2s a RF")

        records: list[tuple[object, ...]] = []

        def fake_rf(model, x, sigmas, extra_args=None, callback=None, disable=False, **kwargs):
            records.append((
                "rf",
                tuple(float(item) for item in sigmas.detach().cpu().tolist()),
                extra_args.get("cond"),
                extra_args.get("uncond"),
                extra_args.get("cond_scale"),
                kwargs,
            ))
            return x + 4.0

        def fake_euler(*_args, **_kwargs):
            records.append(("euler",))
            return torch.ones((1, 4, 2, 2)) * -99.0

        old_sampling_module = sd_sampler_executor._sampling_module
        try:
            sd_sampler_executor._sampling_module = lambda: types.SimpleNamespace(
                sample_dpmpp_2s_ancestral_RF=fake_rf,
                sample_euler=fake_euler,
            )
            p = type("FluxRealisticP", (), {"extra_generation_params": {}, "width": 16, "height": 16, "cfg_scale": 1.25})()
            result = sd_sampler_executor.NativeSamplerExecutor().sample(
                p,
                sampler="Flux Realistic",
                x=torch.zeros((1, 4, 2, 2)),
                sigmas=torch.tensor([1.0, 0.5, 0.0]),
                cfg_denoiser=object(),
                sampler_extra_args={"cond": "cond", "uncond": "uncond", "cond_scale": 1.25},
                sampler_kwargs={"custom": "value"},
            )
        finally:
            sd_sampler_executor._sampling_module = old_sampling_module

        self.assertEqual(round(float(result.detach().cpu().mean()), 3), 4.0)
        self.assertEqual(records, [("rf", (1.0, 0.5, 0.0), "cond", "uncond", 1.25, {"custom": "value"})])
        self.assertEqual(p.extra_generation_params["Native Sampler Executor"], "forge_neo.modules.sd_sampler_executor")
        self.assertEqual(p.extra_generation_params["Native Sampler Latent Shape"], (1, 4, 2, 2))

