    def test_source_scheduler_sigma_to_t_tensor_contract(self):
        import torch

        from forge_neo.modules import sd_schedulers

        calls: list[tuple[str, bool, float]] = []

        class TensorStrictPredictor:
            def sigma_to_t(self, sigma):
                calls.append(("sigma_to_t", isinstance(sigma, torch.Tensor), round(float(sigma.detach().cpu()), 3)))
                if not isinstance(sigma, torch.Tensor):
                    raise TypeError("sigma must be tensor")
                return sigma * 10

            def t_to_sigma(self, timestep):
                calls.append(("t_to_sigma", isinstance(timestep, torch.Tensor), round(float(timestep.detach().cpu()), 3)))
                return timestep / 10

        sigmas = sd_schedulers.normal_scheduler(3, 0.1, 1.0, TensorStrictPredictor(), "cpu")
        self.assertEqual([round(float(item), 3) for item in sigmas], [1.0, 0.55, 0.1, 0.0])
        self.assertEqual(calls[0], ("sigma_to_t", True, 1.0))
        self.assertEqual(calls[1], ("sigma_to_t", True, 0.1))
        self.assertTrue(all(call[1] for call in calls))

        scheduler_source = Path(ROOT, "forge_neo", "modules", "sd_schedulers.py").read_text(encoding="utf-8")
        self.assertIn("inner_model.sigma_to_t(torch.tensor(sigma_max))", scheduler_source)
        self.assertIn("inner_model.sigma_to_t(torch.tensor(sigma_min))", scheduler_source)
        self.assertIn("inner_model.t_to_sigma(ts)", scheduler_source)
        self.assertNotIn("def _sigma_to_t", scheduler_source)
        self.assertNotIn("def _t_to_sigma", scheduler_source)
        self.assertNotIn("def _model_sigmas", scheduler_source)

    def test_source_basic_schedulers_direct_inner_model_contract(self):
        import torch

        from forge_neo.modules import sd_schedulers

        class DirectInnerModel:
            sigmas = torch.tensor([0.0, 0.1, 0.5, 1.0], dtype=torch.float32)

            def __init__(self):
                self.get_sigmas_calls = []

            def sigma_to_t(self, sigma):
                return sigma * 10

            def t_to_sigma(self, timestep):
                return timestep / 10

            def get_sigmas(self, n):
                self.get_sigmas_calls.append(int(n))
                return torch.tensor([1.0, 0.5, 0.0], dtype=torch.float32)

        inner_model = DirectInnerModel()

        simple = sd_schedulers.simple_scheduler(2, 0.1, 1.0, inner_model, "cpu")
        uniform = sd_schedulers.uniform(2, 0.1, 1.0, inner_model, "cpu")
        sgm = sd_schedulers.sgm_uniform(3, 0.1, 1.0, inner_model, "cpu")
        ddim = sd_schedulers.ddim_scheduler(2, 0.1, 1.0, inner_model, "cpu")

        self.assertEqual([round(float(item), 3) for item in simple], [1.0, 0.1, 0.0])
        self.assertEqual([round(float(item), 3) for item in uniform], [1.0, 0.5, 0.0])
        self.assertEqual(inner_model.get_sigmas_calls, [2])
        self.assertEqual([round(float(item), 3) for item in sgm], [1.0, 0.7, 0.4, 0.0])
