    def test_source_math_flowmatch_schedulers_direct_contract(self):
        import types
        import torch

        from forge_neo.modules import sd_schedulers, shared

        previous_sd_model = shared.sd_model
        option_names = [
            "use_dynamic_shifting",
            "invert_sigmas",
            "use_karras_sigmas",
            "use_exponential_sigmas",
            "use_beta_sigmas",
            "stochastic_sampling",
        ]
        previous_opts = {name: getattr(shared.opts, name) for name in option_names}
        try:
            shared.sd_model = types.SimpleNamespace(is_sdxl=True)
            for name in option_names:
                setattr(shared.opts, name, False)

            linear = sd_schedulers.linear_quadratic(4, 0.1, 1.0, "cpu")
            kl = sd_schedulers.kl_optimal(4, 0.1, 1.0, "cpu")
            align = sd_schedulers.get_align_your_steps_sigmas(4, 0.1, 1.0, "cpu")
            bong = sd_schedulers.bong_tangent_scheduler(4, 0.1, 1.0, "cpu")

            self.assertIsInstance(linear, torch.Tensor)
            self.assertEqual(tuple(linear.shape), (5,))
            self.assertEqual(tuple(kl.shape), (5,))
            self.assertEqual(tuple(align.shape), (5,))
            self.assertEqual(tuple(bong.shape), (5,))

            fake_predictor = types.SimpleNamespace(shift=2.0)
            fake_unet = types.SimpleNamespace(model=types.SimpleNamespace(predictor=fake_predictor))
            inner_model = types.SimpleNamespace(
                inner_model=types.SimpleNamespace(
                    forge_objects=types.SimpleNamespace(unet=fake_unet)
                )
            )
            flow = sd_schedulers.flow_match_euler_discrete_scheduler(2, 0.1, 1.0, inner_model, "cpu")
            self.assertIsInstance(flow, torch.Tensor)
            self.assertEqual(flow.device.type, "cpu")
            self.assertGreaterEqual(int(flow.numel()), 2)
        finally:
            shared.sd_model = previous_sd_model
            for name, value in previous_opts.items():
                setattr(shared.opts, name, value)

