        self.assertIn("step_indices = torch.arange(n + 1, device=device)", scheduler_source)
        self.assertIn("unet = inner_model.inner_model.forge_objects.unet", scheduler_source)
        self.assertIn('"use_dynamic_shifting": shared.opts.use_dynamic_shifting', scheduler_source)
        self.assertIn("scheduler.set_timesteps(n, device=device, mu=0.0)", scheduler_source)
        self.assertNotIn("def _tensor(", scheduler_source)
        self.assertNotIn("def _torch_module(", scheduler_source)
