    def test_source_condition_constant_init_contract(self):
        import ast

        target_path = Path(ROOT, "forge_neo", "webui", "backend", "sampling", "condition.py")
        spec = importlib.util.spec_from_file_location("forge_neo_source_condition_contract", target_path)
        self.assertIsNotNone(spec)
        self.assertIsNotNone(spec.loader)
        condition = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(condition)

        const = condition.ConditionConstant("constant-cond")
        processed = const.process_cond(batch_size=4, device="cpu")

        self.assertEqual(const.cond, "constant-cond")
        self.assertIsInstance(processed, condition.ConditionConstant)
        self.assertIsNot(processed, const)
        self.assertEqual(processed.cond, "constant-cond")
        self.assertTrue(const.can_concat(condition.ConditionConstant("constant-cond")))
        self.assertFalse(const.can_concat(condition.ConditionConstant("other-cond")))
        self.assertEqual(const.concat([condition.ConditionConstant("constant-cond")]), "constant-cond")

        source_path = Path(ROOT, "..", "sd-webui-forge-classic", "backend", "sampling", "condition.py").resolve()
        target_source = target_path.read_text(encoding="utf-8")
        self.assertIn("class ConditionConstant(Condition):\n    def __init__(self, cond)", target_source)
        self.assertIn("self.cond = cond", target_source)

        def function_names(path: Path):
            tree = ast.parse(path.read_text(encoding="utf-8"))
            names = set()
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    names.add(node.name)
                elif isinstance(node, ast.ClassDef):
                    for child in node.body:
                        if isinstance(child, ast.FunctionDef):
                            names.add(f"{node.name}.{child.name}")
            return names

        self.assertEqual(sorted(function_names(source_path) - function_names(target_path)), [])

    def test_source_condition_classes_direct_torch_contract(self):
        import torch

        from forge_neo.runtime_backend.sampling import condition

        left = condition.Condition(torch.ones((1, 2)))
        right = condition.Condition(torch.ones((1, 2)) * 2)
        different = condition.Condition(torch.ones((1, 3)))
        concatenated = left.concat([right])
        self.assertTrue(left.can_concat(right))
        self.assertFalse(left.can_concat(different))
        self.assertEqual(tuple(concatenated.shape), (2, 2))
        self.assertEqual(round(float(concatenated.detach().cpu().mean()), 3), 1.5)

        short = condition.ConditionCrossAttn(torch.ones((1, 2, 3)))
        long = condition.ConditionCrossAttn(torch.ones((1, 4, 3)) * 2)
        cross = short.concat([long])
        self.assertTrue(short.can_concat(long))
        self.assertEqual(tuple(cross.shape), (2, 4, 3))
        self.assertEqual(round(float(cross[0].detach().cpu().mean()), 3), 1.0)
        self.assertEqual(round(float(cross[1].detach().cpu().mean()), 3), 2.0)

