        self.assertIn("def concat(self, others):\n        conds = [self.cond]\n        for x in others:\n            conds.append(x.cond)\n        return torch.cat(conds)", source)
        self.assertIn("for x in others:\n            c = x.cond", source)
        self.assertIn("return torch.cat(out)", source)
