    def test_source_condition_compilers_direct_paths_contract(self):
        import torch

        from forge_neo.runtime_backend.sampling import condition

        tensor_cond = torch.ones((1, 2, 3), dtype=torch.float32)
        tensor_compiled = condition.compile_conditions(tensor_cond)
        self.assertEqual(tuple(tensor_compiled[0]["cross_attn"].shape), (1, 2, 3))
        self.assertIn("c_crossattn", tensor_compiled[0]["model_conds"])
        self.assertNotIn("pooled_output", tensor_compiled[0])

        dict_cond = {
            "crossattn": torch.ones((1, 2, 3), dtype=torch.float32) * 2,
            "vector": torch.ones((1, 4), dtype=torch.float32) * 3,
            "guidance": torch.ones((1, 1), dtype=torch.float32) * 4,
        }
        dict_compiled = condition.compile_conditions(dict_cond)
        self.assertEqual(tuple(dict_compiled[0]["cross_attn"].shape), (1, 2, 3))
        self.assertEqual(tuple(dict_compiled[0]["pooled_output"].shape), (1, 4))
        self.assertIn("y", dict_compiled[0]["model_conds"])
        self.assertIn("guidance", dict_compiled[0]["model_conds"])

        class AdvancedCondition(dict):
            def __init__(self):
                super().__init__(
                    crossattn=torch.arange(12, dtype=torch.float32).reshape(2, 2, 3),
                    vector=torch.arange(8, dtype=torch.float32).reshape(2, 4),
                )
                self.calls = []

            def advanced_indexing(self, indices):
                self.calls.append(tuple(indices))
                return {
                    "crossattn": self["crossattn"][indices],
                    "vector": self["vector"][indices],
                }

        advanced_cond = AdvancedCondition()
        weighted = condition.compile_weighted_conditions(advanced_cond, [[(0, 0.25)], [(1, 0.75)]])
        self.assertEqual(advanced_cond.calls, [(0, 1)])
        self.assertEqual(len(weighted), 1)
        self.assertEqual(weighted[0]["strength"], 0.75)
        self.assertEqual(tuple(weighted[0]["cross_attn"].shape), (2, 2, 3))
        self.assertEqual(tuple(weighted[0]["pooled_output"].shape), (2, 4))

        pair_cond = [
            [torch.ones((1, 2, 3), dtype=torch.float32), {"pooled_output": torch.ones((1, 4), dtype=torch.float32)}],
            [torch.ones((1, 2, 3), dtype=torch.float32) * 2, {"pooled_output": torch.ones((1, 4), dtype=torch.float32) * 2}],
        ]
        pair_weighted = condition.compile_weighted_conditions(pair_cond, [[(0, 1.0)], [(1, 1.0)]])
        self.assertEqual(len(pair_weighted), 1)
        self.assertEqual(tuple(pair_weighted[0]["cross_attn"].shape), (2, 2, 3))
        self.assertEqual(tuple(pair_weighted[0]["pooled_output"].shape), (2, 4))

        source = Path(ROOT, "forge_neo", "webui", "backend", "sampling", "condition.py").read_text(encoding="utf-8")
        self.assertIn("if isinstance(cond, torch.Tensor):\n        result = dict(", source)
        self.assertIn('cross_attn = cond["crossattn"]\n        pooled_output = cond["vector"]', source)
        self.assertIn("current_weight = 0", source)
        self.assertIn('if hasattr(cond, "advanced_indexing"):\n            feed = cond.advanced_indexing(current_indices)', source)
        self.assertIn("feed = cond[current_indices]", source)
        self.assertIn('h = compile_conditions(feed)\n        if h is None:\n            continue\n        h[0]["strength"] = current_weight\n        results += h', source)

