    def test_source_sampling_function_model_conds_iteration_contract(self):
        import torch

        from forge_neo.runtime_backend.sampling import sampling_function

        class FakeModelCond:
            def __init__(self, value):
                self.value = value

            def process_cond(self, batch_size, device, area):
                return torch.full((batch_size, 1), self.value + sum(area), device=device)

        class SourceStyleModelConds:
            def __init__(self):
                self.records = []
                self.data = {"a": FakeModelCond(1), "b": FakeModelCond(2)}

            def __iter__(self):
                self.records.append("__iter__")
                return iter(self.data)

            def __getitem__(self, key):
                self.records.append(("__getitem__", key))
                return self.data[key]

            def items(self):
                raise AssertionError("source-style model_conds iteration must not call items()")

        model_conds = SourceStyleModelConds()
        result = sampling_function.get_area_and_mult(
            {"model_conds": model_conds},
            torch.zeros((1, 1, 2, 2), dtype=torch.float32),
            torch.ones((1,), dtype=torch.float32),
        )

        self.assertEqual(sorted(result.conditioning.keys()), ["a", "b"])
        self.assertEqual(model_conds.records, ["__iter__", ("__getitem__", "a"), ("__getitem__", "b")])

        source = Path(ROOT, "forge_neo", "webui", "backend", "sampling", "sampling_function.py").read_text(encoding="utf-8")
        self.assertIn("for c in model_conds:", source)
        self.assertIn("conditioning[c] = model_conds[c].process_cond", source)
        self.assertNotIn("for key, model_cond in model_conds.items():", source)

