    def test_source_sampling_function_5d_area_contract(self):
        import json
        import torch

        from forge_neo.runtime_backend.sampling import condition, sampling_function

        class RecordingCond:
            def __init__(self, value):
                self.value = value
                self.calls = []

            def process_cond(self, batch_size, device, area):
                self.calls.append((batch_size, str(device), tuple(area)))
                return condition.Condition(torch.full((batch_size, 1), self.value + sum(area), device=device))

        cond = RecordingCond(3)
        x = torch.zeros((1, 16, 1, 8, 8), dtype=torch.float32)
        timestep = torch.ones((1,), dtype=torch.float32)
        result = sampling_function.get_area_and_mult({"model_conds": {"c": cond}}, x, timestep)
        self.assertEqual(tuple(result.input_x.shape), (1, 16, 1, 8, 8))
        self.assertEqual(tuple(result.mult.shape), (1, 16, 1, 8, 8))
        self.assertEqual(result.area, (1, 8, 0, 0))
        self.assertEqual(cond.calls, [(1, "cpu", (1, 8, 0, 0))])
        self.assertEqual(float(result.conditioning["c"].cond[0, 0]), 12.0)

        cropped = sampling_function.get_area_and_mult({"model_conds": {"c": cond}, "area": (1, 4, 0, 2)}, x, timestep)
        self.assertEqual(tuple(cropped.input_x.shape), (1, 16, 1, 4, 8))
        self.assertEqual(cropped.area, (1, 4, 0, 2))

        class FakeModel:
            model_options = {}

            def __init__(self):
                self.inputs = []

            def memory_required(self, input_shape):
                return 1

            def apply_model(self, input_x, timestep, **kwargs):
                self.inputs.append((tuple(input_x.shape), tuple(timestep.shape), sorted(kwargs.keys())))
                return input_x + 2

        cond_compiled = [{"model_conds": {"c": RecordingCond(1)}}]
        uncond_compiled = [{"model_conds": {"c": RecordingCond(2)}}]
        cond_out, uncond_out = sampling_function.calc_cond_uncond_batch(FakeModel(), cond_compiled, uncond_compiled, x, timestep, {})
        self.assertEqual(tuple(cond_out.shape), (1, 16, 1, 8, 8))
        self.assertEqual(tuple(uncond_out.shape), (1, 16, 1, 8, 8))
        self.assertEqual(float(cond_out.mean()), 2.0)
        self.assertEqual(float(uncond_out.mean()), 2.0)

        source = Path(ROOT, "forge_neo", "webui", "backend", "sampling", "sampling_function.py").read_text(encoding="utf-8")
        classic_source = Path(ROOT, "..", "sd-webui-forge-classic", "backend", "sampling", "sampling_function.py").read_text(encoding="utf-8")
        self.assertIn("area = (x_in.shape[2], x_in.shape[3], 0, 0)", classic_source)
        self.assertIn("area = (x_in.shape[2], x_in.shape[3], 0, 0)", source)
        self.assertIn("conditioning[c] = model_conds[c].process_cond(batch_size=x_in.shape[0], device=x_in.device, area=area)", source)
        self.assertNotIn("cond_area = area if area is not None else (x_in.shape[-2], x_in.shape[-1], 0, 0)", source)

        stage_report_path = Path(ROOT, "reports", "forge-neo-stage466-sampling-function-5d-area.json")
        self.assertTrue(stage_report_path.is_file())
        stage_report = json.loads(stage_report_path.read_text(encoding="utf-8"))
        self.assertEqual(stage_report["stage"], 466)
        self.assertEqual(stage_report["processing_stage"], "source_sampling_function_5d_area_port")
        self.assertIn("test_source_sampling_function_5d_area_contract", stage_report["contracts"])

    def test_source_sampling_function_cond_cat_iteration_contract(self):
        from forge_neo.runtime_backend.sampling import sampling_function

        class FakeProcessedCond:
            def __init__(self, name):
                self.name = name

            def concat(self, others):
                return (self.name, [item.name for item in others])

        class SourceStyleConditioning:
            def __init__(self, data):
                self.records = []
                self.data = data

            def __iter__(self):
                self.records.append("__iter__")
                return iter(self.data)

            def __getitem__(self, key):
                self.records.append(("__getitem__", key))
                return self.data[key]

            def items(self):
                raise AssertionError("source-style conditioning iteration must not call items()")

        first = SourceStyleConditioning({"a": FakeProcessedCond("a0"), "b": FakeProcessedCond("b0")})
        second = SourceStyleConditioning({"a": FakeProcessedCond("a1"), "b": FakeProcessedCond("b1")})
        result = sampling_function.cond_cat([first, second])

        self.assertEqual(result, {"a": ("a0", ["a1"]), "b": ("b0", ["b1"])})
        self.assertEqual(first.records, ["__iter__", ("__getitem__", "a"), ("__getitem__", "b")])
        self.assertEqual(second.records, ["__iter__", ("__getitem__", "a"), ("__getitem__", "b")])

        source = Path(ROOT, "forge_neo", "webui", "backend", "sampling", "sampling_function.py").read_text(encoding="utf-8")
        self.assertIn("for x in c_list:", source)
        self.assertIn("for k in x:", source)
        self.assertIn("cur = temp.get(k, [])", source)
        self.assertIn("cur.append(x[k])", source)
        self.assertIn("temp[k] = cur", source)
        self.assertNotIn("for key, value in item.items():", source)

    def test_source_sampling_function_cond_equal_size_loop_contract(self):
        from forge_neo.runtime_backend.sampling import sampling_function

        class FakeCond:
            def __init__(self, name, concatable=True):
                self.name = name
                self.concatable = concatable
                self.calls = []

            def can_concat(self, other):
                self.calls.append(other.name)
                return self.concatable

        matching_left = {"a": FakeCond("a0"), "b": FakeCond("b0")}
        matching_right = {"a": FakeCond("a1"), "b": FakeCond("b1")}
        self.assertTrue(sampling_function.cond_equal_size(matching_left, matching_right))
        self.assertEqual(matching_left["a"].calls, ["a1"])
        self.assertEqual(matching_left["b"].calls, ["b1"])

        different_keys_left = {"a": FakeCond("a0")}
        different_keys_right = {"b": FakeCond("b1")}
        self.assertFalse(sampling_function.cond_equal_size(different_keys_left, different_keys_right))
        self.assertEqual(different_keys_left["a"].calls, [])

        failing_left = {"a": FakeCond("a0", concatable=False), "b": FakeCond("b0")}
        failing_right = {"a": FakeCond("a1"), "b": FakeCond("b1")}
        self.assertFalse(sampling_function.cond_equal_size(failing_left, failing_right))
        self.assertEqual(failing_left["a"].calls, ["a1"])
        self.assertEqual(failing_left["b"].calls, [])

        source = Path(ROOT, "forge_neo", "webui", "backend", "sampling", "sampling_function.py").read_text(encoding="utf-8")
        self.assertIn("for k in c1:\n        if not c1[k].can_concat(c2[k]):\n            return False\n    return True", source)
        self.assertNotIn("return all(c1[key].can_concat(c2[key]) for key in c1)", source)

    def test_source_torch_hijack_direct_rng_contract(self):
        import torch

        from forge_neo.modules import sd_samplers_common

        class FakeRNG:
            def __init__(self):
                self.calls = 0

            def next(self):
                self.calls += 1
                return torch.ones((1, 2), dtype=torch.float32) * 3

        rng = FakeRNG()
        hijack = sd_samplers_common.TorchHijack(types.SimpleNamespace(rng=rng))
        self.assertIs(hijack.randn_like.__func__, hijack.__getattr__("randn_like").__func__)
        self.assertEqual(float(hijack.randn_like(torch.zeros((1, 2))).mean()), 3.0)
        self.assertEqual(rng.calls, 1)
        self.assertIs(hijack.__getattr__("zeros_like"), torch.zeros_like)
        with self.assertRaises(AttributeError) as raised:
            hijack.__getattr__("definitely_missing")
        self.assertIn("'TorchHijack' object has no attribute 'definitely_missing'", str(raised.exception))

        source = Path(ROOT, "forge_neo", "modules", "sd_samplers_common.py").read_text(encoding="utf-8")
        hijack_start = source.find("class TorchHijack")
        hijack_block = source[hijack_start:source.find("class Sampler", hijack_start)]
        self.assertIn("This is here to replace torch.randn_like of k-diffusion.", hijack_block)
        self.assertIn("make images generated in batches to be same as images generated individually.", hijack_block)
        self.assertIn("self.rng = p.rng", hijack_block)
        self.assertIn("if hasattr(torch, item):\n            return getattr(torch, item)", hijack_block)
        self.assertIn("return self.rng.next()", hijack_block)
        self.assertNotIn('getattr(p, "rng", None)', hijack_block)
        self.assertNotIn("import torch", hijack_block)
        self.assertNotIn("torch.randn_like(x)", hijack_block)
        self.assertNotIn("return x", hijack_block)

    def test_source_sampler_callback_interrupt_contract(self):
        from forge_neo.modules import sd_samplers_common, shared

        class FakeTotalTqdm:
            def __init__(self):
                self.calls = 0

            def update(self):
                self.calls += 1

        sampler = sd_samplers_common.Sampler("callback-test")
        sampler.stop_at = 2
        old_total_tqdm = shared.total_tqdm
        old_sampling_step = shared.state.sampling_step
        old_preview_step = shared.state.preview_step
        fake_total_tqdm = FakeTotalTqdm()
        try:
            shared.total_tqdm = fake_total_tqdm
            sampler.callback_state({"i": 2})
            self.assertEqual(shared.state.sampling_step, 2)
            self.assertEqual(shared.state.preview_step, 3)
            self.assertEqual(fake_total_tqdm.calls, 1)

            with self.assertRaises(sd_samplers_common.InterruptedException):
                sampler.callback_state({"i": 3})
            self.assertEqual(shared.state.sampling_step, 2)
            self.assertEqual(shared.state.preview_step, 3)
            self.assertEqual(fake_total_tqdm.calls, 1)
        finally:
            shared.total_tqdm = old_total_tqdm
            shared.state.sampling_step = old_sampling_step
            shared.state.preview_step = old_preview_step

        source = Path(ROOT, "forge_neo", "modules", "sd_samplers_common.py").read_text(encoding="utf-8")
        callback_block = source[source.find("def callback_state"):source.find("def launch_sampling")]
        self.assertIn('step = d["i"]', callback_block)
        self.assertIn("if self.stop_at is not None and step > self.stop_at:\n            raise InterruptedException", callback_block)
        self.assertIn("state.sampling_step = step", callback_block)
        self.assertIn("state.preview_step = step + 1", callback_block)
        self.assertIn("shared.total_tqdm.update()", callback_block)
        self.assertNotIn("shared.state.sampling_step", callback_block)
        self.assertNotIn("from forge_neo.modules import shared", callback_block)
        self.assertNotIn("except Exception", callback_block)
        self.assertNotIn("pass", callback_block)

    def test_source_sampler_launch_sampling_state_contract(self):
        import contextlib

        from forge_neo.modules import sd_samplers_common, shared

        class FakeModelWrapCfg:
            def __init__(self):
                self.steps = None
                self.total_steps = None

        class FakeConfig:
            def __init__(self):
                self.calls = []

            def total_steps(self, steps):
                self.calls.append(steps)
                return steps * 2

        sampler = sd_samplers_common.Sampler("launch-test")
        sampler.model_wrap_cfg = FakeModelWrapCfg()
        sampler.config = FakeConfig()
        sampler.last_latent = "last-latent"
        old_sampling_steps = shared.state.sampling_steps
        old_sampling_step = shared.state.sampling_step
        old_preview_step = shared.state.preview_step
        try:
            shared.state.sampling_steps = 99
            shared.state.sampling_step = 88
            shared.state.preview_step = 77
            result = sampler.launch_sampling(4, lambda: "sampled")
            self.assertEqual(result, "sampled")
            self.assertEqual(sampler.model_wrap_cfg.steps, 4)
            self.assertEqual(sampler.model_wrap_cfg.total_steps, 8)
            self.assertEqual(sampler.config.calls, [4])
            self.assertEqual(shared.state.sampling_steps, 4)
            self.assertEqual(shared.state.sampling_step, 0)
            self.assertEqual(shared.state.preview_step, 0)

            stdout = io.StringIO()
            with contextlib.redirect_stdout(stdout):
                self.assertEqual(sampler.launch_sampling(5, lambda: (_ for _ in ()).throw(RecursionError())), "last-latent")
            self.assertIn("Encountered RecursionError during sampling; try to use a smaller rho value instead", stdout.getvalue())
            self.assertEqual(sampler.model_wrap_cfg.steps, 5)
            self.assertEqual(sampler.model_wrap_cfg.total_steps, 10)

            self.assertEqual(
                sampler.launch_sampling(6, lambda: (_ for _ in ()).throw(sd_samplers_common.InterruptedException())),
                "last-latent",
            )
            self.assertEqual(sampler.model_wrap_cfg.steps, 6)
            self.assertEqual(sampler.model_wrap_cfg.total_steps, 12)
        finally:
            shared.state.sampling_steps = old_sampling_steps
            shared.state.sampling_step = old_sampling_step
            shared.state.preview_step = old_preview_step

        source = Path(ROOT, "forge_neo", "modules", "sd_samplers_common.py").read_text(encoding="utf-8")
        launch_block = source[source.find("def launch_sampling"):source.find("def number_of_needed_noises")]
        self.assertIn("self.model_wrap_cfg.steps = steps", launch_block)
        self.assertIn("self.model_wrap_cfg.total_steps = self.config.total_steps(steps)", launch_block)
        self.assertIn("state.sampling_steps = steps", launch_block)
        self.assertIn("state.sampling_step = 0", launch_block)
        self.assertIn("state.preview_step = 0", launch_block)
        self.assertNotIn("shared.state.sampling_steps", launch_block)
        self.assertNotIn("from forge_neo.modules import shared", launch_block)
        self.assertIn('print("Encountered RecursionError during sampling; try to use a smaller rho value instead")', launch_block)
        self.assertNotIn("if self.model_wrap_cfg is not None", launch_block)
        self.assertNotIn("int(steps or 0)", launch_block)
        self.assertNotIn("except Exception", launch_block)

