    def test_source_sampling_function_condition_modifiers_contract(self):
        import torch

        from forge_neo.runtime_backend.sampling import sampling_function

        model_calls: list[dict[str, object]] = []
        modifier_calls: list[dict[str, object]] = []

        class FakeModel:
            def memory_required(self, input_shape):
                return 0

            def apply_model(self, input_x, timestep, **kwargs):
                model_calls.append(
                    {
                        "input_mean": round(float(input_x.detach().cpu().mean()), 3),
                        "shape": tuple(input_x.shape),
                        "timestep": tuple(float(item) for item in timestep.detach().cpu().tolist()),
                        "kwargs": kwargs,
                    }
                )
                return input_x + 0.25

        class FakeControl:
            previous_controlnet = None

            def __init__(self):
                self.calls = []
                self.transformer_options = None

            def get_control(self, input_x, timestep, control_cond, batch_size):
                self.calls.append(
                    {
                        "shape": tuple(input_x.shape),
                        "batch_size": batch_size,
                        "has_concat": "c_concat" in control_cond,
                        "concat_mean": round(float(control_cond["c_concat"].detach().cpu().mean()), 3),
                        "transformer_options": dict(self.transformer_options),
                    }
                )
                return {"control": batch_size}

        control = FakeControl()

        def conditioning_modifier(model, x, timestep, uncond, cond, cond_scale, model_options, seed):
            modifier_calls.append(
                {
                    "seed": seed,
                    "cond_scale": cond_scale,
                    "cond_has_control": cond[0]["control"] is control,
                    "uncond_has_control": uncond[0]["control"] is control,
                    "cond_has_concat": "c_concat" in cond[0]["model_conds"],
                    "uncond_has_concat": "c_concat" in uncond[0]["model_conds"],
                    "concat_mean": round(float(cond[0]["model_conds"]["c_concat"].cond.detach().cpu().mean()), 3),
                }
            )
            updated_options = sampling_function._source_utils().join_dicts(model_options, {"transformer_options": {"modifier": True}})
            return model, x + 1.0, timestep, uncond, cond, cond_scale + 0.25, updated_options, seed

        fake_unet = types.SimpleNamespace(
            model=FakeModel(),
            model_options={
                "transformer_options": {"base": True},
                "conditioning_modifiers": [conditioning_modifier],
            },
            controlnet_linked_list=control,
            extra_concat_condition=torch.ones((1, 1, 4, 4)) * 9.0,
        )
        fake_sd_model = types.SimpleNamespace(
            is_inpaint=True,
            forge_objects=types.SimpleNamespace(unet=fake_unet),
        )
        fake_denoiser = types.SimpleNamespace(
            inner_model=types.SimpleNamespace(inner_model=fake_sd_model),
            p=types.SimpleNamespace(seeds=[321]),
        )
        params = sampling_function.DenoiserParams(
            x=torch.zeros((1, 4, 4, 4)),
            image_cond=torch.zeros((1, 1, 4, 4)),
            sigma=torch.ones((1,)),
            sampling_step=0,
            total_sampling_steps=1,
            text_cond=[[torch.ones((1, 2, 3)), {"pooled_output": torch.ones((1, 4))}]],
            text_uncond=[[torch.zeros((1, 2, 3)), {"pooled_output": torch.zeros((1, 4))}]],
            denoiser=fake_denoiser,
        )

        result, cond_pred, uncond_pred = sampling_function.sampling_function(
            fake_denoiser,
            denoiser_params=params,
            cond_scale=1.5,
            cond_composition=[[(0, 1.0)]],
            extra_model_options={"transformer_options": {"extra": True}},
        )

        self.assertEqual(tuple(result.shape), (1, 4, 4, 4))
        self.assertEqual(tuple(cond_pred.shape), (1, 4, 4, 4))
        self.assertEqual(tuple(uncond_pred.shape), (1, 4, 4, 4))
        self.assertEqual(
            modifier_calls,
            [
                {
                    "seed": 321,
                    "cond_scale": 1.5,
                    "cond_has_control": True,
                    "uncond_has_control": True,
                    "cond_has_concat": True,
                    "uncond_has_concat": True,
                    "concat_mean": 9.0,
                }
            ],
        )
        self.assertEqual(len(control.calls), 1)
        self.assertEqual(control.calls[0]["shape"], (2, 4, 4, 4))
        self.assertEqual(control.calls[0]["batch_size"], 2)
        self.assertTrue(control.calls[0]["has_concat"])
        self.assertEqual(control.calls[0]["concat_mean"], 9.0)
        self.assertEqual(control.calls[0]["transformer_options"]["base"], True)
        self.assertEqual(control.calls[0]["transformer_options"]["extra"], True)
        self.assertEqual(control.calls[0]["transformer_options"]["modifier"], True)
        self.assertEqual(len(model_calls), 1)
        apply_kwargs = model_calls[0]["kwargs"]
        self.assertEqual(model_calls[0]["input_mean"], 1.0)
        self.assertEqual(tuple(apply_kwargs["c_concat"].shape), (2, 1, 4, 4))
        self.assertEqual(round(float(apply_kwargs["c_concat"].detach().cpu().mean()), 3), 9.0)
        self.assertEqual(apply_kwargs["control"], {"control": 2})
        self.assertIs(apply_kwargs["control_model"], control)
        self.assertEqual(apply_kwargs["transformer_options"]["cond_or_uncond"], [1, 0])

    def test_source_sampling_function_direct_compilers_contract(self):
        from forge_neo.runtime_backend.sampling import condition, sampling_function

        self.assertIs(sampling_function.Condition, condition.Condition)
