    def test_source_sampling_function_inner_cfg_args_contract(self):
        import torch

        from forge_neo.runtime_backend.sampling import condition, sampling_function

        records = []

        class FakeModel:
            def memory_required(self, input_shape):
                return 0

            def apply_model(self, input_x, timestep, **kwargs):
                chunks = []
                for item in kwargs["transformer_options"]["cond_or_uncond"]:
                    value = 2.0 if item == 0 else 1.0
                    chunks.append(torch.ones_like(input_x[:1]) * value)
                return torch.cat(chunks)

        def cfg_callback(args):
            records.append(("cfg", tuple(args.keys()), round(float(args["cond_denoised"].mean()), 3), round(float(args["uncond_denoised"].mean()), 3)))
            return args["cond"] * 0.5

        def post_callback(args):
            records.append(("post", tuple(args.keys()), round(float(args["denoised"].mean()), 3)))
            return args["denoised"] + 0.25

        result = sampling_function.sampling_function_inner(
            FakeModel(),
            torch.zeros((1, 1, 2, 2), dtype=torch.float32),
            torch.ones((1,), dtype=torch.float32),
            condition.compile_conditions(torch.zeros((1, 2, 3))),
            condition.compile_conditions(torch.ones((1, 2, 3))),
            2.0,
            {"free_memory": 2**63 - 1, "sampler_cfg_function": cfg_callback, "sampler_post_cfg_function": [post_callback]},
        )

        self.assertEqual(round(float(result.detach().cpu().mean()), 3), 1.25)
        self.assertEqual(records[0][0], "cfg")
        self.assertEqual(
            records[0][1],
            ("cond", "uncond", "cond_scale", "timestep", "input", "sigma", "cond_denoised", "uncond_denoised", "model", "model_options"),
        )
        self.assertEqual(records[0][2:], (2.0, 1.0))
        self.assertEqual(records[1][0], "post")
        self.assertEqual(
            records[1][1],
            ("denoised", "cond", "uncond", "cond_scale", "model", "uncond_denoised", "cond_denoised", "sigma", "model_options", "input"),
        )

        source = Path(ROOT, "forge_neo", "webui", "backend", "sampling", "sampling_function.py").read_text(encoding="utf-8")
        self.assertIn('args = {"cond": x - cond_pred, "uncond": x - uncond_pred, "cond_scale": cond_scale, "timestep": timestep, "input": x, "sigma": timestep, "cond_denoised": cond_pred, "uncond_denoised": uncond_pred, "model": model, "model_options": model_options}', source)
        self.assertIn('args = {"denoised": cfg_result, "cond": cond, "uncond": uncond, "cond_scale": cond_scale, "model": model, "uncond_denoised": uncond_pred, "cond_denoised": cond_pred, "sigma": timestep, "model_options": model_options, "input": x}', source)
        self.assertNotIn('args = {\n            "cond": x - cond_pred', source)
        self.assertNotIn('args = {\n            "denoised": cfg_result', source)

