    def test_source_sampling_function_objects_concatable_contract(self):
        import torch

        from forge_neo.runtime_backend.sampling import sampling_function

        class FakeCond:
            def can_concat(self, other):
                return isinstance(other, FakeCond)

        input_x = torch.zeros((1, 1, 1, 1))
        control = object()
        patches = object()
        base = types.SimpleNamespace(input_x=input_x, control=control, patches=patches, conditioning={"c": FakeCond()})
        same = types.SimpleNamespace(input_x=input_x, control=control, patches=patches, conditioning={"c": FakeCond()})
        other_control = types.SimpleNamespace(input_x=input_x, control=object(), patches=patches, conditioning={"c": FakeCond()})
        missing_control = types.SimpleNamespace(input_x=input_x, control=None, patches=patches, conditioning={"c": FakeCond()})
        other_patches = types.SimpleNamespace(input_x=input_x, control=control, patches=object(), conditioning={"c": FakeCond()})

        self.assertTrue(sampling_function.can_concat_cond(base, same))
        self.assertFalse(sampling_function.can_concat_cond(base, other_control))
        self.assertFalse(sampling_function.can_concat_cond(base, missing_control))
        self.assertFalse(sampling_function.can_concat_cond(base, other_patches))

        source = Path(ROOT, "forge_neo", "webui", "backend", "sampling", "sampling_function.py").read_text(encoding="utf-8")
        self.assertIn("def objects_concatable(obj1, obj2):", source)
        self.assertIn("if not objects_concatable(c1.control, c2.control):", source)
        self.assertIn("if not objects_concatable(c1.patches, c2.patches):", source)
        self.assertNotIn("if c1.control is not c2.control:", source)

    def test_source_condition_batch_free_memory_contract(self):
        import torch

        from forge_neo.runtime_backend.sampling import condition, sampling_function

        old_backend = sys.modules.get("backend")
        old_backend_args = sys.modules.get("backend.args")
        old_memory_management = sys.modules.get("backend.memory_management")
        backend_pkg = types.ModuleType("backend")
        backend_args = types.ModuleType("backend.args")
        memory_management = types.ModuleType("backend.memory_management")
        memory_calls = []
        empty_calls = []
        apply_records = []

        def fake_get_free_memory(device):
            memory_calls.append(str(device))
            return 1

        def fake_soft_empty_cache():
            empty_calls.append("empty")

        memory_management.signal_empty_cache = True
        memory_management.get_free_memory = fake_get_free_memory
        memory_management.soft_empty_cache = fake_soft_empty_cache
        memory_management.logger = types.SimpleNamespace(warning=lambda _message: None)
        backend_args.args = types.SimpleNamespace(disable_gpu_warning=False)
        backend_pkg.memory_management = memory_management
        sys.modules["backend"] = backend_pkg
        sys.modules["backend.args"] = backend_args
        sys.modules["backend.memory_management"] = memory_management

        class FakeModel:
            def memory_required(self, input_shape):
                return 2 if int(input_shape[0]) > 1 else 1

            def apply_model(self, input_x, timestep, **kwargs):
                apply_records.append(tuple(kwargs["transformer_options"]["cond_or_uncond"]))
                return input_x + len(apply_records)

        try:
            result, cond_pred, uncond_pred = sampling_function.sampling_function_inner(
                FakeModel(),
                torch.zeros((1, 1, 1, 1)),
                torch.ones((1,)),
                condition.compile_conditions(torch.zeros((1, 2, 3))),
                condition.compile_conditions(torch.ones((1, 2, 3))),
                2.0,
                {},
                return_full=True,
            )
        finally:
            if old_backend is None:
                sys.modules.pop("backend", None)
            else:
                sys.modules["backend"] = old_backend
            if old_backend_args is None:
                sys.modules.pop("backend.args", None)
            else:
                sys.modules["backend.args"] = old_backend_args
            if old_memory_management is None:
                sys.modules.pop("backend.memory_management", None)
            else:
                sys.modules["backend.memory_management"] = old_memory_management

        self.assertGreaterEqual(len(memory_calls), 2)
        self.assertEqual(len(empty_calls), len(memory_calls))
        self.assertEqual(apply_records, [(1,), (0,)])
        self.assertEqual(round(float(uncond_pred.detach().cpu().mean()), 3), 1.0)
        self.assertEqual(round(float(cond_pred.detach().cpu().mean()), 3), 2.0)
        self.assertEqual(round(float(result.detach().cpu().mean()), 3), 3.0)

        source = Path(ROOT, "forge_neo", "webui", "backend", "sampling", "sampling_function.py").read_text(encoding="utf-8")
        self.assertIn('from backend import memory_management', source)
        self.assertIn("if memory_management.signal_empty_cache:", source)
        self.assertIn("memory_management.soft_empty_cache()", source)
        self.assertIn("free_memory = memory_management.get_free_memory(x_in.device)", source)

