    def test_source_condition_batch_direct_model_apply_contract(self):
        import torch

        from forge_neo.runtime_backend.sampling import condition, sampling_function

        records = []

        class FakeModel:
            def memory_required(self, input_shape):
                return 0

            def apply_model(self, input_x, timestep, **kwargs):
                records.append(("apply", tuple(kwargs["transformer_options"]["cond_or_uncond"])))
                chunks = []
                for item in kwargs["transformer_options"]["cond_or_uncond"]:
                    value = 2.0 if item == 0 else 1.0
                    chunks.append(torch.ones_like(input_x[:1]) * value)
                return torch.cat(chunks)

        def wrapper(apply_model, payload):
            records.append(("wrapper", tuple(payload["cond_or_uncond"]), sorted(payload["c"].keys())))
            return apply_model(payload["input"], payload["timestep"], **payload["c"]) + 1.0

        result, cond_pred, uncond_pred = sampling_function.sampling_function_inner(
            FakeModel(),
            torch.zeros((1, 1, 1, 1)),
            torch.ones((1,)),
            condition.compile_conditions(torch.zeros((1, 2, 3))),
            condition.compile_conditions(torch.ones((1, 2, 3))),
            2.0,
            {"free_memory": 2**63 - 1, "model_function_wrapper": wrapper},
            return_full=True,
        )

        self.assertEqual(records[0][0], "wrapper")
        self.assertEqual(records[0][1], (1, 0))
        self.assertIn("transformer_options", records[0][2])
        self.assertEqual(records[1], ("apply", (1, 0)))
        self.assertEqual(round(float(uncond_pred.detach().cpu().mean()), 3), 2.0)
        self.assertEqual(round(float(cond_pred.detach().cpu().mean()), 3), 3.0)
        self.assertEqual(round(float(result.detach().cpu().mean()), 3), 4.0)

        source = Path(ROOT, "forge_neo", "webui", "backend", "sampling", "sampling_function.py").read_text(encoding="utf-8")
        self.assertIn('if "model_function_wrapper" in model_options:', source)
        self.assertIn('output = model_options["model_function_wrapper"](model.apply_model, {"input": input_x, "timestep": timestep_, "c": c, "cond_or_uncond": cond_or_uncond}).chunk(batch_chunks)', source)
        self.assertIn("output = model.apply_model(input_x, timestep_, **c).chunk(batch_chunks)", source)
        self.assertIn("del input_x", source)
        self.assertIn("del mult", source)
        self.assertNotIn("elif callable(model):", source)
        self.assertNotIn("output = input_x", source)
        self.assertNotIn("chunks = output.chunk(batch_chunks)", source)

