    def test_source_sampler_executor_signature_kwargs_contract(self):
        import torch

        from forge_neo.modules import sd_sampler_executor

        records = []

        def fake_euler(model, x, sigmas, extra_args=None, callback=None, disable=False, s_noise=1.0):
            records.append(("euler", callable(callback), disable, s_noise, tuple(float(item) for item in sigmas.detach().cpu().tolist()), sorted(extra_args)))
            if callable(callback):
                callback({"i": 0, "x": x + 0.5})
            return x + float(s_noise)

        def fake_ddim(model, x, timesteps, extra_args=None, callback=None, disable=False, eta=0.0):
            records.append(("ddim", callable(callback), disable, eta, tuple(int(item) for item in timesteps.detach().cpu().tolist()), sorted(extra_args)))
            if callable(callback):
                callback({"i": 0, "x": x + 0.25})
            return x + float(eta)

        old_sampling_module = sd_sampler_executor._sampling_module
        old_timesteps_module = sd_sampler_executor._timesteps_module
        try:
            sd_sampler_executor._sampling_module = lambda: types.SimpleNamespace(sample_euler=fake_euler)
            sd_sampler_executor._timesteps_module = lambda: types.SimpleNamespace(ddim=fake_ddim)
            executor = sd_sampler_executor.NativeSamplerExecutor()
            p = type("SignatureKwargsP", (), {"extra_generation_params": {}, "width": 16, "height": 16, "cfg_scale": 1.0})()
            euler_result = executor.sample(
                p,
                sampler="Euler",
                x=torch.zeros((1, 4, 2, 2)),
                sigmas=torch.tensor([1.0, 0.0]),
                cfg_denoiser=object(),
                sampler_extra_args={"cond": "cond", "uncond": "uncond", "cond_scale": 1.0},
                sampler_kwargs={"s_noise": 0.75, "unknown": "drop"},
            )
            ddim_result = executor.sample(
                p,
                sampler="DDIM",
                x=torch.zeros((1, 4, 2, 2)),
                sigmas=None,
                cfg_denoiser=object(),
                sampler_extra_args={"cond": "cond", "uncond": "uncond", "cond_scale": 1.0},
                timesteps=torch.tensor([1, 999], dtype=torch.long),
                sampler_kwargs={"eta": 0.33, "unknown": "drop"},
            )
        finally:
            sd_sampler_executor._sampling_module = old_sampling_module
            sd_sampler_executor._timesteps_module = old_timesteps_module

        self.assertEqual(round(float(euler_result.detach().cpu().mean()), 3), 0.75)
        self.assertEqual(round(float(ddim_result.detach().cpu().mean()), 3), 0.33)
        self.assertEqual(records[0], ("euler", True, False, 0.75, (1.0, 0.0), ["cond", "cond_scale", "image_cond", "s_min_uncond", "uncond"]))
        self.assertEqual(records[1], ("ddim", True, False, 0.33, (1, 999), ["cond", "cond_scale", "image_cond", "s_min_uncond", "uncond"]))
        self.assertEqual(sd_sampler_executor._signature_sampler_kwargs(fake_euler, {"s_noise": 0.5, "unknown": 1}), {"s_noise": 0.5})

