    def test_forge_neo_image_only_preset_removal_contract(self):
        from forge_neo import api, models, settings
        source_root = str(Path(ROOT, "forge_neo", "webui"))
        old_source_root_index = sys.path.index(source_root) if source_root in sys.path else None
        if old_source_root_index is None:
            sys.path.insert(0, source_root)
        presets = importlib.import_module("modules_forge.presets")

        try:
            active_presets = ["sd", "xl", "flux", "klein", "qwen", "qwen21", "krea2", "lumina", "zit", "anima"]
            removed_presets = {"wan", "ernie"}
            self.assertEqual(models.UI_PRESETS, active_presets)
            self.assertEqual(settings.PRESET_ARCHES, tuple(sorted(active_presets)))
            self.assertEqual(presets.PresetArch.choices(), active_presets)
            self.assertEqual(presets.SAMPLERS[presets.PresetArch.qwen], "Euler")
            self.assertEqual(presets.SCHEDULERS[presets.PresetArch.qwen], "Beta")
            self.assertEqual(presets.SAMPLERS[presets.PresetArch.qwen21], "Euler")
            self.assertEqual(presets.SCHEDULERS[presets.PresetArch.qwen21], "Simple")
            self.assertEqual(presets.STEPS[presets.PresetArch.qwen21], 25)
            self.assertEqual(presets.CFG[presets.PresetArch.qwen21], 1.0)
            self.assertEqual(presets.SAMPLERS[presets.PresetArch.krea2], "Euler")
            self.assertEqual(presets.SCHEDULERS[presets.PresetArch.krea2], "Simple")
            self.assertEqual(presets.SAMPLERS[presets.PresetArch.anima], "ER SDE")
            self.assertEqual(presets.SCHEDULERS[presets.PresetArch.anima], "Simple")
            self.assertEqual(settings.PRESET_FRAMES, {})
            self.assertIn("krea2", api.SOURCE_PRESET_DCFG_EMPTY_OPTIONS)
            self.assertNotIn("wan", api.SOURCE_PRESET_DCFG_EMPTY_OPTIONS)
            for removed in removed_presets:
                self.assertNotIn(removed, models.UI_PRESETS)
                self.assertNotIn(removed, models.PRESET_DEFAULTS)
                self.assertNotIn(removed, models.PRESET_ENGINE)
                self.assertNotIn(removed, settings.PRESET_ARCHES)
                self.assertNotIn(removed, settings.PRESET_SETTING_KEYS)
                self.assertNotIn(removed, presets.PresetArch.choices())
        finally:
            if old_source_root_index is None:
                try:
                    sys.path.remove(source_root)
                except ValueError:
                    pass

        removed_paths = (
            "forge_neo/webui/backend/diffusion_engine/wan.py",
            "forge_neo/webui/backend/diffusion_engine/ernie.py",
            "forge_neo/webui/backend/nn/wan.py",
            "forge_neo/webui/backend/nn/ernie.py",
            "forge_neo/webui/extensions-builtin/sd_forge_radial",
            "forge_neo/webui/backend/huggingface/Wan-AI",
            "forge_neo/webui/backend/huggingface/baidu/ERNIE-Image",
            "forge_neo/webui/backend/huggingface/wan.tokenizer.json.xz",
            "forge_neo/webui/backend/huggingface/ernie.tokenizer.json.xz",
        )
        for removed_path in removed_paths:
            self.assertFalse(Path(ROOT, removed_path).exists(), removed_path)

        loader_source = Path(ROOT, "forge_neo", "webui", "backend", "loader.py").read_text(encoding="utf-8")
        args_source = Path(ROOT, "forge_neo", "webui", "backend", "args.py").read_text(encoding="utf-8")
        self.assertNotIn("from backend.diffusion_engine.wan import Wan", loader_source)
        self.assertNotIn("from backend.diffusion_engine.ernie import ErnieImage", loader_source)
        self.assertNotIn("WanTransformer3DModel", loader_source)
        self.assertNotIn("ErnieImageTransformer2DModel", loader_source)
        self.assertIn("backend.args.dynamic_args.wan = False", loader_source)
        self.assertIn("dynamic_args.wan = False", args_source)
        self.assertNotIn('dynamic_args.wan = value == "wan"', args_source)
        self.assertNotIn('dynamic_args.wan = "wan" in text', args_source)
        self.assertNotIn("Wan 2.2", args_source)

        manifest = json.loads(Path(ROOT, "forge_neo", "webui", "manifest.json").read_text(encoding="utf-8"))
        forbidden_prefixes = (
            "diffusion_engine/wan.py",
            "diffusion_engine/ernie.py",
            "nn/wan.py",
            "nn/ernie.py",
            "extensions-builtin/sd_forge_radial",
            "huggingface/Wan-AI",
            "huggingface/baidu/ERNIE-Image",
            "huggingface/wan.tokenizer",
            "huggingface/ernie.tokenizer",
        )
        for item in manifest.get("files", []):
            joined = f"{item.get('source_path', '')}|{item.get('target_path', '')}"
            for prefix in forbidden_prefixes:
                self.assertNotIn(prefix, joined)

    def test_source_backend_flux1_preset_clip_l_contract(self):
        from forge_neo import models
        from forge_neo.runtime_backend.source_runtime import _source_backend_payload
        from forge_neo.runtime import ForgeNeoRequest

        old_source_config_value = models._source_config_value
        try:
            models._source_config_value = lambda *_args, **_kwargs: None
            choices = models.ForgeNeoModelChoices(
                checkpoints=["flux1-dev-fp8.safetensors"],
                vae=["ae.safetensors"],
                text_encoders=["clip_l.safetensors", "t5xxl_fp8_e4m3fn.safetensors"],
            )
            defaults = models.preset_model_defaults("flux", choices)
            self.assertEqual(defaults.checkpoint, "flux1-dev-fp8.safetensors")
            self.assertEqual(defaults.vae, "ae.safetensors")
            self.assertEqual(defaults.text_encoders, ["clip_l.safetensors", "t5xxl_fp8_e4m3fn.safetensors"])
            self.assertEqual(
                defaults.modules,
                ["clip_l.safetensors", "t5xxl_fp8_e4m3fn.safetensors", "ae.safetensors"],
            )

            payload = _source_backend_payload(
                ForgeNeoRequest(
                    preset="flux",
                    checkpoint=defaults.checkpoint,
                    vae=defaults.vae,
                    text_encoders=defaults.text_encoders,
                )
            )["payload"]
            self.assertEqual(
                payload["override_settings"]["forge_additional_modules"],
                ["clip_l.safetensors", "t5xxl_fp8_e4m3fn.safetensors", "ae.safetensors"],
            )

            stage_report_path = Path(ROOT, "reports", "forge-neo-stage625-source-backend-flux1-clip-l-modules.json")
            self.assertTrue(stage_report_path.is_file())
            stage_report = json.loads(stage_report_path.read_text(encoding="utf-8"))
            self.assertEqual(stage_report["stage"], 625)
            self.assertEqual(stage_report["flux1_modules"], ["clip_l.safetensors", "t5xxl_fp8_e4m3fn.safetensors", "ae.safetensors"])
            self.assertIn("test_source_backend_flux1_preset_clip_l_contract", stage_report["contracts"])
        finally:
            models._source_config_value = old_source_config_value

    def test_generation_uses_visible_vae_text_encoder_selection_contract(self):
        from forge_neo import ui

        old_module_selection_for_request = ui._module_selection_for_request
        old_run_current_model_save_plan = ui.run_current_model_save_plan
        calls: list[list[str]] = []
        save_requests = []

        def fake_module_selection(values):
            selected = list(values or [])
            calls.append(selected)
            if selected:
                return selected[0], selected[1:]
            return "None", []

        def fake_current_model_save_plan(request):
            save_requests.append(request)
            return types.SimpleNamespace(
                status="plan",
                error="",
                plan={"output": {"planned_model_path": "planned.safetensors"}, "current_model": {"checkpoint": request.checkpoint}},
                plan_path="plan.json",
                plan_json="{}",
            )

        try:
            ui._module_selection_for_request = fake_module_selection
            ui.run_current_model_save_plan = fake_current_model_save_plan
            build_args = [
                "txt2img",
                "qwen",
                "qwen-model.safetensors",
                [],
                "Automatic",
                "prompt",
                "",
                [],
                "{}",
                "all",
                "Euler",
                "Beta",
                1,
                64,
                64,
                1.0,
                0.0,
                None,
                0.0,
                0.0,
                -1,
                1,
                1,
                False,
                False,
                [],
                {},
                "Latent",
                0,
                0.0,
                1.0,
                0,
                0,
                "Use same checkpoint",
                [],
                "Euler",
                "Beta",
                "",
                "",
                1.0,
                0.0,
                "None",
                0.8,
            ]
            request = ui._build_request(*build_args)
            self.assertEqual(request.vae, "None")
            self.assertEqual(request.text_encoders, [])
            self.assertEqual(calls[-1], [])

            visible_build_args = list(build_args)
            visible_build_args[3] = ["visible-vae.safetensors", "clip.safetensors"]
            visible_request = ui._build_request(*visible_build_args)
            self.assertEqual(visible_request.vae, "visible-vae.safetensors")
            self.assertEqual(visible_request.text_encoders, ["clip.safetensors"])
            self.assertEqual(calls[-1], ["visible-vae.safetensors", "clip.safetensors"])

            hidden_update = ui._text_encoders_changed([])
            self.assertEqual(hidden_update["value"], "None")
            visible_update = ui._text_encoders_changed(["visible-vae.safetensors", "clip.safetensors"])
            self.assertEqual(visible_update["value"], "visible-vae.safetensors")

            ui._save_current_checkpoint_notice(
                "current-model.safetensors",
                {"__lang": "en"},
                "checkpoint",
                "qwen-model.safetensors",
                [],
                "Automatic",
            )
            self.assertEqual(save_requests[-1].vae, "None")
            self.assertEqual(save_requests[-1].text_encoders, [])
            ui._save_current_checkpoint_notice(
                "current-model.safetensors",
                {"__lang": "en"},
                "checkpoint",
                "qwen-model.safetensors",
                ["visible-vae.safetensors", "clip.safetensors"],
                "Automatic",
            )
            self.assertEqual(save_requests[-1].vae, "visible-vae.safetensors")
            self.assertEqual(save_requests[-1].text_encoders, ["clip.safetensors"])

            loaded_models_html = ui._settings_loaded_models_html(
                {"__lang": "en"},
                "qwen-model.safetensors",
                [],
                "Automatic",
            )
            self.assertNotIn("stale-hidden-vae.safetensors", loaded_models_html)
            self.assertIn("None", loaded_models_html)
        finally:
            ui._module_selection_for_request = old_module_selection_for_request
            ui.run_current_model_save_plan = old_run_current_model_save_plan

    def test_source_backend_batched_model_load_sync_contract(self):
        patcher_source = Path(ROOT, "forge_neo", "webui", "backend", "patcher", "base.py").read_text(encoding="utf-8")
        load_start = patcher_source.find("    def load(self, device_to=None, lowvram_model_memory=0")
        load_end = patcher_source.find("    def patch_model(", load_start)
        self.assertGreater(load_start, 0)
        self.assertGreater(load_end, load_start)
        load_block = patcher_source[load_start:load_end]

        regular_load_loop_start = load_block.find("        for x in load_completely:")
        module_to_loop = load_block.find("        for x in load_completely:\n            x[2].to(device_to)", regular_load_loop_start + 1)
        offloaded_loop = load_block.find("        for x in offloaded:", module_to_loop)
        self.assertGreater(regular_load_loop_start, 0)
        self.assertGreater(module_to_loop, regular_load_loop_start)
        self.assertGreater(offloaded_loop, module_to_loop)

        per_module_block = load_block[regular_load_loop_start:module_to_loop]
        batched_sync_block = load_block[module_to_loop:offloaded_loop]
        self.assertNotIn("torch.cuda.synchronize()", per_module_block)
        self.assertNotIn("torch.xpu.synchronize()", per_module_block)
        self.assertIn("if load_completely:", batched_sync_block)
        self.assertIn("torch.cuda.synchronize()", batched_sync_block)
        self.assertIn("torch.xpu.synchronize()", batched_sync_block)

        stage_report_path = Path(ROOT, "reports", "forge-neo-stage626-source-backend-batched-model-load-sync.json")
        self.assertTrue(stage_report_path.is_file())
        stage_report = json.loads(stage_report_path.read_text(encoding="utf-8"))
        self.assertEqual(stage_report["stage"], 626)
        self.assertTrue(stage_report["batched_model_load_sync"])
        self.assertIn("test_source_backend_batched_model_load_sync_contract", stage_report["contracts"])

