    def test_source_backend_qwen_driver_free_vram_budget_contract(self):
        memory_source = Path(ROOT, "forge_neo", "webui", "backend", "memory_management.py").read_text(encoding="utf-8")

        self.assertIn("LOWVRAM_MIN_WEIGHT_MEMORY = 64 * 1024 * 1024", memory_source)
        self.assertIn("def _driver_free_memory(device: torch.device) -> float:", memory_source)
        self.assertIn("free_total, free_torch = get_free_memory(device, torch_free_too=True)", memory_source)
        self.assertIn("return max(0, free_total - free_torch)", memory_source)
        self.assertIn("def _weight_budget_free_memory(model: \"ModelPatcher\", device: torch.device, loaded_memory: float) -> float:", memory_source)
        self.assertIn("if model.current_loaded_device() == device:", memory_source)
        self.assertIn("base_inference_memory = (1024 * 1024 * 1024) * 0.8", memory_source)
        self.assertIn("if total_vram > (20 * 1024):", memory_source)
        self.assertIn("base_inference_memory = (1024 * 1024 * 1024) * 4", memory_source)
        self.assertIn("return base_inference_memory + extra_reserved_memory()", memory_source)
        self.assertIn('FORGE_NEO_SOURCE_BACKEND_WEIGHT_LOAD_MARGIN_MB", "512"', memory_source)
        self.assertIn("WEIGHT_LOAD_MARGIN_MEMORY = _weight_load_margin_from_env()", memory_source)
        self.assertIn('FORGE_NEO_SOURCE_BACKEND_FULL_LOAD_MARGIN_MB", "1024"', memory_source)
        self.assertIn("FULL_LOAD_MARGIN_MEMORY = _full_load_margin_from_env()", memory_source)
        self.assertIn("def _source_patcher_weight_load_margin(model_memory: float, reserved_memory: float) -> float:", memory_source)
        self.assertIn("return max(WEIGHT_LOAD_MARGIN_MEMORY, min(reserved_memory * 0.5, model_memory * 0.05))", memory_source)
        self.assertIn("def _adaptive_lowvram_model_memory(model_memory: float, current_free_memory: float, reserved_memory: float, loaded_memory: float) -> float:", memory_source)
        self.assertIn("load_margin = _source_patcher_weight_load_margin(model_memory, reserved_memory)", memory_source)
        self.assertIn("available_for_weights = current_free_memory - reserved_memory - load_margin", memory_source)
        self.assertIn("full_load_margin = max(FULL_LOAD_MARGIN_MEMORY, load_margin)", memory_source)
        self.assertIn("if model_memory + full_load_margin <= available_for_weights:", memory_source)
        self.assertIn("LOWVRAM_FULL_LOAD_GAP_MEMORY = 64 * 1024 * 1024", memory_source)
        self.assertIn("max_partial_budget = max(0.1, model_memory - LOWVRAM_FULL_LOAD_GAP_MEMORY)", memory_source)
        self.assertIn("target_loaded_memory = min(max(min_partial_budget, available_for_weights), max_partial_budget)", memory_source)
        self.assertIn("extra_memory = target_loaded_memory - loaded_memory", memory_source)
        self.assertIn("return max(SAMPLING_HEADROOM_MEMORY, extra_reserved_memory())", memory_source)
        self.assertIn("reserved_model_memory = _model_weight_reserve_memory(model)", memory_source)
        self.assertIn("current_free_mem = _weight_budget_free_memory(model, torch_dev, loaded_memory)", memory_source)
        self.assertIn("lowvram_model_memory = _adaptive_lowvram_model_memory(model_memory, current_free_mem, reserved_model_memory, loaded_memory)", memory_source)
        self.assertIn("Using adaptive low VRAM loading", memory_source)
        self.assertIn("free_after_adjustment = get_free_memory(torch_dev)", memory_source)
        self.assertIn("Partial unload did not restore sampling headroom", memory_source)
        self.assertIn("loaded_model.model_unload(None, unpatch_weights=True)", memory_source)
        self.assertIn("_reload_model_with_adaptive_lowvram_budget(loaded_model, model, torch_dev, headroom, force_patch_weights)", memory_source)
        self.assertNotIn("current_free_mem = get_free_memory(torch_dev) + loaded_memory", memory_source)
        self.assertNotIn("loaded_model.model_unload(None, unpatch_weights=False)", memory_source)
        self.assertNotIn("loaded_model.model_load(0.1, force_patch_weights=force_patch_weights)", memory_source)
        self.assertLess(
            memory_source.index("lowvram_model_memory = _adaptive_lowvram_model_memory"),
            memory_source.index("loaded_model.model_load(lowvram_model_memory"),
        )
        self.assertNotIn("FORGE_NEO_SOURCE_BACKEND_DYNAMIC_TEXT_ENCODER_THRESHOLD_MB", memory_source)
        self.assertNotIn("FORGE_NEO_SOURCE_BACKEND_DYNAMIC_MODEL_THRESHOLD_MB", memory_source)
        self.assertNotIn("FORGE_NEO_SOURCE_BACKEND_DYNAMIC_VRAM_MB", memory_source)

        stage_report_path = Path(ROOT, "reports", "forge-neo-stage630-source-backend-qwen-driver-free-vram-budget.json")
        self.assertTrue(stage_report_path.is_file())
        stage_report = json.loads(stage_report_path.read_text(encoding="utf-8"))
        self.assertEqual(stage_report["stage"], 630)
        self.assertEqual(stage_report["lowvram_min_weight_memory_mb"], 64)
        self.assertTrue(stage_report["uses_cuda_driver_free_memory"])
        self.assertTrue(stage_report["uses_model_size_comparison"])
        self.assertTrue(stage_report["uses_sampling_reserved_memory"])
        self.assertTrue(stage_report["reloads_lowvram_when_partial_unload_does_not_restore_headroom"])
        self.assertIn("test_source_backend_qwen_driver_free_vram_budget_contract", stage_report["contracts"])

