    def test_source_backend_uses_current_project_model_roots_contract(self):
        from forge_neo import models
        from forge_neo.bootstrap import ensure_config
        from forge_neo.runtime_backend import source_runtime

        runtime_source = Path(ROOT, "forge_neo", "runtime_backend", "source_runtime.py").read_text(encoding="utf-8")
        models_source = Path(ROOT, "forge_neo", "models.py").read_text(encoding="utf-8")
        config = ensure_config(test_stub=True)
        old_reference_roots = os.environ.get("FORGE_NEO_REFERENCE_ROOTS")
        old_auto_roots = os.environ.get("FORGE_NEO_AUTO_REFERENCE_ROOTS")
        old_source_config_paths = os.environ.get("FORGE_NEO_SOURCE_CONFIG_PATHS")
        old_data_root = os.environ.get("FORGE_NEO_SOURCE_BACKEND_DATA_DIR")
        old_model_map = getattr(config, "model_cata_map", None)
        old_paths = {
            name: getattr(config, name, None)
            for name in (
                "paths_checkpoints",
                "paths_diffusion_models",
                "paths_text_encoders",
                "paths_clip",
                "paths_vae",
                "paths_loras",
                "paths_controlnet",
                "paths_upscale_models",
            )
        }
        try:
            with tempfile.TemporaryDirectory() as tmp:
                root = Path(tmp)
                local_ckpt = root / "SimpleModels" / "diffusion_models"
                source_config = root / "config.json"
                local_ckpt.mkdir(parents=True)
                source_config.write_text(json.dumps({"path_checkpoints": [str(local_ckpt)]}), encoding="utf-8")
                config.model_cata_map = {"checkpoints": [str(local_ckpt)], "diffusion_models": []}
                for name in old_paths:
                    setattr(config, name, [])
                os.environ["FORGE_NEO_AUTO_REFERENCE_ROOTS"] = "1"
                os.environ.pop("FORGE_NEO_REFERENCE_ROOTS", None)
                os.environ["FORGE_NEO_SOURCE_CONFIG_PATHS"] = str(source_config)
                os.environ.pop("FORGE_NEO_SOURCE_BACKEND_DATA_DIR", None)

                checkpoint_roots = models.model_roots_for_catalog("checkpoints")
                self.assertTrue(any(os.path.samefile(root, local_ckpt) for root in checkpoint_roots))
                self.assertEqual(models._reference_root_candidates(config), [])
                self.assertTrue(any(os.path.samefile(path, source_config) for path in models._source_config_candidate_paths(config)))
                self.assertEqual(
                    os.path.normcase(os.path.abspath(source_runtime._default_data_root())),
                    os.path.normcase(os.path.abspath(Path(ROOT, "forge_neo", "webui"))),
                )
                self.assertTrue(any(os.path.samefile(item, local_ckpt) for item in source_runtime._source_backend_model_dir_args()[1::2]))
        finally:
            if old_reference_roots is None:
                os.environ.pop("FORGE_NEO_REFERENCE_ROOTS", None)
            else:
                os.environ["FORGE_NEO_REFERENCE_ROOTS"] = old_reference_roots
            if old_auto_roots is None:
                os.environ.pop("FORGE_NEO_AUTO_REFERENCE_ROOTS", None)
            else:
                os.environ["FORGE_NEO_AUTO_REFERENCE_ROOTS"] = old_auto_roots
            if old_source_config_paths is None:
                os.environ.pop("FORGE_NEO_SOURCE_CONFIG_PATHS", None)
            else:
                os.environ["FORGE_NEO_SOURCE_CONFIG_PATHS"] = old_source_config_paths
            if old_data_root is None:
                os.environ.pop("FORGE_NEO_SOURCE_BACKEND_DATA_DIR", None)
            else:
                os.environ["FORGE_NEO_SOURCE_BACKEND_DATA_DIR"] = old_data_root
            if old_model_map is not None:
                config.model_cata_map = old_model_map
            for name, value in old_paths.items():
                if value is not None:
                    setattr(config, name, value)

        self.assertIn("return SOURCE_WEBUI_ROOT", runtime_source)
        self.assertNotIn("_EXTERNAL_V3_PACKAGE_NAME", runtime_source)
        self.assertNotIn("EXTERNAL_V3_PACKAGE_NAME", models_source)
        self.assertNotIn("_is_external_v3_package_path", runtime_source)
        self.assertNotIn("_is_external_v3_package_path", models_source)

