    def test_source_backend_loading_stop_guard_contract(self):
        runtime_source = Path(ROOT, "forge_neo", "runtime_backend", "source_runtime.py").read_text(encoding="utf-8")
        child_source = Path(ROOT, "forge_neo", "runtime_backend", "source_runtime_child.py").read_text(encoding="utf-8")

