    def test_source_backend_preset_model_cache_contract(self):
        sd_models_source = Path(ROOT, "forge_neo", "webui", "modules", "sd_models.py").read_text(encoding="utf-8")

        self.assertIn("from collections import OrderedDict", sd_models_source)
        self.assertIn("_FORGE_MODEL_CACHE = OrderedDict()", sd_models_source)
        self.assertIn("def _forge_model_cache_size() -> int:", sd_models_source)
        self.assertIn('os.environ.get("FORGE_NEO_SOURCE_BACKEND_MODEL_CACHE_SIZE", "1")', sd_models_source)
        self.assertIn("def _forge_model_cache_pop(cache_key: str):", sd_models_source)
        self.assertIn("def _forge_model_cache_store(cache_key: str, model) -> None:", sd_models_source)
        self.assertIn("_FORGE_MODEL_CACHE.clear()", sd_models_source)
        self.assertIn("cached_model = _forge_model_cache_pop(current_hash)", sd_models_source)
        self.assertIn("old_hash = model_data.forge_hash", sd_models_source)
        self.assertIn("_forge_model_cache_store(old_hash, old_model)", sd_models_source)
        self.assertIn('timer.record("forge model cache")', sd_models_source)
        self.assertIn("sd_model = forge_loader(state_dict, additional_state_dicts=additional_state_dicts)", sd_models_source)
        self.assertIn("while len(_FORGE_MODEL_CACHE) > cache_size:", sd_models_source)

        cache_get = sd_models_source.index("cached_model = _forge_model_cache_pop(current_hash)")
        old_store = sd_models_source.index("_forge_model_cache_store(old_hash, old_model)")
        forge_load = sd_models_source.index("sd_model = forge_loader(state_dict, additional_state_dicts=additional_state_dicts)")
        self.assertLess(cache_get, old_store)
        self.assertLess(old_store, forge_load)

        stage_report_path = Path(ROOT, "reports", "forge-neo-stage638-source-backend-preset-model-cache.json")
        self.assertTrue(stage_report_path.is_file())
        stage_report = json.loads(stage_report_path.read_text(encoding="utf-8"))
        self.assertEqual(stage_report["stage"], 638)
        self.assertEqual(stage_report["default_model_cache_size"], 1)
        self.assertTrue(stage_report["preset_switch_keeps_previous_cpu_model"])
        self.assertTrue(stage_report["switch_back_skips_forge_loader"])
        self.assertIn("test_source_backend_preset_model_cache_contract", stage_report["contracts"])

