    def test_source_backend_xyz_axis_options_initialize_without_ui(self):
        module_name = "_forge_neo_xyz_grid_axis_contract"
        stub_names = [
            "backend",
            "backend.logging",
            "modules",
            "modules.scripts",
            "modules.sd_models",
            "modules.shared",
            "modules.errors",
            "modules.images",
            "modules.processing",
            "modules.sd_samplers",
            "modules.sd_schedulers",
            "modules.sd_vae",
            "modules.ui_components",
        ]
        missing = object()
        old_modules = {name: sys.modules.get(name, missing) for name in stub_names}

        def register(name: str, module: types.ModuleType) -> None:
            sys.modules[name] = module
            if "." in name:
                parent_name, child_name = name.rsplit(".", 1)
                setattr(sys.modules[parent_name], child_name, module)

        try:
            backend_pkg = types.ModuleType("backend")
            backend_pkg.__path__ = []
            register("backend", backend_pkg)

            backend_logging = types.ModuleType("backend.logging")
            backend_logging.setup_logger = lambda logger: None
            register("backend.logging", backend_logging)

            modules_pkg = types.ModuleType("modules")
            modules_pkg.__path__ = []
            register("modules", modules_pkg)

            scripts_mod = types.ModuleType("modules.scripts")

            class BaseScript:
                def elem_id(self, value):
                    return value

            scripts_mod.Script = BaseScript
            register("modules.scripts", scripts_mod)

            processing_mod = types.ModuleType("modules.processing")

            class StableDiffusionProcessing:
                pass

            class StableDiffusionProcessingTxt2Img(StableDiffusionProcessing):
                pass

            processing_mod.Processed = object
            processing_mod.StableDiffusionProcessing = StableDiffusionProcessing
            processing_mod.StableDiffusionProcessingTxt2Img = StableDiffusionProcessingTxt2Img
            processing_mod.process_images = lambda p: None
            processing_mod.fix_seed = lambda p: None
            register("modules.processing", processing_mod)

            sd_models_mod = types.ModuleType("modules.sd_models")
            sd_models_mod.model_data = types.SimpleNamespace(forge_loading_parameters={})
            sd_models_mod.select_checkpoint = lambda: None
            sd_models_mod.get_closet_checkpoint_match = lambda name: None
            sd_models_mod.checkpoints_list = {}
            register("modules.sd_models", sd_models_mod)

            shared_mod = types.ModuleType("modules.shared")
            shared_mod.cmd_opts = types.SimpleNamespace(adv_samplers=False)
            shared_mod.opts = types.SimpleNamespace(hide_samplers=[], img_max_size_mp=200, return_grid=True, forge_additional_modules=[])
            shared_mod.state = types.SimpleNamespace()
            shared_mod.latent_upscale_modes = []
            shared_mod.sd_upscalers = []
            shared_mod.prompt_styles = types.SimpleNamespace(styles={})
            shared_mod.total_tqdm = types.SimpleNamespace(updateTotal=lambda total: None)
            register("modules.shared", shared_mod)

            for name in ("errors", "images"):
                register(f"modules.{name}", types.ModuleType(f"modules.{name}"))

            sd_samplers_mod = types.ModuleType("modules.sd_samplers")
            sd_samplers_mod.samplers = []
            sd_samplers_mod.samplers_for_img2img = []
            sd_samplers_mod.samplers_map = {}
            register("modules.sd_samplers", sd_samplers_mod)

            sd_schedulers_mod = types.ModuleType("modules.sd_schedulers")
            sd_schedulers_mod.schedulers = []
            register("modules.sd_schedulers", sd_schedulers_mod)

            sd_vae_mod = types.ModuleType("modules.sd_vae")
            sd_vae_mod.vae_dict = {}
            register("modules.sd_vae", sd_vae_mod)

            ui_components_mod = types.ModuleType("modules.ui_components")

            class ToolButton:
                pass

            ui_components_mod.ToolButton = ToolButton
            register("modules.ui_components", ui_components_mod)

            sys.modules.pop(module_name, None)
            spec = importlib.util.spec_from_file_location(module_name, Path(ROOT, "forge_neo", "webui", "scripts", "xyz_grid.py"))
            module = importlib.util.module_from_spec(spec)
            sys.modules[module_name] = module
            assert spec.loader is not None
            spec.loader.exec_module(module)

            script = module.Script()
            self.assertFalse(hasattr(script, "current_axis_options"))
            txt_labels = [axis.label for axis in script._axis_options_for_processing(module.StableDiffusionProcessingTxt2Img())]
            self.assertIn("Hires steps", txt_labels)
            self.assertIn("Hires sampler", txt_labels)
            self.assertFalse(script._current_axis_options_is_img2img)

            img_labels = [axis.label for axis in script._axis_options_for_processing(module.StableDiffusionProcessing())]
            self.assertNotIn("Hires steps", img_labels)
            self.assertNotIn("Hires sampler", img_labels)
            self.assertIn("Denoising", img_labels)
            self.assertTrue(script._current_axis_options_is_img2img)

            captured = {}

            def fake_draw_xyz_grid(*_args, **kwargs):
                captured.update(kwargs)
                return types.SimpleNamespace(images=[], infotexts=[])

            module.draw_xyz_grid = fake_draw_xyz_grid
            p = module.StableDiffusionProcessingTxt2Img()
            p.width = 64
            p.height = 64
            p.steps = 2
            p.n_iter = 1
            p.batch_size = 1
            p.seed = 123
            p.enable_hr = False
            p.hr_second_pass_steps = 0
            p.styles = []
            p.override_settings = {}
            p.extra_generation_params = {}
            script.run(p, 1, "", [], 14, "", ["Karras", "Simple"], 0, "", [], True, False, False, False, False, False, False, 0, 0, False)
            self.assertEqual(module.state.xyz_plot_x.axis.label, "Nothing")
            self.assertEqual(module.state.xyz_plot_y.axis.label, "Schedule type")
            self.assertEqual(module.state.xyz_plot_y.values, ["Karras", "Simple"])
            self.assertEqual(captured["x_labels"], [""])
            self.assertEqual(captured["y_labels"], ["Schedule type: Karras", "Schedule type: Simple"])
        finally:
            sys.modules.pop(module_name, None)
            for name, old_module in old_modules.items():
                if old_module is missing:
                    sys.modules.pop(name, None)
                else:
                    sys.modules[name] = old_module

    def test_auto_simplemodels_roots_stay_inside_workspace_family(self):
        from forge_neo.bootstrap import ensure_config
        from forge_neo import models
        import shared

        config = ensure_config(test_stub=True)
        old_root = getattr(shared, "root", "")
        old_config_dict = dict(getattr(config, "config_dict", {}) or {})
        old_simplemodels_roots = os.environ.get("FORGE_NEO_SIMPLEMODELS_ROOTS")
        old_auto_simplemodels_roots = os.environ.get("FORGE_NEO_AUTO_SIMPLEMODELS_ROOTS")
        try:
            with tempfile.TemporaryDirectory() as tmp:
                base = Path(tmp) / "New_SimpAI"
                studio = base / "SimpAI_win_dev" / "SimpAI_Studio"
                intended = base / "SimpleModels"
                too_high = Path(tmp) / "SimpleModels"
                for folder in (studio, intended, too_high):
                    folder.mkdir(parents=True)

                shared.root = str(studio)
                config.config_dict = dict(old_config_dict)
                config.config_dict.pop("forge_neo_simplemodels_roots", None)
                os.environ.pop("FORGE_NEO_SIMPLEMODELS_ROOTS", None)
                os.environ["FORGE_NEO_AUTO_SIMPLEMODELS_ROOTS"] = "1"

                roots = list(models._simplemodels_root_candidates(config))
                self.assertTrue(any(os.path.samefile(path, intended) for path in roots))
                self.assertFalse(any(os.path.samefile(path, too_high) for path in roots))
        finally:
            shared.root = old_root
            config.config_dict = old_config_dict
            if old_simplemodels_roots is None:
                os.environ.pop("FORGE_NEO_SIMPLEMODELS_ROOTS", None)
            else:
                os.environ["FORGE_NEO_SIMPLEMODELS_ROOTS"] = old_simplemodels_roots
            if old_auto_simplemodels_roots is None:
                os.environ.pop("FORGE_NEO_AUTO_SIMPLEMODELS_ROOTS", None)
            else:
                os.environ["FORGE_NEO_AUTO_SIMPLEMODELS_ROOTS"] = old_auto_simplemodels_roots

    def test_model_catalogs_read_source_outer_user_config_and_drop_stale_cache_entries(self):
        from forge_neo.bootstrap import ensure_config
        from forge_neo import models
        import shared

        config = ensure_config(test_stub=True)
        old_root = getattr(shared, "root", "")
        old_config_path = getattr(config, "config_path", "")
        old_map = getattr(config, "model_cata_map", None)
        old_modelsinfo = getattr(config, "modelsinfo", None)
        old_paths_checkpoints = getattr(config, "paths_checkpoints", None)
        old_paths_diffusion_models = getattr(config, "paths_diffusion_models", None)
        old_reference_roots = os.environ.get("FORGE_NEO_REFERENCE_ROOTS")
        old_auto_roots = os.environ.get("FORGE_NEO_AUTO_REFERENCE_ROOTS")
        old_simplemodels_roots = os.environ.get("FORGE_NEO_SIMPLEMODELS_ROOTS")
        old_auto_simplemodels_roots = os.environ.get("FORGE_NEO_AUTO_SIMPLEMODELS_ROOTS")
        old_model_config_paths = os.environ.get("FORGE_NEO_MODEL_CONFIG_PATHS")

        class PathlessModelsInfo:
            def get_model_names(self, *_args, **_kwargs):
                return ["stale-cache-copy.safetensors"]

            def get_model_filepath(self, *_args, **_kwargs):
                return ""

        try:
            with tempfile.TemporaryDirectory() as tmp:
                base = Path(tmp) / "New_SimpAI"
                studio = base / "SimpAI_win_dev" / "SimpAI_Studio"
                studio_users = studio / "users"
                outer_users = base / "users"
                outer_checkpoints = base / "SimpleModels" / "checkpoints"
                for folder in (studio_users, outer_users, outer_checkpoints):
                    folder.mkdir(parents=True)
                (studio_users / "config.txt").write_text("{}", encoding="utf-8")
                (outer_users / "config.txt").write_text(
                    json.dumps({"path_checkpoints": ["..\\..\\SimpleModels\\checkpoints"]}),
                    encoding="utf-8",
                )
                (outer_checkpoints / "outer-config-real.safetensors").write_bytes(b"outer-real")
                (outer_checkpoints / "stale-cache-copy.safetensors").write_bytes(b"")

                shared.root = str(studio)
                config.config_path = str(studio_users / "config.txt")
                config.model_cata_map = {"checkpoints": [], "diffusion_models": []}
                config.modelsinfo = PathlessModelsInfo()
                config.paths_checkpoints = []
                config.paths_diffusion_models = []
                os.environ.pop("FORGE_NEO_REFERENCE_ROOTS", None)
                os.environ.pop("FORGE_NEO_SIMPLEMODELS_ROOTS", None)
                os.environ.pop("FORGE_NEO_MODEL_CONFIG_PATHS", None)
                os.environ["FORGE_NEO_AUTO_REFERENCE_ROOTS"] = "0"
                os.environ["FORGE_NEO_AUTO_SIMPLEMODELS_ROOTS"] = "0"

                roots = models.model_roots_for_catalog("checkpoints")
                self.assertTrue(any(os.path.samefile(root, outer_checkpoints) for root in roots))
                names = models._model_names("checkpoints")
                self.assertIn("outer-config-real.safetensors", names)
                self.assertNotIn("stale-cache-copy.safetensors", names)
                self.assertTrue(
                    os.path.samefile(
                        models.find_model_path("outer-config-real.safetensors", "checkpoints"),
                        outer_checkpoints / "outer-config-real.safetensors",
                    )
                )
        finally:
            shared.root = old_root
            config.config_path = old_config_path
            if old_map is not None:
                config.model_cata_map = old_map
            config.modelsinfo = old_modelsinfo
            if old_paths_checkpoints is not None:
                config.paths_checkpoints = old_paths_checkpoints
            if old_paths_diffusion_models is not None:
                config.paths_diffusion_models = old_paths_diffusion_models
            if old_reference_roots is None:
                os.environ.pop("FORGE_NEO_REFERENCE_ROOTS", None)
            else:
                os.environ["FORGE_NEO_REFERENCE_ROOTS"] = old_reference_roots
            if old_auto_roots is None:
                os.environ.pop("FORGE_NEO_AUTO_REFERENCE_ROOTS", None)
            else:
                os.environ["FORGE_NEO_AUTO_REFERENCE_ROOTS"] = old_auto_roots
            if old_simplemodels_roots is None:
                os.environ.pop("FORGE_NEO_SIMPLEMODELS_ROOTS", None)
            else:
                os.environ["FORGE_NEO_SIMPLEMODELS_ROOTS"] = old_simplemodels_roots
            if old_auto_simplemodels_roots is None:
                os.environ.pop("FORGE_NEO_AUTO_SIMPLEMODELS_ROOTS", None)
            else:
                os.environ["FORGE_NEO_AUTO_SIMPLEMODELS_ROOTS"] = old_auto_simplemodels_roots
            if old_model_config_paths is None:
                os.environ.pop("FORGE_NEO_MODEL_CONFIG_PATHS", None)
            else:
                os.environ["FORGE_NEO_MODEL_CONFIG_PATHS"] = old_model_config_paths

    def test_disable_backend_generate_contract_returns_image_and_infotext(self):
        from forge_neo.runtime import ForgeNeoRequest, generate

        events: list[dict[str, object]] = []
        result = generate(
            ForgeNeoRequest(
                prompt='a cinematic shot of a neon sign that says "NEO" on a brick wall',
                checkpoint="flux-test.safetensors",
                text_encoders=["qwen-test.gguf"],
                width=320,
                height=256,
                steps=2,
                seed=123,
                denoising_strength=0.6,
                styles=["Photo"],
                loras=["lora-test.safetensors"],
            ),
            progress_callback=events.append,
        )
        self.assertEqual(result.status, "finished")
        self.assertEqual(result.seed, 123)
        self.assertEqual(len(result.images), 1)
        self.assertIn("Steps: 2", result.infotext)
        self.assertIn("Model: flux-test.safetensors", result.infotext)
        self.assertIn("Denoising strength: 0.6", result.infotext)
        self.assertIn("Styles: Photo", result.infotext)
        self.assertIn("LoRA: lora-test.safetensors", result.infotext)
        self.assertTrue(any(event.get("event") == "finish" for event in events))

        xyz_result = generate(
            ForgeNeoRequest(
                prompt="xyz smoke",
                width=64,
                height=64,
                steps=1,
                seed=321,
                script="X/Y/Z plot",
                script_args={
                    "x_type": "Seed",
                    "x_values": "1, 2",
                    "y_type": "CFG Scale",
                    "y_values": "5, 7",
                    "z_type": "Nothing",
                    "z_values": "",
                    "draw_legend": True,
                },
            )
        )
        self.assertEqual(xyz_result.status, "finished")
        self.assertEqual(len(xyz_result.images), 4)
        self.assertIn("Script: X/Y/Z plot", xyz_result.infotext)
        self.assertIn("X values: 1, 2", xyz_result.infotext)
        self.assertIn("Y type: CFG Scale", xyz_result.infotext)

        prompt_matrix_result = generate(
            ForgeNeoRequest(
                prompt="base | red | blue",
                width=64,
                height=64,
                steps=1,
                seed=77,
                script="Prompt Matrix",
                script_args={"prompt_type": "positive", "variations_delimiter": "comma", "different_seeds": True},
            )
        )
        self.assertEqual(prompt_matrix_result.status, "finished")
        self.assertEqual(len(prompt_matrix_result.images), 4)
        self.assertIn("Script: Prompt Matrix", prompt_matrix_result.infotext)
        self.assertIn("different seeds: True", prompt_matrix_result.infotext)

        prompts_result = generate(
            ForgeNeoRequest(
                prompt="base prompt",
                width=64,
                height=64,
                steps=1,
                seed=88,
                script="Prompts from File or Textbox",
                script_args={"prompt_text": "first line\nsecond line", "prompt_position": "end", "iterate_seed": True},
            )
        )
        self.assertEqual(prompts_result.status, "finished")
        self.assertEqual(len(prompts_result.images), 2)
        self.assertIn("Prompt lines: 2", prompts_result.infotext)

        upscale_result = generate(
            ForgeNeoRequest(
                prompt="upscale smoke",
                width=300,
                height=256,
                steps=1,
                seed=89,
                script="SD Upscale",
                script_args={"scale_factor": 2.0, "upscaler": "Latent", "overlap": 64},
            )
        )
        self.assertEqual(upscale_result.status, "finished")
        self.assertEqual(len(upscale_result.images), 1)
        self.assertEqual(upscale_result.images[0].size, (600, 512))
        self.assertIn("Scale Factor: 2.0", upscale_result.infotext)

    def test_backend_unavailable_does_not_generate_placeholder_contract(self):
        from forge_neo import runtime
        from forge_neo.runtime_backend import adapter
        from forge_neo.worker import ForgeNeoWorker

        old_disable_backend = adapter.args_manager.args.disable_backend
        old_run_backend_generation = adapter.run_backend_generation
        try:
            adapter.args_manager.args.disable_backend = False

            def fake_backend_generation(request, progress_callback=None, control_callback=None):
                return runtime.ForgeNeoResult(status="backend_unavailable", error="adapter missing for test")

            adapter.run_backend_generation = fake_backend_generation
            events: list[dict[str, object]] = []
            result = runtime.generate(
                runtime.ForgeNeoRequest(prompt="no placeholder", width=64, height=64, steps=1, seed=1234),
                progress_callback=events.append,
            )
            self.assertEqual(result.status, "backend_unavailable")
            self.assertEqual(result.seed, 1234)
            self.assertEqual(result.images, [])
            self.assertEqual(result.output_paths, [])
            self.assertIn("adapter missing for test", result.error)
            self.assertTrue(any(event.get("event") == "finish" and event.get("message") == "backend_unavailable" for event in events))

            worker = ForgeNeoWorker()
            worker.reset()
            worker._finish(result)
            snapshot = worker.snapshot()
            self.assertEqual(snapshot["status"], "backend_unavailable")
            self.assertEqual(snapshot["progress"], 1.0)
            self.assertEqual(snapshot["message_en"], "Backend unavailable.")
            self.assertEqual(snapshot["message_cn"], "后端不可用。")

            runtime_source = Path(ROOT, "forge_neo", "runtime.py").read_text(encoding="utf-8")
            self.assertIn("if not backend_disabled:", runtime_source)
            self.assertIn('status="backend_unavailable"', runtime_source)
            ui_source = Path(ROOT, "forge_neo", "ui.py").read_text(encoding="utf-8")
            self.assertIn('elif result.status == "backend_unavailable":', ui_source)
            self.assertIn("不会生成占位采样图", ui_source)
        finally:
            adapter.run_backend_generation = old_run_backend_generation
            adapter.args_manager.args.disable_backend = old_disable_backend

    def test_disable_backend_batch_and_worker_control_contract(self):
        from PIL import Image

        from forge_neo.runtime import ForgeNeoExtrasRequest, ForgeNeoRequest, generate, run_extras
        from forge_neo.worker import ForgeNeoWorker

        batch_result = generate(
            ForgeNeoRequest(
                prompt="batch smoke",
                width=64,
                height=64,
                steps=1,
                seed=7,
                batch_count=2,
                batch_size=2,
            )
        )
        self.assertEqual(batch_result.status, "finished")
        self.assertEqual(len(batch_result.images), 4)

        extras_result = run_extras(
            ForgeNeoExtrasRequest(image=Image.new("RGB", (64, 64))),
            control_callback=lambda: "stopped",
        )
        self.assertEqual(extras_result.status, "stopped")

        local_worker = ForgeNeoWorker()
        holder: dict[str, object] = {}

        def run_generation() -> None:
            holder["result"] = local_worker.run(
                ForgeNeoRequest(prompt="stop smoke", width=64, height=64, steps=80, seed=9),
                {"__lang": "cn"},
            )

        thread = threading.Thread(target=run_generation)
        thread.start()
        for _ in range(100):
            if local_worker.snapshot()["events"]:
                break
            time.sleep(0.01)
        local_worker.stop()
        thread.join(timeout=5)
        self.assertFalse(thread.is_alive())
        stopped = holder["result"]
        self.assertEqual(stopped.status, "stopped")
        self.assertEqual(local_worker.snapshot()["status"], "stopped")

        local_worker = ForgeNeoWorker()
        holder = {}

        def run_skip_generation() -> None:
            holder["result"] = local_worker.run(
                ForgeNeoRequest(prompt="skip smoke", width=64, height=64, steps=80, seed=11),
                {"__lang": "cn"},
            )

        thread = threading.Thread(target=run_skip_generation)
        thread.start()
        for _ in range(100):
            if local_worker.snapshot()["events"]:
                break
            time.sleep(0.01)
        local_worker.skip()
        thread.join(timeout=5)
        self.assertFalse(thread.is_alive())
        skipped = holder["result"]
        self.assertEqual(skipped.status, "skipped")
        self.assertEqual(local_worker.snapshot()["status"], "skipped")
        local_worker.reset()
        local_worker.stop()
        unload_result = local_worker.unload_runtime_state()
        self.assertEqual(unload_result["previous_status"], "running")
        self.assertIn("parent_model_unload", unload_result)
        self.assertIn("source_backend", unload_result)
        self.assertIn("gc_collected", unload_result)
        self.assertIn("torch_available", unload_result)
        snapshot = local_worker.snapshot()
        self.assertEqual(snapshot["status"], "idle")
        self.assertFalse(snapshot["stop_requested"])
        self.assertFalse(snapshot["skip_requested"])
        self.assertEqual(snapshot["events"], [])

