    def test_source_progress_live_preview_id_gate_contract(self):
        from fastapi import FastAPI
        from fastapi.testclient import TestClient
        from PIL import Image

        from forge_neo.api import install_api_routes, progress_payload
        from forge_neo.worker import worker

        worker.reset()
        try:
            worker._progress(
                {
                    "event": "progress",
                    "progress": 0.5,
                    "message": "sampling 1/2",
                    "sampling_step": 1,
                    "sampling_steps": 2,
                    "current_image": Image.new("RGB", (8, 8), "red"),
                    "id_live_preview": 7,
                }
            )
            first_payload = progress_payload(skip_current_image=False, id_live_preview=6)
            self.assertEqual(first_payload["id_live_preview"], 7)
            self.assertTrue(first_payload["current_image"])
            self.assertTrue(first_payload["live_preview"].startswith("data:image/png;base64,"))

            same_payload = progress_payload(skip_current_image=False, id_live_preview=7)
            self.assertEqual(same_payload["id_live_preview"], 7)
            self.assertIsNone(same_payload["current_image"])
            self.assertNotIn("live_preview", same_payload)

            app = FastAPI()
            install_api_routes(app)
            client = TestClient(app)
            response = client.get("/forge-neo/api/progress?id_live_preview=7")
            self.assertEqual(response.status_code, 200)
            self.assertIsNone(response.json()["current_image"])
            self.assertEqual(response.json()["id_live_preview"], 7)
            self.assertNotIn("live_preview", response.json())
            response = client.get("/sdapi/v1/progress?id_live_preview=6")
            self.assertEqual(response.status_code, 200)
            self.assertTrue(response.json()["current_image"])
            self.assertNotIn("id_live_preview", response.json())
            self.assertNotIn("live_preview", response.json())
        finally:
            worker.reset()

        api_source = Path(ROOT, "forge_neo", "api.py").read_text(encoding="utf-8")
        js_source = Path(ROOT, "javascript", "forge_neo.js").read_text(encoding="utf-8")
        classic_progress_source = Path(ROOT, "..", "sd-webui-forge-classic", "modules", "progress.py").read_text(encoding="utf-8")
        classic_js_source = Path(ROOT, "..", "sd-webui-forge-classic", "javascript", "progressbar.js").read_text(encoding="utf-8")
        self.assertIn("id_live_preview = req.id_live_preview", classic_progress_source)
        self.assertIn("if shared.state.id_live_preview != req.id_live_preview:", classic_progress_source)
        self.assertIn("funProgress(id_task, res.id_live_preview)", classic_js_source)
        self.assertIn("funLivePreview(id_task, res.id_live_preview)", classic_js_source)
        self.assertIn("def progress_payload(*, skip_current_image: bool = False, id_live_preview: int | None = None)", api_source)
        self.assertIn("if id_live_preview is not None and current_preview_id == int(id_live_preview):", api_source)
        self.assertIn('"id_live_preview", String(Math.round(Number(idLivePreview)))', js_source)
        self.assertIn("fetch(progressUrl(activeLivePreviewId)", js_source)

