    def test_source_conditioning_cache_clip_skip_contract(self):
        from forge_neo.runtime_backend.args import dynamic_args
        from forge_neo.modules import processing, prompt_parser, shared

        class FakeModel:
            def __init__(self):
                self.extra_generation_params = {}
                self.clip_skip_calls = []

            def set_clip_skip(self, value):
                self.clip_skip_calls.append(value)

        old_shared_model = shared.sd_model
        old_clip_skip = shared.opts.CLIP_stop_at_last_layers
        old_persistent_cache = shared.opts.persistent_cond_cache
        old_learned = prompt_parser.get_learned_conditioning
        old_multicond = prompt_parser.get_multicond_learned_conditioning
        old_last_params = dict(dynamic_args.last_extra_generation_params)
        processing.StableDiffusionProcessing.cached_c = [None, None, None]
        processing.StableDiffusionProcessing.cached_uc = [None, None, None]
        try:
            model = FakeModel()
            shared.sd_model = model
            shared.opts.CLIP_stop_at_last_layers = 2
            shared.opts.persistent_cond_cache = True
            calls = []

            def fake_learned(model_arg, prompts, steps, hires_steps=None):
                self.assertIs(model_arg, model)
                calls.append(("uc", tuple(prompts), steps, hires_steps))
                dynamic_args.last_extra_generation_params["UC Param"] = "from uc"
                return ("uc-result", len(calls))

            def fake_multicond(model_arg, prompts, steps, hires_steps=None):
                self.assertIs(model_arg, model)
                calls.append(("c", tuple(prompts), steps, hires_steps))
                dynamic_args.last_extra_generation_params["C Param"] = "from c"
                return ("c-result", len(calls))

            prompt_parser.get_learned_conditioning = fake_learned
            prompt_parser.get_multicond_learned_conditioning = fake_multicond

            p = processing.StableDiffusionProcessingTxt2Img(
                sd_model=model,
                prompt="cache prompt",
                negative_prompt="cache negative",
                sampler_name="Euler a",
                steps=2,
                width=64,
                height=64,
                cfg_scale=4.0,
                distilled_cfg_scale=3.0,
                batch_size=1,
                n_iter=1,
            )
            p.prompts = list(p.all_prompts)
            p.negative_prompts = list(p.all_negative_prompts)
            p.extra_network_data = {"lora": []}

            p.setup_conds()
            first_uc = p.uc
            first_c = p.c
            self.assertEqual(calls, [("uc", ("cache negative",), 2, None), ("c", ("cache prompt",), 2, None)])
            self.assertEqual(model.clip_skip_calls, [2, 2])
            self.assertEqual(model.extra_generation_params["UC Param"], "from uc")
            self.assertEqual(model.extra_generation_params["C Param"], "from c")
            self.assertEqual(dynamic_args.last_extra_generation_params, {})

            p.setup_conds()
            self.assertEqual(len(calls), 2)
            self.assertIs(p.uc, first_uc)
            self.assertIs(p.c, first_c)
            self.assertEqual(model.clip_skip_calls, [2, 2])

            p.close()
            self.assertIsNotNone(processing.StableDiffusionProcessing.cached_c[0])

            shared.opts.persistent_cond_cache = False
            p.close()
            self.assertIsNone(processing.StableDiffusionProcessing.cached_c[0])
            self.assertIsNone(processing.StableDiffusionProcessing.cached_uc[0])
        finally:
            shared.sd_model = old_shared_model
            shared.opts.CLIP_stop_at_last_layers = old_clip_skip
            shared.opts.persistent_cond_cache = old_persistent_cache
            prompt_parser.get_learned_conditioning = old_learned
            prompt_parser.get_multicond_learned_conditioning = old_multicond
            dynamic_args.last_extra_generation_params.clear()
            dynamic_args.last_extra_generation_params.update(old_last_params)
            processing.StableDiffusionProcessing.cached_c = [None, None, None]
            processing.StableDiffusionProcessing.cached_uc = [None, None, None]

        source = Path(ROOT, "forge_neo", "modules", "processing.py").read_text(encoding="utf-8")
        classic_source = Path(ROOT, "..", "sd-webui-forge-classic", "modules", "processing.py").read_text(encoding="utf-8")
        self.assertIn("def get_conds_with_caching", classic_source)
        self.assertIn("shared.sd_model.set_clip_skip(int(opts.CLIP_stop_at_last_layers))", classic_source)
        self.assertIn("last_extra_generation_params = args.dynamic_args.last_extra_generation_params", classic_source)
        self.assertIn("def get_conds_with_caching", source)
        self.assertIn("set_clip_skip(int(_opts_value(\"CLIP_stop_at_last_layers\", 2) or 2))", source)
        self.assertIn("last_extra_generation_params = getattr(dynamic_args, \"last_extra_generation_params\", {})", source)
        self.assertIn("if not bool(_opts_value(\"persistent_cond_cache\", False)):", source)

        stage_report_path = Path(ROOT, "reports", "forge-neo-stage463-conditioning-cache-clip-skip.json")
        primary_summary_path = Path(ROOT, "reports", "forge-neo-stage463-anima-source-neo-ab-clip-skip", "summary.json")
        seed462_summary_path = Path(ROOT, "reports", "forge-neo-stage463-anima-source-neo-ab-clip-skip-seed462", "summary.json")
        self.assertTrue(stage_report_path.is_file())
        self.assertTrue(primary_summary_path.is_file())
        self.assertTrue(seed462_summary_path.is_file())

        stage_report = json.loads(stage_report_path.read_text(encoding="utf-8"))
        primary_summary = json.loads(primary_summary_path.read_text(encoding="utf-8"))
        seed462_summary = json.loads(seed462_summary_path.read_text(encoding="utf-8"))
        self.assertEqual(stage_report["stage"], 463)
        self.assertEqual(stage_report["processing_stage"], "source_conditioning_cache_clip_skip_port")
        self.assertEqual(stage_report["ab"]["primary_seed"], 463)
        self.assertTrue(stage_report["ab"]["primary_source_ok"])
        self.assertTrue(stage_report["ab"]["primary_neo_ok"])
        self.assertEqual(stage_report["ab"]["primary_mae_rgb_avg"], 106.834)
        self.assertTrue(stage_report["ab"]["seed462_matches_stage462_metrics"])
        self.assertEqual(stage_report["ab"]["seed462_mae_rgb_avg"], 96.3676)
        self.assertEqual(primary_summary["payload"]["seed"], 463)
        self.assertTrue(primary_summary["source"]["ok"])
        self.assertTrue(primary_summary["neo"]["ok"])
        self.assertEqual(primary_summary["neo"]["progress_has_preview_count"], 1)
        self.assertEqual(primary_summary["image_metrics"]["mae_rgb_avg"], 106.834)
        self.assertEqual(seed462_summary["payload"]["seed"], 462)
        self.assertEqual(seed462_summary["image_metrics"]["mae_rgb_avg"], 96.3676)
        self.assertIn("test_source_conditioning_cache_clip_skip_contract", stage_report["contracts"])

    def test_source_prompt_schedule_parser_contract(self):
        from forge_neo.modules import prompt_parser

        self.assertEqual(prompt_parser.get_learned_conditioning_prompt_schedules(["test"], 10)[0], [[10, "test"]])
        self.assertEqual(prompt_parser.get_learned_conditioning_prompt_schedules(["a [b:3]"], 10)[0], [[3, "a "], [10, "a b"]])
        self.assertEqual(prompt_parser.get_learned_conditioning_prompt_schedules(["a [b: 3]"], 10)[0], [[3, "a "], [10, "a b"]])
        self.assertEqual(prompt_parser.get_learned_conditioning_prompt_schedules(["a [[[b]]:2]"], 10)[0], [[2, "a "], [10, "a [[b]]"]])
        self.assertEqual(prompt_parser.get_learned_conditioning_prompt_schedules(["[(a:2):3]"], 10)[0], [[3, ""], [10, "(a:2)"]])
        self.assertEqual(prompt_parser.get_learned_conditioning_prompt_schedules(["a [b : c : 1] d"], 10)[0], [[1, "a b  d"], [10, "a  c  d"]])
        self.assertEqual(prompt_parser.get_learned_conditioning_prompt_schedules(["a[b:[c:d:2]:1]e"], 10)[0], [[1, "abe"], [2, "ace"], [10, "ade"]])
        self.assertEqual(prompt_parser.get_learned_conditioning_prompt_schedules(["a [unbalanced"], 10)[0], [[10, "a [unbalanced"]])
        self.assertEqual(prompt_parser.get_learned_conditioning_prompt_schedules(["a [b:.5] c"], 10)[0], [[5, "a  c"], [10, "a b c"]])
        self.assertEqual(
            prompt_parser.get_learned_conditioning_prompt_schedules(["[a|(b:1.1)]"], 10)[0],
            [[1, "a"], [2, "(b:1.1)"], [3, "a"], [4, "(b:1.1)"], [5, "a"], [6, "(b:1.1)"], [7, "a"], [8, "(b:1.1)"], [9, "a"], [10, "(b:1.1)"]],
        )
        self.assertEqual(
            prompt_parser.get_learned_conditioning_prompt_schedules(["[fe|]male"], 10)[0],
            [[1, "female"], [2, "male"], [3, "female"], [4, "male"], [5, "female"], [6, "male"], [7, "female"], [8, "male"], [9, "female"], [10, "male"]],
        )
        self.assertEqual(prompt_parser.get_learned_conditioning_prompt_schedules(["a [b:.5] c"], 10, 10)[0], [[10, "a b c"]])
        self.assertEqual(prompt_parser.get_learned_conditioning_prompt_schedules(["a [b:1.5] c"], 10, 10)[0], [[5, "a  c"], [10, "a b c"]])

        class FakeModel:
            def __init__(self):
                self.text_batches = []

            def get_learned_conditioning(self, texts):
                self.text_batches.append(list(texts))
                return [f"cond:{text}" for text in texts]

        model = FakeModel()
        schedules = prompt_parser.get_learned_conditioning(model, prompt_parser.SdConditioning(["a [b:3]"], width=64, height=64), 10)
        self.assertEqual(model.text_batches, [["a ", "a b"]])
        self.assertEqual([row.end_at_step for row in schedules[0]], [3, 10])
        self.assertEqual([row.cond for row in schedules[0]], ["cond:a ", "cond:a b"])

        source = Path(ROOT, "forge_neo", "modules", "prompt_parser.py").read_text(encoding="utf-8")
        classic_source = Path(ROOT, "..", "sd-webui-forge-classic", "modules", "prompt_parser.py").read_text(encoding="utf-8")
        self.assertIn("schedule_parser = lark.Lark", classic_source)
        self.assertIn("alternate: \"[\" prompt (\"|\" [prompt])+ \"]\"", classic_source)
        self.assertIn("schedule_parser = lark.Lark", source)
        self.assertIn("alternate: \"[\" prompt (\"|\" [prompt])+ \"]\"", source)
        self.assertNotIn("return [[(end_at_step, str(prompt or \"\"))]", source)

        stage_report_path = Path(ROOT, "reports", "forge-neo-stage464-prompt-schedule-parser.json")
        self.assertTrue(stage_report_path.is_file())
        stage_report = json.loads(stage_report_path.read_text(encoding="utf-8"))
        self.assertEqual(stage_report["stage"], 464)
        self.assertEqual(stage_report["processing_stage"], "source_prompt_schedule_parser_port")
        self.assertIn("test_source_prompt_schedule_parser_contract", stage_report["contracts"])

    def test_source_prompt_reconstruction_batch_contract(self):
        import torch

        from forge_neo.modules import prompt_parser

        Scheduled = prompt_parser.ScheduledPromptConditioning
        tensor_a = torch.ones((2, 3), dtype=torch.float32)
        tensor_b = torch.ones((2, 3), dtype=torch.float32) * 2
        tensor_c = torch.ones((2, 3), dtype=torch.float32) * 3
        reconstructed = prompt_parser.reconstruct_cond_batch(
            [
                [Scheduled(2, tensor_a), Scheduled(4, tensor_b)],
                [Scheduled(4, tensor_c)],
            ],
            3,
        )
        self.assertTrue(isinstance(reconstructed, torch.Tensor))
        self.assertEqual(tuple(reconstructed.shape), (2, 2, 3))
        self.assertEqual(float(reconstructed[0].sum()), 12.0)
        self.assertEqual(float(reconstructed[1].sum()), 18.0)

        dict_reconstructed = prompt_parser.reconstruct_cond_batch(
            [
                [
                    Scheduled(
                        4,
                        {
                            "crossattn": torch.ones((2, 3), dtype=torch.float32),
                            "vector": torch.ones((4,), dtype=torch.float32),
                        },
                    )
                ],
                [
                    Scheduled(
                        4,
                        {
                            "crossattn": torch.ones((2, 3), dtype=torch.float32) * 5,
                            "vector": torch.ones((4,), dtype=torch.float32) * 7,
                        },
                    )
                ],
            ],
            1,
        )
        self.assertTrue(isinstance(dict_reconstructed, prompt_parser.DictWithShape))
        self.assertEqual(tuple(dict_reconstructed.shape), (2, 2, 3))
        self.assertEqual(tuple(dict_reconstructed["vector"].shape), (2, 4))
        self.assertEqual(float(dict_reconstructed["crossattn"][1].sum()), 30.0)
        self.assertEqual(float(dict_reconstructed["vector"][1].sum()), 28.0)

        short = torch.tensor([[1.0, 2.0, 3.0]], dtype=torch.float32)
        long = torch.tensor([[4.0, 5.0, 6.0], [7.0, 8.0, 9.0]], dtype=torch.float32)
        multicond = prompt_parser.MulticondLearnedConditioning(
            shape=(2,),
            batch=[
                [prompt_parser.ComposableScheduledPromptConditioning([Scheduled(4, short)], 1.0)],
                [prompt_parser.ComposableScheduledPromptConditioning([Scheduled(4, long)], 0.5)],
            ],
        )
        conds_list, stacked = prompt_parser.reconstruct_multicond_batch(multicond, 1)
        self.assertEqual(conds_list, [[(0, 1.0)], [(1, 0.5)]])
        self.assertTrue(isinstance(stacked, torch.Tensor))
        self.assertEqual(tuple(stacked.shape), (2, 2, 3))
        self.assertEqual(stacked[0].tolist(), [[1.0, 2.0, 3.0], [1.0, 2.0, 3.0]])
        self.assertEqual(stacked[1].tolist(), [[4.0, 5.0, 6.0], [7.0, 8.0, 9.0]])

        source = Path(ROOT, "forge_neo", "modules", "prompt_parser.py").read_text(encoding="utf-8")
        classic_source = Path(ROOT, "..", "sd-webui-forge-classic", "modules", "prompt_parser.py").read_text(encoding="utf-8")
        self.assertIn("def reconstruct_cond_batch(c: list[list[ScheduledPromptConditioning]], current_step):", classic_source)
        self.assertIn("def stack_conds(tensors):", classic_source)
        self.assertIn("def reconstruct_cond_batch(cond: list[list[ScheduledPromptConditioning]], current_step):", source)
        self.assertIn("def stack_conds(tensors):", source)
        self.assertIn("if current_step <= entry.end_at_step:", source)
        self.assertIn("stacked = DictWithShape(stacked)", source)

        stage_report_path = Path(ROOT, "reports", "forge-neo-stage465-prompt-reconstruction-batch.json")
        self.assertTrue(stage_report_path.is_file())
        stage_report = json.loads(stage_report_path.read_text(encoding="utf-8"))
        self.assertEqual(stage_report["stage"], 465)
        self.assertEqual(stage_report["processing_stage"], "source_prompt_reconstruction_batch_port")
        self.assertIn("test_source_prompt_reconstruction_batch_contract", stage_report["contracts"])

