    def test_sdapi_generation_source_infotext_override_settings_response_contract(self):
        from fastapi import FastAPI
        from fastapi.testclient import TestClient

        from forge_neo import api
        from forge_neo.runtime import ForgeNeoResult

        infotext = (
            "source infotext response prompt\n"
            "Negative prompt: source infotext response negative\n"
            "Steps: 1, Sampler: Euler, CFG scale: 2, Seed: 123, Size: 64x64"
        )

        captured_requests = []
        old_generate = api.generate

        def fake_generate(request):
            captured_requests.append(request)
            return ForgeNeoResult(images=[], infotext="stage 624 ok", seed=request.seed)

        try:
            api.generate = fake_generate
            app = FastAPI()
            api.install_api_routes(app)
            client = TestClient(app)

            txt_response = client.post(
                "/sdapi/v1/txt2img",
                json={"infotext": infotext, "override_settings": None, "send_images": False},
            )
            self.assertEqual(txt_response.status_code, 200, txt_response.text)
            txt_params = txt_response.json()["parameters"]
            self.assertEqual(txt_params["override_settings"], {})
            self.assertEqual(txt_params["prompt"], "source infotext response prompt")
            self.assertEqual(txt_params["negative_prompt"], "source infotext response negative")

            txt_default_response = client.post(
                "/sdapi/v1/txt2img",
                json={"infotext": infotext, "send_images": False},
            )
            self.assertEqual(txt_default_response.status_code, 200, txt_default_response.text)
            self.assertEqual(txt_default_response.json()["parameters"]["override_settings"], {})

            txt_null_response = client.post(
                "/sdapi/v1/txt2img",
                json={"override_settings": None, "send_images": False},
            )
            self.assertEqual(txt_null_response.status_code, 200, txt_null_response.text)
            self.assertIsNone(txt_null_response.json()["parameters"]["override_settings"])

            img_response = client.post(
                "/sdapi/v1/img2img",
                json={"init_images": [], "infotext": infotext, "override_settings": None, "send_images": False},
            )
            self.assertEqual(img_response.status_code, 200, img_response.text)
            self.assertEqual(img_response.json()["parameters"]["override_settings"], {})
            self.assertEqual(len(captured_requests), 4)
        finally:
            api.generate = old_generate

        stage_report_path = Path(ROOT, "reports", "forge-neo-stage624-sdapi-generation-source-infotext-override-settings-response.json")
        self.assertTrue(stage_report_path.is_file())
        stage_report = json.loads(stage_report_path.read_text(encoding="utf-8"))
        self.assertEqual(stage_report["stage"], 624)
        self.assertIn("test_sdapi_generation_source_infotext_override_settings_response_contract", stage_report["contracts"])

