    def test_seed_random_button_restores_random_sentinel_contract(self):
        source = Path(ROOT, "forge_neo", "ui.py").read_text(encoding="utf-8")
        module = ast.parse(source)
        function = next(
            node
            for node in module.body
            if isinstance(node, ast.FunctionDef) and node.name == "_random_seed_clicked"
        )
        self.assertEqual(len(function.body), 1)
        self.assertIsInstance(function.body[0], ast.Return)
        self.assertEqual(ast.literal_eval(function.body[0].value), -1)

