    def test_extras_upscaler_choice_values_contract(self):
        from forge_neo import ui
        from forge_neo.ui import _extras_upscaler_choices, _low_bit_choices

        self.assertEqual(
            _extras_upscaler_choices()[:5],
            [
                ("Nearest-最近邻", "Nearest"),
                ("Bilinear-双线性", "Bilinear"),
                ("Bicubic-双三次", "Bicubic"),
                ("Lanczos-兰索斯", "Lanczos"),
                ("ESRGAN", "ESRGAN"),
            ],
        )
        self.assertEqual(_extras_upscaler_choices(include_none=True)[0], ("None-无", "None"))
        self.assertEqual(_low_bit_choices()[0], ("自动", "Automatic"))
        low_bit_values = [choice[1] if isinstance(choice, tuple) else choice for choice in _low_bit_choices()]
        self.assertNotIn("Int8", low_bit_values)
        self.assertNotIn("Int8 (fp16 LoRA)", low_bit_values)
        self.assertEqual(_low_bit_choices()[-1], ("无", "None"))
        old_upscale_model_names = ui.upscale_model_names
        try:
            ui.upscale_model_names = lambda: ["RealESRGAN_x2plus", "4x-UltraSharp"]
            self.assertIn("Lanczos", ui._hires_upscaler_names())
            self.assertIn("ESRGAN", ui._hires_upscaler_names())
            self.assertIn("RealESRGAN_x2plus", ui._hires_upscaler_names())
            self.assertIn("4x-UltraSharp", ui._script_upscaler_choices())
            self.assertIn("RealESRGAN_x2plus", ui._upscaler_names(include_latent=True))
            self.assertIn(("RealESRGAN_x2plus", "RealESRGAN_x2plus"), _extras_upscaler_choices())
            self.assertIn(("4x-UltraSharp", "4x-UltraSharp"), _extras_upscaler_choices(include_none=True))
            self.assertIn(("无", "None"), ui._hires_upscaler_choices())
        finally:
            ui.upscale_model_names = old_upscale_model_names

