    def test_batch_edit_generate_plan_contract(self):
        from PIL import Image
        from forge_neo.runtime import ForgeNeoBatchEditRequest, build_batch_edit_plan, run_batch_edit

        with tempfile.TemporaryDirectory() as tmp:
            input_dir = Path(tmp) / "input"
            output_dir = Path(tmp) / "output"
            input_dir.mkdir()
            Image.new("RGB", (64, 256), "white").save(input_dir / "a.jpg")
            Image.new("RGB", (100, 50), "black").save(input_dir / "b.png")
            (input_dir / "ignore.txt").write_text("skip", encoding="utf-8")

            result = build_batch_edit_plan(
                ForgeNeoBatchEditRequest(
                    input_dir=str(input_dir),
                    output_dir=str(output_dir),
                    prompt="turn into gray model",
                    negative_prompt="blur",
                    max_edge_length=128,
                    steps=22,
                    cfg_scale=5.5,
                    seed=123,
                    formats=["png", "jpg"],
                    sort_method="文件名升序",
                )
            )
            self.assertEqual(result.status, "plan")
            self.assertEqual(result.progress, "计划就绪: 2/2 张图片")
            self.assertTrue(output_dir.is_dir())
            self.assertEqual([Path(item["input"]).name for item in result.files], ["a.jpg", "b.png"])
            self.assertEqual((result.files[0]["width"], result.files[0]["height"]), (64, 128))
            self.assertEqual((result.files[1]["width"], result.files[1]["height"]), (128, 64))
            self.assertEqual(result.files[0]["seed"], 123)
            self.assertIn("当前为 Forge Neo 迁移计划模式", result.log)
            self.assertIn("采样步数: 22", result.log)
            self.assertIn("CFG Scale: 5.5", result.log)

            executed = run_batch_edit(
                ForgeNeoBatchEditRequest(
                    input_dir=str(input_dir),
                    output_dir=str(output_dir),
                    prompt="turn into gray model",
                    negative_prompt="blur",
                    max_edge_length=128,
                    steps=22,
                    cfg_scale=5.5,
                    seed=123,
                    formats=["png", "jpg"],
                    sort_method="文件名升序",
                )
            )
            self.assertEqual(executed.status, "finished")
            self.assertEqual(executed.progress, "处理完成: 2/2 张图片")
            written_paths = [Path(item["output"]) for item in executed.files if item.get("written")]
            self.assertEqual(len(written_paths), 2)
            for path in written_paths:
                self.assertTrue(path.is_file())
                with Image.open(path) as output_image:
                    self.assertIn(output_image.size, [(64, 128), (128, 64)])
                    self.assertEqual(output_image.format, "PNG")
            self.assertIn("开始 Forge Neo 轻量执行", executed.log)
            self.assertIn("[完成] a.jpg -> processed_a.png", executed.log)

        missing = build_batch_edit_plan(ForgeNeoBatchEditRequest(input_dir="Z:/not/here", output_dir="Z:/out"))
        self.assertEqual(missing.status, "error")
        self.assertIn("输入目录不存在", missing.progress)

