    def test_controlnet_multi_unit_infotext_contract(self):
        from forge_neo.runtime import ForgeNeoRequest, build_infotext

        text = build_infotext(
            ForgeNeoRequest(
                prompt="neon sign",
                controlnet_units=[
                    {
                        "enabled": True,
                        "module": "canny",
                        "model": "control-a.safetensors",
                        "weight": 0.7,
                        "resize_mode": "Crop and Resize",
                        "guidance_start": 0.0,
                        "guidance_end": 0.5,
                        "pixel_perfect": True,
                        "control_mode": "Balanced",
                        "hr_option": "Both",
                        "processor_res": 512,
                        "threshold_a": 100,
                        "threshold_b": 200,
                    },
                    {
                        "enabled": True,
                        "module": "depth",
                        "model": "control-b.safetensors",
                        "weight": 1.1,
                        "resize_mode": "Resize and Fill",
                        "guidance_start": 0.2,
                        "guidance_end": 0.9,
                        "pixel_perfect": False,
                        "control_mode": "ControlNet is more important",
                        "hr_option": "High res only",
                        "processor_res": 768,
                        "threshold_a": 0.5,
                        "threshold_b": 0.5,
                    },
                    {"enabled": False},
                ],
            ),
            seed=46,
        )
        self.assertIn("ControlNet 0: module=canny", text)
        self.assertIn("model=control-a.safetensors", text)
        self.assertIn("processor res=512", text)
        self.assertIn("ControlNet 1: module=depth", text)
        self.assertIn("model=control-b.safetensors", text)
        self.assertIn("processor res=768", text)
        self.assertNotIn("ControlNet 2:", text)

    def test_img2img_submode_infotext_contract(self):
        from forge_neo.runtime import ForgeNeoRequest, build_infotext

        inpaint_text = build_infotext(
            ForgeNeoRequest(
                mode="inpaint_upload",
                prompt="repair wall",
                denoising_strength=0.6,
                selected_scale_tab=1,
                resize_mode="Resize and fill",
                resize_scale=1.5,
                mask_blur=12,
                inpainting_fill="latent noise",
                inpainting_mask_mode="Inpaint not masked",
                inpaint_area="Whole picture",
                inpaint_padding=64,
                soft_inpainting_enabled=True,
                soft_inpainting_schedule_bias=1.2,
                soft_inpainting_preservation_strength=0.7,
                soft_inpainting_transition_contrast_boost=5.0,
                soft_inpainting_mask_influence=0.25,
                soft_inpainting_difference_threshold=0.75,
                soft_inpainting_difference_contrast=2.5,
            ),
            seed=42,
        )
        self.assertIn("Mode: inpaint_upload", inpaint_text)
        self.assertIn("Resize mode: Resize and fill", inpaint_text)
        self.assertIn("Resize tab: Resize by", inpaint_text)
        self.assertIn("Mask blur: 12", inpaint_text)
        self.assertIn("Masked content: latent noise", inpaint_text)
        self.assertIn("Soft inpainting enabled: True", inpaint_text)
        self.assertIn("Soft inpainting schedule bias: 1.2", inpaint_text)
        self.assertIn("Soft inpainting preservation strength: 0.7", inpaint_text)
        self.assertIn("Soft inpainting transition contrast boost: 5.0", inpaint_text)
        self.assertIn("Soft inpainting mask influence: 0.25", inpaint_text)
        self.assertIn("Soft inpainting difference threshold: 0.75", inpaint_text)
        self.assertIn("Soft inpainting difference contrast: 2.5", inpaint_text)
        sketch_text = build_infotext(
            ForgeNeoRequest(
                mode="inpaint_sketch",
                prompt="repair sketch",
                mask_alpha=45,
            ),
            seed=44,
        )
        self.assertIn("Mask transparency: 45", sketch_text)

        batch_text = build_infotext(
            ForgeNeoRequest(
                mode="batch",
                prompt="batch repair",
                batch_files=["a.png", "b.png"],
                batch_source_type="upload",
                batch_use_png_info=True,
            ),
            seed=43,
        )
        self.assertIn("Mode: batch", batch_text)
        self.assertIn("Batch files: 2", batch_text)
        self.assertIn("Batch PNG info: True", batch_text)

