    def test_extras_runtime_resize_contract(self):
        from PIL import Image
        from forge_neo import runtime
        from forge_neo.runtime import ForgeNeoExtrasRequest, _directory_images, _image_from_value, run_extras
        from forge_neo.ui import _extras_clicked, _extras_skip_clicked, _extras_status_html, _extras_status_update, _extras_stop_clicked

        with tempfile.TemporaryDirectory() as tmp:
            result = run_extras(
                ForgeNeoExtrasRequest(
                    mode="single",
                    image=Image.new("RGB", (20, 10), "white"),
                    resize_mode="Scale by",
                    resize_scale=2.0,
                    upscaler_1="Nearest",
                    output_dir=tmp,
                )
            )
            self.assertEqual(result.status, "finished")
            self.assertEqual(result.images[0].size, (40, 20))
            self.assertIn("Extras mode: single", result.infotext)
            self.assertIn("Upscaler 1: Nearest", result.infotext)
            self.assertEqual(len(result.output_paths), 1)
            self.assertTrue(os.path.exists(result.output_paths[0]))
            source_calls = []
            old_source_upscale = runtime._run_source_backend_upscale

            def fake_source_upscale(image, request, progress_callback, control_callback):
                source_calls.append(
                    {
                        "size": image.size,
                        "upscaler_1": request.upscaler_1,
                        "upscaler_2": request.upscaler_2,
                        "visibility": request.upscaler_2_visibility,
                    }
                )
                return runtime.ForgeNeoResult(
                    images=[Image.new("RGB", (88, 44), "black")],
                    status="finished",
                    infotext="fake source upscaler",
                )

            try:
                runtime._run_source_backend_upscale = fake_source_upscale
                model_result = run_extras(
                    ForgeNeoExtrasRequest(
                        mode="single",
                        image=Image.new("RGB", (22, 11), "white"),
                        resize_mode="Scale by",
                        resize_scale=2.0,
                        upscaler_1="4x-UltraSharp",
                        output_dir=tmp,
                    )
                )
            finally:
                runtime._run_source_backend_upscale = old_source_upscale

            self.assertEqual(model_result.status, "finished")
            self.assertEqual(model_result.images[0].size, (88, 44))
            self.assertEqual(source_calls, [{"size": (22, 11), "upscaler_1": "4x-UltraSharp", "upscaler_2": "None", "visibility": 0.0}])
            self.assertIn("Upscaler 1: 4x-UltraSharp", model_result.infotext)
            input_dir = Path(tmp) / "extras-input"
            input_dir.mkdir()
            Image.new("RGB", (13, 7), "red").save(input_dir / "MOR08145-抠图.png")
            Image.new("RGB", (9, 5), "blue").save(input_dir / "QQ图片20250817174155.jpg")
            directory_items = _directory_images(str(input_dir))
            self.assertEqual(len(directory_items), 2)
            self.assertIsNotNone(_image_from_value(directory_items[0]))
            directory_output_dir = Path(tmp) / "extras-directory-output"
            directory_first_progress_files: list[list[Path]] = []

            def directory_progress(event):
                if event.get("message") == "extras 1":
                    directory_first_progress_files.append(sorted(directory_output_dir.glob("*.png")))

            directory_result = run_extras(
                ForgeNeoExtrasRequest(
                    mode="directory",
                    input_dir=str(input_dir),
                    output_dir=str(directory_output_dir),
                    show_results=True,
                    resize_mode="Scale by",
                    resize_scale=1.0,
                    upscaler_1="Nearest",
                ),
                progress_callback=directory_progress,
            )
            self.assertEqual(directory_result.status, "finished")
            self.assertEqual(len(directory_result.images), 2)
            self.assertEqual(len(directory_result.output_paths), 2)
            self.assertTrue(all(Path(path).exists() for path in directory_result.output_paths))
            self.assertEqual(len(directory_first_progress_files), 1)
            self.assertEqual(len(directory_first_progress_files[0]), 1)
            self.assertEqual(Path(directory_result.output_paths[0]), directory_first_progress_files[0][0])
            self.assertIn("Extras mode: directory", directory_result.infotext)
            self.assertNotIn("No input image found", directory_result.error)
            batch_output_dir = Path(tmp) / "extras-batch-output"
            batch_first_progress_files: list[list[Path]] = []

            def batch_progress(event):
                if event.get("message") == "extras 1":
                    batch_first_progress_files.append(sorted(batch_output_dir.glob("*.png")))

            batch_result = run_extras(
                ForgeNeoExtrasRequest(
                    mode="batch",
                    batch_files=[input_dir / "MOR08145-抠图.png", input_dir / "QQ图片20250817174155.jpg"],
                    output_dir=str(batch_output_dir),
                    show_results=True,
                    resize_mode="Scale by",
                    resize_scale=1.0,
                    upscaler_1="Nearest",
                ),
                progress_callback=batch_progress,
            )
            self.assertEqual(batch_result.status, "finished")
            self.assertEqual(len(batch_result.images), 2)
            self.assertEqual(len(batch_result.output_paths), 2)
            self.assertEqual(len(batch_first_progress_files), 1)
            self.assertEqual(len(batch_first_progress_files[0]), 1)
            self.assertEqual(Path(batch_result.output_paths[0]), batch_first_progress_files[0][0])
            from forge_neo.worker import ForgeNeoWorker

            source_batch_output_dir = Path(tmp) / "extras-source-batch-output"
            source_batch_calls: list[tuple[int, int]] = []
            first_source_finish_snapshot: dict[str, object] = {}
            old_source_upscale = runtime._run_source_backend_upscale
            source_worker = ForgeNeoWorker()

            def fake_source_batch_upscale(image, request, progress_callback, control_callback):
                source_batch_calls.append(image.size)
                if progress_callback is not None:
                    progress_callback(
                        {
                            "event": "progress",
                            "progress": 0.5,
                            "message": "tile upscale",
                            "message_en": "tile upscale",
                            "message_cn": "分块放大",
                            "sampling_step": 72,
                            "sampling_steps": 144,
                        }
                    )
                    progress_callback(
                        {
                            "event": "finish",
                            "progress": 1.0,
                            "message": "Source backend upscaler finished",
                            "message_en": "Source backend upscaler finished",
                            "message_cn": "源后端放大器完成",
                            "sampling_step": 144,
                            "sampling_steps": 144,
                        }
                    )
                if len(source_batch_calls) == 1:
                    first_source_finish_snapshot.update(source_worker.snapshot())
                return runtime.ForgeNeoResult(
                    images=[Image.new("RGB", (max(1, image.width * 2), max(1, image.height * 2)), "green")],
                    status="finished",
                    infotext="fake source batch upscaler",
                )

            try:
                runtime._run_source_backend_upscale = fake_source_batch_upscale
                source_batch_result = source_worker.run_extras(
                    ForgeNeoExtrasRequest(
                        mode="batch",
                        batch_files=[input_dir / "MOR08145-抠图.png", input_dir / "QQ图片20250817174155.jpg"],
                        output_dir=str(source_batch_output_dir),
                        show_results=True,
                        resize_mode="Scale by",
                        resize_scale=2.0,
                        upscaler_1="4x-UltraSharp",
                    )
                )
            finally:
                runtime._run_source_backend_upscale = old_source_upscale

            self.assertEqual(source_batch_result.status, "finished")
            self.assertEqual(source_batch_calls, [(13, 7), (9, 5)])
            self.assertEqual(first_source_finish_snapshot["status"], "running")
            self.assertLess(first_source_finish_snapshot["progress"], 1.0)
            source_events = source_worker.snapshot()["events"]
            source_finish_events = [event for event in source_events if event.get("event") == "finish"]
            self.assertEqual(len(source_finish_events), 1)
            self.assertEqual(source_finish_events[0]["message"], "finished")
            mapped_first_finish = [
                event
                for event in source_events
                if event.get("message_en") == "Extras item 1/2: Source backend upscaler finished"
            ]
            self.assertEqual(len(mapped_first_finish), 1)
            self.assertEqual(mapped_first_finish[0]["event"], "progress")
            self.assertEqual(mapped_first_finish[0]["progress"], 0.5)
            if importlib.util.find_spec("av") is None:
                self.skipTest("PyAV is not available")
            import av

            source_video = Path(tmp) / "clip.mp4"
            input_container = av.open(str(source_video), mode="w")
            input_stream = input_container.add_stream("mpeg4", rate=8)
            input_stream.width = 20
            input_stream.height = 10
            input_stream.pix_fmt = "yuv420p"
            for color in ("red", "blue"):
                frame = av.VideoFrame.from_image(Image.new("RGB", (20, 10), color))
                for packet in input_stream.encode(frame):
                    input_container.mux(packet)
            for packet in input_stream.encode():
                input_container.mux(packet)
            input_container.close()

            video_result = run_extras(
                ForgeNeoExtrasRequest(
                    mode="video",
                    video_path=str(source_video),
                    output_dir=tmp,
                    resize_mode="Scale by",
                    resize_scale=2.0,
                    upscaler_1="Nearest",
                )
            )
            self.assertEqual(video_result.status, "finished")
            self.assertEqual(len(video_result.images), 1)
            self.assertEqual(video_result.images[0].size, (40, 20))
            self.assertEqual(len(video_result.output_paths), 2)
            self.assertTrue(os.path.exists(video_result.output_paths[0]))
            self.assertTrue(video_result.output_paths[0].endswith(".mp4"))
            self.assertTrue(os.path.exists(video_result.output_paths[1]))
            with av.open(video_result.output_paths[0]) as output_container:
                self.assertEqual(sum(1 for _ in output_container.decode(video=0)), 2)
            with open(video_result.output_paths[1], "r", encoding="utf-8") as f:
                video_manifest = json.load(f)
            self.assertEqual(video_manifest["type"], "extras_video")
            self.assertEqual(video_manifest["frames"], 2)
            self.assertEqual(video_manifest["size"], [40, 20])
            self.assertIn("Extras mode: video", video_result.infotext)
            self.assertIn(str(source_video), video_result.infotext)
            self.assertEqual(video_result.error, "")
            missing_video = run_extras(
                ForgeNeoExtrasRequest(
                    mode="video",
                    video_path=str(Path(tmp) / "missing.mp4"),
                    output_dir=tmp,
                )
            )
            self.assertEqual(missing_video.status, "error")
            self.assertEqual(missing_video.output_paths, [])
            self.assertIn("No input video found", missing_video.error)
            status_html = _extras_status_html(f"Saved:\n{result.output_paths[0]}")
            self.assertIn("forge-neo-extras-status", status_html)
            self.assertIn("Saved:", status_html)
            self.assertIn("<br>", status_html)
            status_update = _extras_status_update(f"Saved:\n{result.output_paths[0]}")
            self.assertTrue(status_update["visible"])
            self.assertIn("forge-neo-extras-status", status_update["value"])
            clicked_gallery_update, clicked_info, clicked_status, clicked_output_folder = _extras_clicked(
                {"__lang": "en"},
                "single",
                Image.new("RGB", (12, 8), "white"),
                [],
                "",
                tmp,
                True,
                "Scale by",
                1.0,
                0,
                1024,
                1024,
                True,
                "Nearest",
                "None",
                0,
                False,
                0,
                0,
                0.5,
            )
            self.assertTrue(clicked_gallery_update["visible"])
            self.assertEqual(len(clicked_gallery_update["value"]), 1)
            self.assertIn("forge-neo-infotext", clicked_info)
            self.assertIn("Extras mode: single", clicked_info)
            self.assertTrue(clicked_status["visible"])
            self.assertIn("forge-neo-extras-status", clicked_status["value"])
            self.assertIn("Finished.", clicked_status["value"])
            self.assertEqual(Path(clicked_output_folder), Path(tmp))
            video_clicked_gallery_update, video_clicked_info, video_clicked_status, video_clicked_output_folder = _extras_clicked(
                {"__lang": "cn"},
                "video",
                None,
                [],
                "",
                tmp,
                True,
                "Scale by",
                1.0,
                0,
                1024,
                1024,
                True,
                "Nearest",
                "None",
                0,
                False,
                0,
                0,
                0.5,
                str(source_video),
            )
            self.assertTrue(video_clicked_gallery_update["visible"])
            self.assertEqual(len(video_clicked_gallery_update["value"]), 1)
            self.assertIn("Extras mode: video", video_clicked_info)
            self.assertIn(str(source_video), video_clicked_info)
            self.assertTrue(video_clicked_status["visible"])
            self.assertIn("已完成", video_clicked_status["value"])
