    def test_output_panel_save_contract(self):
        from PIL import Image
        from forge_neo.bootstrap import ensure_config
        from forge_neo.runtime import (
            SAVE_LOG_FIELDS,
            ForgeNeoRequest,
            build_infotext,
            first_gallery_image,
            gallery_image_at,
            outputs_dir,
            save_output_images,
            saved_log_path,
        )

        config = ensure_config(test_stub=True)
        old_userhome = getattr(config, "path_userhome", "")
        with tempfile.TemporaryDirectory() as tmp:
            config.path_userhome = tmp
            self.assertEqual(outputs_dir(), Path(tmp) / "ForgeNeo")
            self.assertFalse((Path(tmp) / "outputs" / "ForgeNeo").exists())
            generated_infotext = build_infotext(
                ForgeNeoRequest(prompt="browser save prompt", negative_prompt="blurred", checkpoint="placeholder.gguf"),
                123,
            )
            self.assertIn("Negative prompt: blurred\nSteps: 8", generated_infotext)
            image = Image.new("RGB", (16, 12), "white")
            infotext = (
                "cat in neon light\n"
                "Negative prompt: blurry\n"
                "Steps: 8, Sampler: Euler, Schedule type: Beta, CFG scale: 1.5, Seed: 42, "
                "Size: 16x12, Model: forge-test, Model hash: abc123"
            )
            paths = save_output_images([image], infotext, make_zip=True)
            self.assertEqual(len(paths), 2)
            self.assertTrue(paths[0].endswith(".zip"))
            self.assertTrue(paths[1].endswith(".png"))
            self.assertEqual(Path(paths[0]).parent, Path(tmp) / "ForgeNeo" / "saved")
            self.assertEqual(Path(paths[1]).parent, Path(tmp) / "ForgeNeo" / "saved")
            self.assertTrue(os.path.exists(paths[0]))
            self.assertTrue(os.path.exists(paths[1]))
            self.assertIn("parameters", Image.open(paths[1]).info)
            self.assertTrue(os.path.exists(saved_log_path()))
            with open(saved_log_path(), "r", encoding="utf-8", newline="") as f:
                rows = list(csv.reader(f))
            self.assertEqual(rows[0], SAVE_LOG_FIELDS)
            self.assertEqual(rows[1][0], "cat in neon light")
            self.assertEqual(rows[1][1], "42")
            self.assertEqual(rows[1][2], "16")
            self.assertEqual(rows[1][3], "12")
            self.assertEqual(rows[1][4], "Euler")
            self.assertEqual(rows[1][5], "1.5")
            self.assertEqual(rows[1][7], Path(paths[1]).name)
            self.assertEqual(rows[1][8], "blurry")
            self.assertEqual(rows[1][9], "forge-test")
            self.assertEqual(rows[1][10], "abc123")
            os.remove(saved_log_path())
            from forge_neo import settings

            settings.save_settings({"save_write_log_csv": False})
            disabled_paths = save_output_images([image], infotext)
            self.assertEqual(len(disabled_paths), 1)
            self.assertFalse(os.path.exists(saved_log_path()))
            custom_dir = Path(tmp) / "custom_outputs"
            settings.save_settings(
                {
                    "enable_pnginfo": False,
                    "save_txt": True,
                    "samples_format": "webp",
                    "output_dir": str(custom_dir),
                    "save_write_log_csv": False,
                }
            )
            custom_paths = save_output_images([image], infotext, make_zip=True)
            self.assertTrue(custom_paths[0].endswith(".zip"))
            self.assertEqual(Path(custom_paths[1]).suffix.lower(), ".webp")
            self.assertEqual(Path(custom_paths[1]).parent, custom_dir / "saved")
            self.assertTrue(Path(custom_paths[2]).name.endswith(".txt"))
            self.assertEqual(Path(custom_paths[2]).read_text(encoding="utf-8").strip(), infotext)
            self.assertFalse((custom_dir / "saved" / "log.csv").exists())
            self.assertNotIn("parameters", Image.open(custom_paths[1]).info)
            settings.save_settings({"samples_format": "webp", "enable_pnginfo": True, "save_txt": False, "output_dir": ""})
            webp_paths = save_output_images([image], infotext)
            self.assertEqual(Path(webp_paths[0]).suffix.lower(), ".webp")
            self.assertIn("cat in neon light", _exif_user_comment(webp_paths[0]))
            settings.save_settings({"samples_format": "jpg", "enable_pnginfo": True, "save_txt": False, "output_dir": ""})
            jpg_paths = save_output_images([image], infotext)
            self.assertEqual(Path(jpg_paths[0]).suffix.lower(), ".jpg")
            self.assertIn("cat in neon light", _exif_user_comment(jpg_paths[0]))
            pattern_dir = Path(tmp) / "pattern_outputs"
            settings.save_settings(
                {
                    "samples_filename_pattern": "neo-[seed]-[prompt]-[model_hash]",
                    "grid_zip_filename_pattern": "zip-[seed]-[model_hash]",
                    "output_dir": str(pattern_dir),
                    "save_write_log_csv": False,
                }
            )
            pattern_paths = save_output_images([image], infotext, make_zip=True)
            self.assertTrue(Path(pattern_paths[0]).name.startswith("zip-42-abc123"))
            self.assertTrue(Path(pattern_paths[1]).name.startswith("neo-42-cat_in_neon_light-abc123"))
            self.assertEqual(Path(pattern_paths[1]).parent, pattern_dir / "saved")
            settings.save_settings({"save_write_log_csv": True})
            self.assertEqual(first_gallery_image([(image, None)]).size, (16, 12))

            red = Image.new("RGB", (4, 4), "red")
            blue = Image.new("RGB", (4, 4), "blue")
            self.assertEqual(gallery_image_at([red, blue], 1).getpixel((0, 0))[:3], (0, 0, 255))
            settings.save_settings({"save_selected_only": True})
            selected_paths = save_output_images([red, blue], "Steps: 9", selected_index=1)
            self.assertEqual(len(selected_paths), 1)
            self.assertEqual(Image.open(selected_paths[0]).convert("RGB").getpixel((0, 0)), (0, 0, 255))
            settings.save_settings({"save_selected_only": False})
            all_paths = save_output_images([red, blue], "Steps: 9", selected_index=1)
            self.assertEqual(len(all_paths), 2)
            self.assertEqual(Image.open(all_paths[0]).convert("RGB").getpixel((0, 0)), (255, 0, 0))
            self.assertEqual(Image.open(all_paths[1]).convert("RGB").getpixel((0, 0)), (0, 0, 255))
        config.path_userhome = old_userhome

    def test_png_info_parse_contract(self):
        from PIL import Image
        from forge_neo.png_info import parse_generation_parameters, png_info_html, read_png_info

        text = (
            "a neon sign on a brick wall\n"
            "Negative prompt: blurry, low quality\n"
            "Steps: 8, Sampler: Euler, Schedule type: Beta, CFG scale: 1, Seed: 123, Size: 1152x896, "
            "Model: flux-test.safetensors, Model hash: abc123, VAE: flux-vae.safetensors, "
            "Denoising strength: 0.55, Script: Prompt Matrix"
        )
        parsed = parse_generation_parameters(text)
        self.assertEqual(parsed["prompt"], "a neon sign on a brick wall")
        self.assertEqual(parsed["negative_prompt"], "blurry, low quality")
        self.assertEqual(parsed["steps"], 8)
        self.assertEqual(parsed["sampler"], "Euler")
        self.assertEqual(parsed["scheduler"], "Beta")
        self.assertEqual(parsed["cfg_scale"], 1.0)
        self.assertEqual(parsed["seed"], 123)
        self.assertEqual(parsed["width"], 1152)
        self.assertEqual(parsed["height"], 896)
        self.assertEqual(parsed["model_hash"], "abc123")
        self.assertEqual(parsed["denoising_strength"], 0.55)
        self.assertEqual(parsed["script"], "Prompt Matrix")

        image = Image.new("RGB", (8, 8), "white")
        image.info["parameters"] = text
        image.info["loop"] = 1
        image.info["background"] = (255, 255, 255, 255)
        image.info["icc_profile"] = b"profile"
        self.assertIn("Steps: 8", read_png_info(image))
        html = png_info_html(image)
        self.assertIn("forge-neo-pnginfo-item", html)
        self.assertIn("<p><b>parameters</b></p>", html)
        self.assertIn("<p>a neon sign on a brick wall", html)
        self.assertNotIn("<h4>parameters</h4>", html)
        self.assertNotIn("<pre>", html)
        self.assertNotIn("<h4>loop</h4>", html)
        self.assertNotIn("<h4>background</h4>", html)
        self.assertNotIn("profile", html)

        plain_metadata_image = Image.new("RGB", (8, 8), "white")
        plain_metadata_image.info["Software"] = "Forge Neo Test"
        plain_metadata_html = png_info_html(plain_metadata_image)
        self.assertIn("<p><b>parameters</b></p>", plain_metadata_html)
        self.assertIn("<p><b>Software</b></p>", plain_metadata_html)

        from forge_neo.ui import (
            SCRIPT_SEND_FIELD_COUNT,
            _png_status_html,
            _png_status_update,
            _read_png_clicked,
            _send_png_image_to_img2img,
            _send_png_image_to_inpaint,
            _send_png_to_extras,
            _send_png_to_txt2img,
        )

        status_html = _png_status_html("Ready <ok>")
        self.assertIn("forge-neo-pnginfo-status", status_html)
        self.assertIn("Ready &lt;ok&gt;", status_html)
        status_update = _png_status_update("Ready <ok>")
        self.assertTrue(status_update["visible"])
        self.assertIn("Ready &lt;ok&gt;", status_update["value"])
        empty_png_text, empty_png_html_update, empty_png_status_update = _read_png_clicked(None, {"__lang": "cn"})
        self.assertIn("放入图片后读取元数据", empty_png_text)
        self.assertFalse(empty_png_html_update["visible"])
        self.assertFalse(empty_png_status_update["visible"])
        loaded_png_text, loaded_png_html_update, loaded_png_status_update = _read_png_clicked(image, {"__lang": "cn"})
        self.assertIn("Steps: 8", loaded_png_text)
        self.assertTrue(loaded_png_html_update["visible"])
        self.assertIn("forge-neo-pnginfo-item", loaded_png_html_update["value"])
        self.assertTrue(loaded_png_status_update["visible"])
        self.assertIn("PNG Info 已读取", loaded_png_status_update["value"])
        send_updates = _send_png_to_txt2img(text, {"__lang": "en"})
        self.assertEqual(len(send_updates), 1 + 9 + SCRIPT_SEND_FIELD_COUNT + 1)
        self.assertTrue(send_updates[0]["visible"])
        self.assertIn("forge-neo-pnginfo-status", send_updates[0]["value"])
        self.assertIn("Parameters sent.", send_updates[0]["value"])
        self.assertEqual(send_updates[10]["value"], "Prompt Matrix")
        empty_send_updates = _send_png_to_txt2img("", {"__lang": "cn"})
        self.assertEqual(len(empty_send_updates), 1 + 9 + SCRIPT_SEND_FIELD_COUNT + 1)
        self.assertTrue(empty_send_updates[0]["visible"])
        self.assertIn("没有找到可回填的生成参数", empty_send_updates[0]["value"])
        img_send_updates = _send_png_image_to_img2img(text, image, {"__lang": "cn"})
        self.assertEqual(len(img_send_updates), 2 + 9 + SCRIPT_SEND_FIELD_COUNT + 2)
        self.assertIn("图片和参数已发送", img_send_updates[0]["value"])
        self.assertIs(img_send_updates[1]["value"], image)
        self.assertEqual(img_send_updates[11]["value"], "Prompt Matrix")
        self.assertEqual(img_send_updates[-2]["value"], 0.55)
        self.assertNotIn("value", img_send_updates[-1])
        inpaint_send_updates = _send_png_image_to_inpaint(text, image, {"__lang": "en"})
        self.assertEqual(len(inpaint_send_updates), 2 + 9 + SCRIPT_SEND_FIELD_COUNT + 3)
        self.assertIn("Image and parameters sent.", inpaint_send_updates[0]["value"])
        self.assertIs(inpaint_send_updates[1]["value"], image)
        self.assertEqual(inpaint_send_updates[11]["value"], "Prompt Matrix")
        self.assertEqual(inpaint_send_updates[-3]["value"], 0.55)
        self.assertNotIn("value", inpaint_send_updates[-2])
        self.assertEqual(inpaint_send_updates[-1], "inpaint")
        empty_image_send_updates = _send_png_image_to_img2img("", None, {"__lang": "cn"})
        self.assertEqual(len(empty_image_send_updates), 2 + 9 + SCRIPT_SEND_FIELD_COUNT + 2)
        self.assertIn("没有找到可发送的图片或生成参数", empty_image_send_updates[0]["value"])
        _, extras_message = _send_png_to_extras(None, {"__lang": "cn"})
        self.assertTrue(extras_message["visible"])
        self.assertIn("没有可发送的图片", extras_message["value"])

        exif_bytes = piexif.dump(
            {
                "Exif": {
                    piexif.ExifIFD.UserComment: piexif.helper.UserComment.dump(text, encoding="unicode")
                }
            }
        )
        with tempfile.TemporaryDirectory() as tmp:
            for fmt, suffix in (("JPEG", ".jpg"), ("WEBP", ".webp")):
                path = Path(tmp) / f"metadata{suffix}"
                Image.new("RGB", (8, 8), "white").save(path, format=fmt)
                piexif.insert(exif_bytes, str(path))
                with Image.open(path) as exif_image:
                    self.assertIn("Steps: 8", read_png_info(exif_image))
                    html = png_info_html(exif_image)
                self.assertIn("parameters", html)
                self.assertIn("a neon sign on a brick wall", html)
                self.assertNotIn("UserComment", html)
                self.assertNotIn("<h4>loop</h4>", html)
                self.assertNotIn("<h4>background</h4>", html)

    def test_toprow_prompt_tools_contract(self):
        js_content = Path(ROOT, "javascript", "forge_neo.js").read_text(encoding="utf-8")
        migration_plan = Path(ROOT, "docs", "forge-neo-gradio6-migration-plan.md").read_text(encoding="utf-8")
        from forge_neo.ui import (
            SCRIPT_SEND_FIELD_COUNT,
            _clear_prompts_clicked,
            _paste_img2img_params_clicked,
            _paste_parameter_source,
            _paste_txt2img_params_clicked,
            _prompt_history_path,
            _read_prompt_history,
            _write_prompt_history,
        )

        def value_of(update):
            if isinstance(update, dict):
                return update.get("value")
            return getattr(update, "value", None)

        text = (
            "a neon sign on a brick wall\n"
            "Negative prompt: blurry\n"
            "Steps: 12, Sampler: Euler, Schedule type: Beta, CFG scale: 3.5, Seed: 1234, "
            "Size: 640x512, Denoising strength: 0.42, Script: X/Y/Z plot"
        )
        txt_result = _paste_txt2img_params_clicked(text, "ignored", {"__lang": "en"})
        self.assertTrue(txt_result[0]["visible"])
        self.assertIn("forge-neo-output-status", txt_result[0]["value"])
        self.assertIn("Parameters sent.", txt_result[0]["value"])
        self.assertEqual(value_of(txt_result[1]), "a neon sign on a brick wall")
        self.assertEqual(value_of(txt_result[2]), "blurry")
        self.assertEqual(value_of(txt_result[5]), 12)
        self.assertEqual(value_of(txt_result[6]), 640)
        self.assertEqual(value_of(txt_result[7]), 512)
        self.assertEqual(value_of(txt_result[8]), 3.5)
        self.assertEqual(value_of(txt_result[9]), 1234)
        self.assertEqual(value_of(txt_result[10]), "X/Y/Z plot")
        self.assertEqual(len(txt_result), 1 + 9 + SCRIPT_SEND_FIELD_COUNT + 1)

        self.assertEqual(_paste_parameter_source("ordinary prompt", text), "ordinary prompt")
        old_data_root = os.environ.get("FORGE_NEO_SOURCE_BACKEND_DATA_DIR")
        try:
            with tempfile.TemporaryDirectory() as tempdir:
                os.environ["FORGE_NEO_SOURCE_BACKEND_DATA_DIR"] = tempdir
                self.assertEqual(_prompt_history_path(), Path(tempdir) / "params.txt")
                self.assertEqual(_read_prompt_history(), "")
                _write_prompt_history(text)
                self.assertEqual(_read_prompt_history(), text)
                fallback_result = _paste_txt2img_params_clicked("", "ignored page state", {"__lang": "cn"})
                self.assertTrue(fallback_result[0]["visible"])
                self.assertIn("参数已发送", fallback_result[0]["value"])
                self.assertEqual(value_of(fallback_result[1]), "a neon sign on a brick wall")

                _prompt_history_path().unlink()
                memory_fallback = _paste_txt2img_params_clicked("", text, {"__lang": "cn"})
                self.assertIn("参数已发送", memory_fallback[0]["value"])
        finally:
            if old_data_root is None:
                os.environ.pop("FORGE_NEO_SOURCE_BACKEND_DATA_DIR", None)
            else:
                os.environ["FORGE_NEO_SOURCE_BACKEND_DATA_DIR"] = old_data_root

        self.assertIn(
            '["#forge_neo_paste_params", "Read generation parameters from prompt or last generated image", "从提示词或上次生成的图片中读取生成参数"]',
            js_content,
        )
        self.assertIn(
            '["#forge_neo_img2img_paste_params", "Read generation parameters from prompt or last generated image", "从提示词或上次生成的图片中读取生成参数"]',
            js_content,
        )
        self.assertIn("## 810. 2026-07-25 Forge Neo generation parameter history parity", migration_plan)

        img_result = _paste_img2img_params_clicked("", text, {"__lang": "en"})
        self.assertEqual(value_of(img_result[10]), "X/Y/Z plot")
        self.assertEqual(value_of(img_result[-2]), 0.42)
        self.assertNotIn("value", img_result[-1])

        xyz_text = (
            "xyz dropdown\n"
            "Negative prompt: blurry\n"
            "Steps: 12, Sampler: Euler, Schedule type: Beta, CFG scale: 3.5, Seed: 1234, "
            "Size: 640x512, Denoising strength: 0.42, Script: X/Y/Z plot, X type: Seed, X values: 1, 2, "
            "Y type: Sampler, Y values: Euler, LCM, Z type: Nothing, Z values: , Row Count: 0, Grid Margins: 4, "
            "Draw legend: True, Include Sub Images: True, Use text inputs instead of dropdowns: False"
        )

        xyz_result = _paste_txt2img_params_clicked(xyz_text, "", {"__lang": "en"})
        self.assertEqual(value_of(xyz_result[10]), "X/Y/Z plot")
        self.assertTrue(xyz_result[13]["visible"])
        self.assertEqual(value_of(xyz_result[25]), "Seed")
        self.assertEqual(value_of(xyz_result[26]), "1, 2")
        self.assertEqual(value_of(xyz_result[29]), "Sampler")
        self.assertFalse(xyz_result[30]["visible"])
        self.assertEqual(xyz_result[31]["value"], ["Euler", "LCM"])
        self.assertTrue(xyz_result[32]["visible"])
        self.assertEqual(value_of(xyz_result[38]), 4)
        self.assertTrue(value_of(xyz_result[44]))

        clear_result = _clear_prompts_clicked({"__lang": "cn"})
        self.assertEqual(clear_result[0], "")
        self.assertEqual(clear_result[1], "")
        self.assertTrue(clear_result[2]["visible"])
        self.assertIn("forge-neo-output-status", clear_result[2]["value"])
        self.assertIn("提示词已清空", clear_result[2]["value"])

    def test_finished_generation_persists_prompt_history(self):
        from forge_neo import ui

        infotext = (
            "history prompt\n"
            "Negative prompt: blur\n"
            "Steps: 8, Sampler: Euler, CFG scale: 4, Seed: 42, Size: 512x512"
        )
        old_data_root = os.environ.get("FORGE_NEO_SOURCE_BACKEND_DATA_DIR")
        old_build_request = ui._build_request
        old_worker = ui.worker
        try:
            with tempfile.TemporaryDirectory() as tempdir:
                os.environ["FORGE_NEO_SOURCE_BACKEND_DATA_DIR"] = tempdir
                ui._build_request = lambda *_values: object()
                ui.worker = types.SimpleNamespace(
                    run=lambda _request, _state: types.SimpleNamespace(
                        status="finished",
                        infotext=infotext,
                        error="",
                        output_paths=[],
                        images=[],
                    )
                )

                ui._generate_clicked({"__lang": "cn"})

                self.assertEqual((Path(tempdir) / "params.txt").read_text(encoding="utf-8"), infotext)
        finally:
            ui._build_request = old_build_request
            ui.worker = old_worker
            if old_data_root is None:
                os.environ.pop("FORGE_NEO_SOURCE_BACKEND_DATA_DIR", None)
            else:
                os.environ["FORGE_NEO_SOURCE_BACKEND_DATA_DIR"] = old_data_root

