            self.assertIsInstance(i18n_config.get("languages"), list)
            self.assertTrue(any(item.get("code") == i18n_config.get("default") for item in i18n_config["languages"]))
            self.assertIsInstance(translate_config.get("apis"), list)
            self.assertTrue(translate_config.get("default"))
            translate_module_name = "scripts.physton_prompt.translate"
            old_translate_module = sys.modules.get(translate_module_name)
            calls = []
            fake_translate_module = types.ModuleType(translate_module_name)

            def fake_translate(text, from_lang, to_lang, api, api_config):
                calls.append((text, from_lang, to_lang, api, api_config))
                return {
                    "success": True,
                    "translated_text": ["中文一", "中文二"] if isinstance(text, list) else "中文",
                    "from_lang": from_lang,
                    "to_lang": to_lang,
                    "api": api,
                }

            fake_translate_module.translate = fake_translate
            sys.modules[translate_module_name] = fake_translate_module
            try:
                single_result = _physton_translate_payload(
                    {
                        "text": "hello",
                        "from_lang": "en_US",
                        "to_lang": "zh_CN",
                        "api": "alibaba_free",
                        "api_config": {"region": "CN"},
                    }
                )
                batch_result = _physton_translate_payload(
                    {
                        "texts": ["hello", "world"],
                        "from_lang": "en_US",
                        "to_lang": "zh_CN",
                        "api": "alibaba_free",
                        "api_config": {},
                    },
                    batch=True,
                )
            finally:
                if old_translate_module is None:
                    sys.modules.pop(translate_module_name, None)
                else:
                    sys.modules[translate_module_name] = old_translate_module
            self.assertEqual(single_result["translated_text"], "中文")
            self.assertEqual(batch_result["translated_text"], ["中文一", "中文二"])
            self.assertEqual(calls[0], ("hello", "en_US", "zh_CN", "alibaba_free", {"region": "CN"}))
            self.assertEqual(calls[1], (["hello", "world"], "en_US", "zh_CN", "alibaba_free", {}))

