    def test_forge_styles_use_bundled_csv_not_fooocus_catalog(self):
        styles_path = os.path.join(ROOT, "forge_neo", "styles.py")
        with open(styles_path, "r", encoding="utf-8") as f:
            styles_source = f.read()
        self.assertNotIn("sdxl_styles", styles_source)
        self.assertNotIn("fooocus", styles_source.lower())
        self.assertNotIn('ROOT / "style.csv"', styles_source)
        self.assertNotIn('row.get("text"', styles_source)
        self.assertIn('STYLE_CSV_FIELDS = ("name", "prompt", "negative_prompt")', styles_source)
        self.assertTrue(os.path.exists(os.path.join(ROOT, "html", "forge_neo", "styles.csv")))

        with open(os.path.join(ROOT, "html", "forge_neo", "styles.csv"), "r", encoding="utf-8-sig", newline="") as f:
            reader = csv.DictReader(f)
            self.assertEqual(tuple(reader.fieldnames or ()), ("name", "prompt", "negative_prompt"))

        from forge_neo import styles as forge_styles
        from forge_neo.styles import STYLE_CSV_FIELDS, _load_csv, get_style, style_choices

        self.assertEqual(STYLE_CSV_FIELDS, ("name", "prompt", "negative_prompt"))

        self.assertIn("基础起手式", style_choices())
        style = get_style("基础起手式")
        self.assertIsNotNone(style)
        self.assertIn("masterpiece", style.prompt)
        self.assertTrue(os.path.normpath(style.path).endswith(os.path.normpath("html/forge_neo/styles.csv")))

        with tempfile.TemporaryDirectory() as tempdir:
            legacy_path = os.path.join(tempdir, "styles.csv")
            with open(legacy_path, "w", encoding="utf-8", newline="") as f:
                f.write("name,text,negative_prompt\nLegacy,legacy prompt,\n")
            self.assertEqual(_load_csv(Path(legacy_path)), {})

        old_ensure_config = forge_styles.ensure_config
        try:
            with tempfile.TemporaryDirectory() as tempdir:
                user_dir = Path(tempdir) / "forge_neo"
                user_dir.mkdir(parents=True, exist_ok=True)
                with (user_dir / "styles.csv").open("w", encoding="utf-8-sig", newline="") as f:
                    writer = csv.DictWriter(f, fieldnames=list(STYLE_CSV_FIELDS))
                    writer.writeheader()
                    writer.writerow({"name": "用户自定义", "prompt": "user prompt", "negative_prompt": ""})
                    writer.writerow({"name": "基础起手式", "prompt": "user override prompt", "negative_prompt": "user negative"})

                class FakeConfig:
                    path_userhome = tempdir

                forge_styles.ensure_config = lambda: FakeConfig()
                ordered = forge_styles.style_choices()
                self.assertEqual(ordered[:2], ["用户自定义", "基础起手式"])
                self.assertEqual(forge_styles.get_style("基础起手式").prompt, "user override prompt")
                self.assertTrue(os.path.normpath(forge_styles.get_style("用户自定义").path).endswith(os.path.normpath("forge_neo/styles.csv")))
        finally:
            forge_styles.ensure_config = old_ensure_config

    def test_forge_styles_editor_new_style_and_refresh_contract(self):
        from forge_neo import ui as forge_ui
        from forge_neo.styles import PromptStyle
        from forge_neo.ui import _refresh_styles_clicked, _style_selected

        prompt, negative_prompt, delete_update, save_update = _style_selected("new temporary style")
        self.assertEqual(prompt, "")
        self.assertEqual(negative_prompt, "")
        self.assertFalse(delete_update["visible"])
        self.assertTrue(save_update["visible"])

        old_style_choices = forge_ui.style_choices
        old_get_style = forge_ui.get_style
        try:
            catalog = {
                "None": PromptStyle("None", "", ""),
                "Alpha": PromptStyle("Alpha", "alpha prompt", "alpha negative"),
                "Beta": PromptStyle("Beta", "beta prompt", "beta negative"),
            }
            forge_ui.style_choices = lambda: ["None", "Alpha", "Beta"]
            forge_ui.get_style = lambda name: catalog.get(str(name or ""))

            editor_update, edit_update, prompt, negative_prompt, delete_update, save_update = forge_ui._open_style_editor_clicked([])
            self.assertTrue(editor_update["visible"])
            self.assertEqual(edit_update["value"], "Alpha")
            self.assertEqual(prompt, "alpha prompt")
            self.assertEqual(negative_prompt, "alpha negative")
            self.assertTrue(delete_update["visible"])
            self.assertTrue(save_update["visible"])

            _, edit_update, prompt, negative_prompt, _, _ = forge_ui._open_style_editor_clicked(["Beta"])
            self.assertEqual(edit_update["value"], "Beta")
            self.assertEqual(prompt, "beta prompt")
            self.assertEqual(negative_prompt, "beta negative")

            prompt, negative_prompt, dropdown_value, editor_update = forge_ui._materialize_style_editor_clicked(
                "base prompt",
                "base negative",
                "editor prompt",
                "editor negative",
            )
            self.assertEqual(prompt, "base prompt, editor prompt")
            self.assertEqual(negative_prompt, "base negative, editor negative")
            self.assertEqual(dropdown_value, [])
            self.assertFalse(editor_update["visible"])
        finally:
            forge_ui.style_choices = old_style_choices
            forge_ui.get_style = old_get_style

        dropdown_update, edit_update, delete_update, save_update, status = _refresh_styles_clicked("new temporary style", {"__lang": "cn"})
        self.assertIn("choices", dropdown_update)
        self.assertIn("choices", edit_update)
        self.assertFalse(delete_update["visible"])
        self.assertTrue(save_update["visible"])
        self.assertTrue(status["visible"])
        self.assertIn("样式已刷新", status["value"])
        self.assertIn("forge-neo-output-status", status["value"])

    def test_forge_output_status_html_contract(self):
        from PIL import Image
        from forge_neo.ui import (
            _clear_prompts_clicked,
            _infotext_html,
            _localized_value_choices,
            _open_output_folder_clicked,
            _output_status_html,
            _output_status_update,
            _paste_txt2img_params_clicked,
            _send_output_to_extras,
            _send_output_to_upscale,
            _send_output_to_storyboard,
            _storyboard_add_blank_clicked,
            _storyboard_cell_annotation_changed,
            _storyboard_cell_audio_changed,
            _storyboard_cell_delete_clicked,
            _storyboard_cell_image_changed,
            _storyboard_character_next_clicked,
            _storyboard_character_panel_updates,
            _storyboard_character_prev_clicked,
            _storyboard_delete_character_clicked,
            _storyboard_delete_character_image_clicked,
            _storyboard_clear_clicked,
            _storyboard_delete_audio_clicked,
            _storyboard_delete_frame_clicked,
            _storyboard_delete_story_clicked,
            _storyboard_export_script_clicked,
            _storyboard_export_clicked,
            _storyboard_move_audio_clicked,
            _storyboard_move_frame_clicked,
            _storyboard_new_character_clicked,
            _storyboard_new_story_clicked,
            _storyboard_panel_updates,
            _storyboard_save_character_clicked,
            _storyboard_save_story_clicked,
            _storyboard_summary_html,
            _switch_dimensions_clicked,
            STORYBOARD_CHARACTER_OUTPUT_COUNT,
            STORYBOARD_PANEL_OUTPUT_COUNT,
        )

        self.assertEqual(_localized_value_choices([("Just resize", "仅缩放")]), [("仅缩放", "Just resize")])

        status_html = _output_status_html("Ready <ok>\nPath")
        self.assertIn("forge-neo-output-status", status_html)
        self.assertIn("Ready &lt;ok&gt;", status_html)
        self.assertIn("<br>", status_html)
        status_update = _output_status_update("Ready <ok>\nPath")
        self.assertTrue(status_update["visible"])
        self.assertIn("Ready &lt;ok&gt;", status_update["value"])

        infotext_html = _infotext_html("Steps: 8 <unsafe>")
        self.assertIn("forge-neo-infotext", infotext_html)
        self.assertIn("Steps: 8 &lt;unsafe&gt;", infotext_html)

        _, _, cleared = _clear_prompts_clicked({"__lang": "cn"})
        self.assertTrue(cleared["visible"])
        self.assertIn("forge-neo-output-status", cleared["value"])
        self.assertIn("提示词已清空", cleared["value"])

        width, height, switched = _switch_dimensions_clicked(512, 768, {"__lang": "en"})
        self.assertEqual((width, height), (768, 512))
        self.assertTrue(switched["visible"])
        self.assertIn("Width and height switched.", switched["value"])
        self.assertIn("forge-neo-output-status", switched["value"])

        pasted = _paste_txt2img_params_clicked("", "", {"__lang": "cn"})
        self.assertTrue(pasted[0]["visible"])
        self.assertIn("forge-neo-output-status", pasted[0]["value"])
        self.assertIn("没有找到可回填的生成参数", pasted[0]["value"])

        _, sent_status = _send_output_to_extras([], {"__lang": "cn"}, -1)
        self.assertTrue(sent_status["visible"])
        self.assertIn("forge-neo-output-status", sent_status["value"])
        self.assertIn("没有可发送的结果图片", sent_status["value"])

        upscale_image, upscale_mode, upscale_resize_mode, upscale_scale, upscale_status = _send_output_to_upscale(
            [Image.new("RGB", (4, 4), "white")],
            {"__lang": "cn"},
            0,
        )
        self.assertEqual(upscale_image["value"].size, (4, 4))
        self.assertEqual(upscale_mode, "single")
        self.assertEqual(upscale_resize_mode, "Scale by")
        self.assertEqual(upscale_scale["value"], 2.0)
        self.assertTrue(upscale_status["visible"])
        self.assertIn("预设为高清放大", upscale_status["value"])

        missing_upscale = _send_output_to_upscale([], {"__lang": "cn"}, -1)
        self.assertNotIn("value", missing_upscale[0])
        self.assertTrue(missing_upscale[-1]["visible"])
        self.assertIn("没有可发送的结果图片", missing_upscale[-1]["value"])

        from forge_neo import storyboard

        old_outputs_dir = storyboard.outputs_dir
        try:
            with tempfile.TemporaryDirectory() as tempdir:
                storyboard.outputs_dir = lambda settings=None: Path(tempdir)
                storyboard.save_story_scripts({"stories": {}})
                self.assertEqual(storyboard.story_script_choices(), [])

                new_story = _storyboard_new_story_clicked({"__lang": "cn"})
                self.assertIn("choices", new_story[0])
                self.assertEqual(new_story[1], "新故事")
                self.assertEqual(new_story[2]["value"], "奇幻")
                self.assertIn("已新建故事", new_story[5]["value"])
                new_story_key = new_story[0]["value"]

                saved_story = _storyboard_save_story_clicked(
                    {"__lang": "cn"},
                    new_story_key,
                    "迁移测试剧本",
                    "科幻",
                    "第一幕\n角色: 台词",
                )
                self.assertEqual(saved_story[0]["value"], "迁移测试剧本")
                self.assertEqual(saved_story[1], "迁移测试剧本")
                self.assertEqual(saved_story[2]["value"], "科幻")
                self.assertIn("第一幕", storyboard.load_story_script("迁移测试剧本")["script"])
                self.assertIn("已保存", saved_story[5]["value"])

                character_panel = _storyboard_character_panel_updates({"__lang": "cn"}, "迁移测试剧本", 1)
                self.assertEqual(len(character_panel), STORYBOARD_CHARACTER_OUTPUT_COUNT)
                self.assertEqual(character_panel[0]["choices"], [])
                character_draft = _storyboard_new_character_clicked({"__lang": "cn"})
                self.assertIn("姓名：", character_draft[1]["value"])
                saved_character = _storyboard_save_character_clicked(
                    {"__lang": "cn"},
                    "迁移测试剧本",
                    "",
                    "姓名：球球\n年龄：10\n性格：勇敢",
                    Image.new("RGB", (16, 12), "green"),
                    1,
                )
                self.assertEqual(len(saved_character), STORYBOARD_CHARACTER_OUTPUT_COUNT)
                self.assertEqual(saved_character[0]["value"], "球球")
                self.assertIn("球球", saved_character[0]["choices"])
                self.assertIn("勇敢", saved_character[1]["value"])
                self.assertTrue(Path(saved_character[2]["value"]).is_file())
                self.assertIn("已保存", saved_character[5]["value"])
                self.assertEqual(storyboard.story_character_choices("迁移测试剧本", 1)[0], ["球球"])
                loaded_character = storyboard.load_story_character("迁移测试剧本", "球球")
                self.assertEqual(loaded_character["name"], "球球")
                self.assertIn("勇敢", loaded_character["content"])
                self.assertTrue(Path(loaded_character["image_path"]).is_file())
                self.assertEqual(len(_storyboard_character_prev_clicked({"__lang": "cn"}, "迁移测试剧本", 1)), STORYBOARD_CHARACTER_OUTPUT_COUNT)
                self.assertEqual(len(_storyboard_character_next_clicked({"__lang": "cn"}, "迁移测试剧本", 1)), STORYBOARD_CHARACTER_OUTPUT_COUNT)

                script_exported = _storyboard_export_script_clicked({"__lang": "cn"}, "迁移测试剧本")
                self.assertTrue(Path(script_exported[0]).is_file())
                self.assertEqual(Path(script_exported[0]).suffix, ".zip")
                self.assertIn("剧本已导出", script_exported[1]["value"])
                with zipfile.ZipFile(script_exported[0]) as archive:
                    names = archive.namelist()
                    text_names = [name for name in names if name.endswith(".txt")]
                    self.assertTrue(text_names)
                    exported_text = archive.read(text_names[0]).decode("utf-8")
                    self.assertIn("【角色小传】", exported_text)
                    self.assertIn("球球", exported_text)
                    self.assertTrue(any(name.startswith("character_images/") and name.endswith(".jpg") for name in names))

                deleted_character_image = _storyboard_delete_character_image_clicked({"__lang": "cn"}, "迁移测试剧本", "球球", 1)
                self.assertIsNone(deleted_character_image[2]["value"])
                self.assertNotIn("image_path", storyboard.load_story_script("迁移测试剧本")["characters"]["球球"])
                deleted_character = _storyboard_delete_character_clicked({"__lang": "cn"}, "迁移测试剧本", "球球", 1)
                self.assertEqual(storyboard.story_character_choices("迁移测试剧本", 1)[0], [])
                self.assertEqual(deleted_character[0]["value"], "")
                self.assertIn("已删除角色", deleted_character[5]["value"])

                deleted_story = _storyboard_delete_story_clicked({"__lang": "cn"}, "迁移测试剧本")
                self.assertEqual(storyboard.story_script_choices(), [])
                self.assertEqual(deleted_story[1], "")
                self.assertIn("已删除故事", deleted_story[5]["value"])

                storyboard_missing = _send_output_to_storyboard([], {"__lang": "cn"}, -1)
                self.assertTrue(storyboard_missing[0]["visible"])
                self.assertIn("forge-neo-output-status", storyboard_missing[0]["value"])
                self.assertIn("没有可发送的结果图片", storyboard_missing[0]["value"])
                self.assertEqual(len(storyboard_missing), STORYBOARD_PANEL_OUTPUT_COUNT + 1)

                storyboard_ready = _send_output_to_storyboard([Image.new("RGB", (4, 4), "white")], {"__lang": "cn"}, 0)
                self.assertEqual(len(storyboard_ready), STORYBOARD_PANEL_OUTPUT_COUNT + 1)
                self.assertTrue(storyboard_ready[0]["visible"])
                self.assertIn("结果已发送到分镜 #1", storyboard_ready[0]["value"])
                self.assertFalse(storyboard_ready[1]["visible"])
                self.assertEqual(len(storyboard_ready[1]["value"]), 1)
                self.assertIn("storyboard_", storyboard_ready[1]["value"][0][0])
                self.assertIn("storyboard_", storyboard_ready[2]["value"])
                self.assertIn("分镜墙", storyboard_ready[38]["value"])
                self.assertTrue(storyboard_ready[39]["visible"])
                self.assertEqual(storyboard_ready[40], 1)
                self.assertEqual(storyboard_ready[41], 1)
                self.assertEqual(len(storyboard.load_storyboards()), 1)
                self.assertIn("共 1 个分镜", _storyboard_summary_html(1, {"__lang": "cn"}))

                image_changed = _storyboard_cell_image_changed({"__lang": "cn"}, 1, Image.new("RGB", (6, 6), "blue"), 0)
                self.assertEqual(len(image_changed), STORYBOARD_PANEL_OUTPUT_COUNT)
                self.assertIn("图片已更新", image_changed[38]["value"])
                self.assertIn("storyboard_", image_changed[1]["value"])

                audio_file = Path(tempdir) / "storyboard-test.wav"
                audio_file.write_bytes(b"RIFF\x24\x00\x00\x00WAVEfmt ")
                audio_changed = _storyboard_cell_audio_changed({"__lang": "cn"}, 1, str(audio_file), 0)
                self.assertIn("音频已更新", audio_changed[38]["value"])
                self.assertTrue(Path(storyboard.load_storyboards()[0]["audio_path"]).is_file())

                annotation_changed = _storyboard_cell_annotation_changed({"__lang": "cn"}, 1, "镜头注释", 0)
                self.assertEqual(storyboard.load_storyboards()[0]["description"], "镜头注释")
                self.assertIn("注释已保存", annotation_changed[38]["value"])

                added_blank = _storyboard_add_blank_clicked({"__lang": "cn"})
                self.assertEqual(added_blank[39], 1)
                self.assertIn("已添加空白分镜 #2", added_blank[38]["value"])
                moved_audio = _storyboard_move_audio_clicked({"__lang": "cn"}, 1, 2)
                self.assertIn("音频已移动到分镜 #2", moved_audio[38]["value"])
                self.assertIsNone(storyboard.load_storyboards()[0].get("audio_path"))
                self.assertTrue(storyboard.load_storyboards()[1].get("audio_path"))
                deleted_audio = _storyboard_delete_audio_clicked({"__lang": "cn"}, 2)
                self.assertIn("音频已删除", deleted_audio[38]["value"])
                self.assertIsNone(storyboard.load_storyboards()[1].get("audio_path"))

                moved_frame = _storyboard_move_frame_clicked({"__lang": "cn"}, 2, 1)
                self.assertIn("分镜已移动到 #1", moved_frame[38]["value"])
                self.assertEqual(len(storyboard.load_storyboards()), 2)
                deleted_frame = _storyboard_delete_frame_clicked({"__lang": "cn"}, 1)
                self.assertIn("分镜已删除", deleted_frame[38]["value"])
                self.assertEqual(len(storyboard.load_storyboards()), 1)

                cell_deleted = _storyboard_cell_delete_clicked({"__lang": "cn"}, 1, 0)
                self.assertIn("已清空", cell_deleted[38]["value"])
                self.assertEqual(storyboard.load_storyboards()[0].get("description"), "")

                exported = _storyboard_export_clicked({"__lang": "cn"})
                self.assertTrue(Path(exported[0]).is_file())
                self.assertEqual(Path(exported[0]).suffix, ".zip")
                self.assertIn("分镜已导出", exported[39]["value"])
                with zipfile.ZipFile(exported[0]) as archive:
                    names = archive.namelist()
                    self.assertIn("storyboard.json", names)
                    self.assertIn("storyboard_content.txt", names)
                cleared = _storyboard_clear_clicked({"__lang": "cn"})
                self.assertEqual(storyboard.load_storyboards(), [])
                self.assertIn("已清空 1 个分镜", cleared[38]["value"])
        finally:
            storyboard.outputs_dir = old_outputs_dir

        with tempfile.TemporaryDirectory() as tmp:
            opened_folders = []
            folder_status = _open_output_folder_clicked({"__lang": "cn"}, tmp, opener=opened_folders.append)
            self.assertEqual(opened_folders, [str(Path(tmp))])
            self.assertTrue(folder_status["visible"])
            self.assertIn("forge-neo-output-status", folder_status["value"])
            self.assertIn("已打开", folder_status["value"])

