        self.assertIn("const point = self.canvasPointFromEvent(drawingCanvas, e);", js_content)
        self.assertIn("this.canvasDisplayScale(canvas)", js_content)
        self.assertIn('image.style.setProperty("width", `${scaledWidth}px`, "important");', js_content)
        self.assertIn('drawingCanvas.style.setProperty("width", `${scaledWidth}px`, "important");', js_content)
        self.assertIn('drawingCanvas.style.setProperty("height", `${scaledHeight}px`, "important");', js_content)
